(400724,44525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daireyi ... ve balkondan nefret etseler, emlakçının günü tamamen mahvolurdu!'::text,'gezseler'::text,'gezerler'::text,'gezerlerdi'::text,'Daireyi gezseler ve balkondan nefret etseler, emlakçının günü tamamen mahvolurdu!'::text),
