(400733,44526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, söylenene göre bu ikisi anahtarları almadan önce daire on çift tarafından ...'::text,'gezilmiş'::text,'gezmiş'::text,'geziliyor'::text,'Yok artık, söylenene göre bu ikisi anahtarları almadan önce daire on çift tarafından gezilmiş.'::text),
