(400739,44527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, il paraît qu''ils ... l''appartement seulement cinq minutes avant de le prendre.'::text,'ont visité'::text,'ont été visités'::text,'visitant'::text,'Ma bestie, il paraît qu''ils ont visité l''appartement seulement cinq minutes avant de le prendre.'::text),
(400742,44527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre daireyi almadan önce sadece beş dakika ...'::text,'gezmişler'::text,'gezilmişler'::text,'gezerek'::text,'Kanka, duyduğuma göre daireyi almadan önce sadece beş dakika gezmişler.'::text),
