(342482,38054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il se met sous la clim, l''air froid le ... vite.'::text,'rafraîchira'::text,'rafraîchirait'::text,'a rafraîchi'::text,'S''il se met sous la clim, l''air froid le rafraîchira vite.'::text),
(342485,38054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klimanın altına geçerse soğuk hava onu çabucak ...'::text,'serinletecek'::text,'serinletirdi'::text,'serinletti'::text,'Klimanın altına geçerse soğuk hava onu çabucak serinletecek.'::text),
(342486,38054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha beáll a klíma alá, a hideg levegő gyorsan ...'::text,'lehűti'::text,'lehűtené'::text,'lehűtötte'::text,'Ha beáll a klíma alá, a hideg levegő gyorsan lehűti.'::text),
(342489,38055,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, wenn ich deine Fernbedienungs-Skills hätte, ... ich auch so schnell abkühlen.'::text,'würde'::text,'werde'::text,'kühle'::text,'Ganz ehrlich, wenn ich deine Fernbedienungs-Skills hätte, würde ich auch so schnell abkühlen.'::text),
(342493,38055,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я так вправно, як ти, орудував пультом, я теж ... так швидко.'::text,'охолов би'::text,'охолону'::text,'охолоджуюсь'::text,'Чесно, якби я так вправно, як ти, орудував пультом, я теж охолов би так швидко.'::text),
(342492,38055,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, si tuviera tu habilidad con el mando, yo también me ... así de rápido.'::text,'refrescaría'::text,'refrescaré'::text,'refresco'::text,'No te voy a mentir, si tuviera tu habilidad con el mando, yo también me refrescaría así de rápido.'::text),
(342491,38055,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, si j''avais ton talent avec la télécommande, moi aussi je me ... aussi vite.'::text,'rafraîchirais'::text,'rafraîchirai'::text,'rafraîchis'::text,'Je vais pas mentir, si j''avais ton talent avec la télécommande, moi aussi je me rafraîchirais aussi vite.'::text),
(342494,38055,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, senin kumanda becerin bende olsa ben de o kadar hızlı ...'::text,'serinlerdim'::text,'serinleyeceğim'::text,'serinlerim'::text,'Yalan yok, senin kumanda becerin bende olsa ben de o kadar hızlı serinlerdim.'::text),
(342495,38055,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ha olyan ügyes lennék a távirányítóval, mint te, én is ilyen gyorsan ...'::text,'lehűlnék'::text,'lehűlök'::text,'lehűlök'::text,'Nem hazudok, ha olyan ügyes lennék a távirányítóval, mint te, én is ilyen gyorsan lehűlnék.'::text),
(342498,38056,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast zugegeben, dass du den Raum viel zu sehr ... hast, und ehrlich, das ist ikonisch.'::text,'runtergekühlt'::text,'runterkühlen'::text,'runtergekühlt'::text,'Du hast zugegeben, dass du den Raum viel zu sehr runtergekühlt hast, und ehrlich, das ist ikonisch.'::text),
(342502,38056,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти зізнався, що ... кімнату надто сильно, і чесно, це культово.'::text,'охолодив'::text,'охолодити'::text,'охолодив'::text,'Ти зізнався, що охолодив кімнату надто сильно, і чесно, це культово.'::text),
(342501,38056,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitiste ... demasiado la habitación y, sinceramente, eso es icónico.'::text,'haber enfriado'::text,'enfriar'::text,'enfriaste'::text,'Admitiste haber enfriado demasiado la habitación y, sinceramente, eso es icónico.'::text),
(342500,38056,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as avoué ... trop la pièce, et franchement, c''est iconique.'::text,'avoir refroidi'::text,'refroidir'::text,'as refroidi'::text,'Tu as avoué avoir refroidi trop la pièce, et franchement, c''est iconique.'::text),
(342503,38056,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Odayı fazla ... itiraf ettin, açıkçası bu efsane.'::text,'soğuttuğunu'::text,'soğutmayı'::text,'soğuttun'::text,'Odayı fazla soğuttuğunu itiraf ettin, açıkçası bu efsane.'::text),
(342504,38056,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerted, hogy túlságosan ... a szobát, és őszintén, ez ikonikus.'::text,'lehűtötted'::text,'lehűteni'::text,'lehűtötted'::text,'Beismerted, hogy túlságosan lehűtötted a szobát, és őszintén, ez ikonikus.'::text),
(342507,38057,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... den Raum früher runterkühlen sollen, aber die Rettung war smooth.'::text,'hättest'::text,'musstest'::text,'konntest nicht'::text,'Ehrlich, du hättest den Raum früher runterkühlen sollen, aber die Rettung war smooth.'::text),
(342511,38057,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ... кімнату раніше, але цей порятунок був елегантним.'::text,'тобі варто було охолодити'::text,'ти, мабуть, охолодив'::text,'ти не міг охолодити'::text,'Чесно, тобі варто було охолодити кімнату раніше, але цей порятунок був елегантним.'::text),
(342510,38057,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... la habitación antes, pero esa recuperación fue impecable.'::text,'deberías haber enfriado'::text,'debiste de enfriar'::text,'no pudiste haber enfriado'::text,'Sinceramente, deberías haber enfriado la habitación antes, pero esa recuperación fue impecable.'::text),
(342509,38057,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... la pièce plus tôt, mais ce rattrapage était stylé.'::text,'aurais dû refroidir'::text,'as dû refroidir'::text,'n''as pas pu refroidir'::text,'Franchement, tu aurais dû refroidir la pièce plus tôt, mais ce rattrapage était stylé.'::text),
(342512,38057,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası odayı daha önce ..., ama o toparlanış çok şıktı.'::text,'soğutmalıydın'::text,'soğutmuş olmalısın'::text,'soğutmuş olamazsın'::text,'Açıkçası odayı daha önce soğutmalıydın, ama o toparlanış çok şıktı.'::text),
(342513,38057,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, korábban ... a szobát, de az a mentés nagyon profi volt.'::text,'le kellett volna hűtened'::text,'biztos lehűtötted'::text,'nem hűthetted le'::text,'Őszintén, korábban le kellett volna hűtened a szobát, de az a mentés nagyon profi volt.'::text),
(342525,38059,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, er ... den Raum früher gekühlt. Ein leicht warmer Nachmittag, könnte schlimmer sein.'::text,'hätte'::text,'kühlte'::text,'würde'::text,'Er wünschte, er hätte den Raum früher gekühlt. Ein leicht warmer Nachmittag, könnte schlimmer sein.'::text),
(342529,38059,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому б хотілося, щоб він ... кімнату раніше. Трохи тепленький день, могло бути й гірше.'::text,'охолодив'::text,'охолодив'::text,'охолоджував би'::text,'Йому б хотілося, щоб він охолодив кімнату раніше. Трохи тепленький день, могло бути й гірше.'::text),
(342528,38059,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía ... la habitación antes. Una tarde un poco calurosa, podría ser peor.'::text,'haber enfriado'::text,'enfriar'::text,'enfriar'::text,'Él desearía haber enfriado la habitación antes. Una tarde un poco calurosa, podría ser peor.'::text),
(342527,38059,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... la pièce plus tôt. Un après-midi un peu chaud, ça pourrait être pire.'::text,'avoir refroidi'::text,'refroidir'::text,'refroidir'::text,'Il aimerait avoir refroidi la pièce plus tôt. Un après-midi un peu chaud, ça pourrait être pire.'::text),
(342530,38059,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke odayı daha önce ... diye düşünüyor. Biraz sıcak bir öğleden sonra, daha kötüsü olabilirdi.'::text,'soğutsaydı'::text,'soğutsa'::text,'soğutacak'::text,'Keşke odayı daha önce soğutsaydı diye düşünüyor. Biraz sıcak bir öğleden sonra, daha kötüsü olabilirdi.'::text),
(342531,38059,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak korábban ... a szobát. Kicsit meleg délután, lehetne rosszabb is.'::text,'lehűtötte volna'::text,'lehűtené'::text,'lehűtené'::text,'Azt kívánja, bárcsak korábban lehűtötte volna a szobát. Kicsit meleg délután, lehetne rosszabb is.'::text),
(342534,38060,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Zeitschrift, ... Luftzug ihn nicht kühlen konnte, war natürlich eine super Wahl.'::text,'deren'::text,'die'::text,'die'::text,'Die Zeitschrift, deren Luftzug ihn nicht kühlen konnte, war natürlich eine super Wahl.'::text),
(342538,38060,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Журнал, ... вітерець не міг його охолодити, був чудовим вибором, звісно.'::text,'чий'::text,'який'::text,'який'::text,'Журнал, чий вітерець не міг його охолодити, був чудовим вибором, звісно.'::text),
(342537,38060,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La revista, ... brisa no podía refrescarlo, fue una gran elección, obviamente.'::text,'cuya'::text,'que'::text,'que'::text,'La revista, cuya brisa no podía refrescarlo, fue una gran elección, obviamente.'::text),
(342536,38060,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le magazine, ... la brise ne pouvait pas le rafraîchir, était un super choix, évidemment.'::text,'dont'::text,'qui'::text,'que'::text,'Le magazine, dont la brise ne pouvait pas le rafraîchir, était un super choix, évidemment.'::text),
(342539,38060,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki, ... onu serinletemeyen dergi harika bir seçimdi.'::text,'esintisi'::text,NULL::text,NULL::text,'Tabii ki, esintisi onu serinletemeyen dergi harika bir seçimdi.'::text),
(342540,38060,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A magazin, ... szellője nem tudta lehűteni, nyilván remek választás volt.'::text,'amelynek a'::text,'amely'::text,'amely'::text,'A magazin, amelynek a szellője nem tudta lehűteni, nyilván remek választás volt.'::text),
(342543,38061,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Zeitschrift konnte er sich nicht abkühlen und hatte das Gefühl, komplett zu schmelzen!'::text,'Trotz'::text,'Obwohl'::text,'Außer wenn'::text,'Trotz der Zeitschrift konnte er sich nicht abkühlen und hatte das Gefühl, komplett zu schmelzen!'::text),
(342547,38061,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... журнал, він не міг охолонути й відчував, що просто тане!'::text,'Попри'::text,'Хоча'::text,'Якщо не'::text,'Попри журнал, він не міг охолонути й відчував, що просто тане!'::text),
(342546,38061,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... la revista, no podía refrescarse y sentía que se estaba derritiendo por completo!'::text,'A pesar de'::text,'Aunque'::text,'A menos que'::text,'¡A pesar de la revista, no podía refrescarse y sentía que se estaba derritiendo por completo!'::text),
(342545,38061,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le magazine, il n''arrivait pas à se rafraîchir et avait l''impression de fondre complètement !'::text,'Malgré'::text,'Bien que'::text,'À moins que'::text,'Malgré le magazine, il n''arrivait pas à se rafraîchir et avait l''impression de fondre complètement !'::text),
(342548,38061,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dergiye ... serinleyemedi ve resmen eriyormuş gibi hissetti!'::text,'rağmen'::text,'her ne kadar'::text,'olmadıkça'::text,'Dergiye rağmen serinleyemedi ve resmen eriyormuş gibi hissetti!'::text),
(342549,38061,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A magazin ... sem tudott lehűlni, és úgy érezte, teljesen elolvad!'::text,'ellenére'::text,'bár'::text,'hacsak nem'::text,'A magazin ellenére sem tudott lehűlni, és úgy érezte, teljesen elolvad!'::text),
(342552,38062,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Abendessen ... die Klimaanlage die Wohnung komplett runtergekühlt haben, sonst ist das eine totale Katastrophe!'::text,'wird'::text,'wird'::text,'kühlt'::text,'Bis zum Abendessen wird die Klimaanlage die Wohnung komplett runtergekühlt haben, sonst ist das eine totale Katastrophe!'::text),
(342556,38062,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечері кондиціонер ... квартиру повністю, інакше це повна катастрофа!'::text,'охолодить'::text,'охолодить'::text,'охолоджує'::text,'До вечері кондиціонер охолодить квартиру повністю, інакше це повна катастрофа!'::text),
(342555,38062,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para la cena, el aire acondicionado ... el piso por completo, o esto es un desastre total!'::text,'habrá enfriado'::text,'enfriará'::text,'enfría'::text,'¡Para la cena, el aire acondicionado habrá enfriado el piso por completo, o esto es un desastre total!'::text),
(342554,38062,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le dîner, la clim ... l''appartement complètement, sinon c''est la cata totale !'::text,'aura refroidi'::text,'refroidira'::text,'refroidit'::text,'D''ici le dîner, la clim aura refroidi l''appartement complètement, sinon c''est la cata totale !'::text),
(342557,38062,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam yemeğine kadar klima daireyi tamamen ..., yoksa bu tam bir felaket!'::text,'soğutmuş olacak'::text,'soğutacak'::text,'soğutuyor'::text,'Akşam yemeğine kadar klima daireyi tamamen soğutmuş olacak, yoksa bu tam bir felaket!'::text),
(342558,38062,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vacsorára a klíma teljesen ... a lakást, különben ez totális katasztrófa!'::text,'lehűti'::text,'lehűti'::text,'hűti'::text,'Vacsorára a klíma teljesen lehűti a lakást, különben ez totális katasztrófa!'::text),
(355764,39530,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich gerade ein kaltes Glas an die Stirn, als er zur Klimaanlage hochsah.'::text,'drückte'::text,'drückte'::text,'hat gedrückt'::text,'Er drückte sich gerade ein kaltes Glas an die Stirn, als er zur Klimaanlage hochsah.'::text),
(355768,39530,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... холодну склянку до чола, коли подивився на кондиціонер.'::text,'притискав'::text,'притиснув'::text,'притиснув'::text,'Він притискав холодну склянку до чола, коли подивився на кондиціонер.'::text),
(355767,39530,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un vaso frío contra la frente cuando miró hacia el aire acondicionado.'::text,'Se estaba apretando'::text,'Se apretó'::text,'Se ha apretado'::text,'Se estaba apretando un vaso frío contra la frente cuando miró hacia el aire acondicionado.'::text),
(355766,39530,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... un verre froid contre son front quand il a levé les yeux vers la clim.'::text,'pressait'::text,'a pressé'::text,'a pressé'::text,'Il pressait un verre froid contre son front quand il a levé les yeux vers la clim.'::text),
(355769,39530,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klimaya baktığında soğuk bir bardağı alnına ...'::text,'bastırıyordu'::text,'bastırdı'::text,'bastırdı'::text,'Klimaya baktığında soğuk bir bardağı alnına bastırıyordu.'::text),
(355770,39530,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp egy hideg poharat ... a homlokához, amikor felnézett a klímára.'::text,'szorított'::text,'odaszorította'::text,'odaszorította'::text,'Épp egy hideg poharat szorított a homlokához, amikor felnézett a klímára.'::text),
(355782,39532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Typ ... sich gerade ein kaltes Glas über die Stirn, als er endlich die Fernbedienung fand.'::text,'rollte'::text,'rollte'::text,'hat gerollt'::text,'Bro, der Typ rollte sich gerade ein kaltes Glas über die Stirn, als er endlich die Fernbedienung fand.'::text),
(355786,39532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей чувак ... холодну склянку по лобі, коли нарешті знайшов пульт.'::text,'качав'::text,'прокачав'::text,'прокачав'::text,'Бро, цей чувак качав холодну склянку по лобі, коли нарешті знайшов пульт.'::text),
(355785,39532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el tío se ... un vaso frío por la frente cuando por fin encontró el mando.'::text,'estaba pasando'::text,'pasó'::text,'ha pasado'::text,'Bro, el tío se estaba pasando un vaso frío por la frente cuando por fin encontró el mando.'::text),
(355784,39532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le mec ... un verre froid sur son front quand il a enfin trouvé la télécommande.'::text,'faisait rouler'::text,'a fait rouler'::text,'a fait rouler'::text,'Frère, le mec faisait rouler un verre froid sur son front quand il a enfin trouvé la télécommande.'::text),
(355787,39532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, adam sonunda kumandayı bulduğunda soğuk bir bardağı alnında ...'::text,'yuvarlıyordu'::text,'yuvarladı'::text,'yuvarladı'::text,'Kanka, adam sonunda kumandayı bulduğunda soğuk bir bardağı alnında yuvarlıyordu.'::text),
(355788,39532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a csávó épp egy hideg poharat ... a homlokán, amikor végre megtalálta a távirányítót.'::text,'görgetett'::text,'végiggörgetett'::text,'végiggörgetett'::text,'Tesó, a csávó épp egy hideg poharat görgetett a homlokán, amikor végre megtalálta a távirányítót.'::text),
(355791,39533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er ... das Glas schon so zehn Minuten über die Stirn, ohne Witz.'::text,'rollt'::text,'rollte'::text,'rollt'::text,'Bro, er rollt das Glas schon so zehn Minuten über die Stirn, ohne Witz.'::text),
(355795,39533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... ту склянку по лобі вже хвилин десять, без брехні.'::text,'качає'::text,'качав'::text,'качає'::text,'Бро, він качає ту склянку по лобі вже хвилин десять, без брехні.'::text),
(355794,39533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... ese vaso por la frente como diez minutos, en serio.'::text,'lleva pasándose'::text,'se pasó'::text,'se está pasando'::text,'Bro, lleva pasándose ese vaso por la frente como diez minutos, en serio.'::text),
(355793,39533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ça fait genre dix minutes qu''il ... ce verre sur son front, sans mentir.'::text,'fait rouler'::text,'a fait rouler'::text,'fait rouler'::text,'Frère, ça fait genre dix minutes qu''il fait rouler ce verre sur son front, sans mentir.'::text),
(355796,39533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, on dakikadır falan o bardağı alnında ..., yemin ederim.'::text,'yuvarlıyor'::text,'yuvarladı'::text,'yuvarlıyor'::text,'Kanka, on dakikadır falan o bardağı alnında yuvarlıyor, yemin ederim.'::text),
(355797,39533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, már vagy tíz perce ... azt a poharat a homlokán, komolyan.'::text,'görgeti'::text,'görgette'::text,'görgeti'::text,'Tesó, már vagy tíz perce görgeti azt a poharat a homlokán, komolyan.'::text),
(355800,39534,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 14 Uhr ... die Hitze seine Stirn nass gemacht, also wurde das Meeting abgesagt.'::text,'hatte'::text,'hat'::text,'macht'::text,'Bis 14 Uhr hatte die Hitze seine Stirn nass gemacht, also wurde das Meeting abgesagt.'::text),
(355804,39534,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 14:00 спека вже ... йому чоло мокрим, тож нараду скасували.'::text,'зробила'::text,'зробила'::text,'робить'::text,'До 14:00 спека вже зробила йому чоло мокрим, тож нараду скасували.'::text),
(355803,39534,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 14:00, el calor ya le ... la frente mojada, así que se canceló la reunión.'::text,'había dejado'::text,'ha dejado'::text,'deja'::text,'Para las 14:00, el calor ya le había dejado la frente mojada, así que se canceló la reunión.'::text),
(355802,39534,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 14 h, la chaleur lui ... le front, donc la réunion a été annulée.'::text,'avait trempé'::text,'a trempé'::text,'trempe'::text,'À 14 h, la chaleur lui avait trempé le front, donc la réunion a été annulée.'::text),
(355805,39534,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 14.00''e kadar sıcak alnını çoktan ..., bu yüzden toplantı iptal edildi.'::text,'ıslatmıştı'::text,'ıslattı'::text,'ıslatıyor'::text,'Saat 14.00''e kadar sıcak alnını çoktan ıslatmıştı, bu yüzden toplantı iptal edildi.'::text),
(355806,39534,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délután 2-re a hőség már ... a homlokát, így a megbeszélést lemondták.'::text,'átáztatta'::text,'átáztatta'::text,'áztatja'::text,'Délután 2-re a hőség már átáztatta a homlokát, így a megbeszélést lemondták.'::text),
(355809,39535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das Glas auf die Stirn legt, ... seine Stirn kalt, weil das Glas kalt ist.'::text,'wird'::text,'wäre'::text,'war'::text,'Wenn er das Glas auf die Stirn legt, wird seine Stirn kalt, weil das Glas kalt ist.'::text),
(355813,39535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він прикладе склянку до чола, його чоло ... холодним, бо склянка холодна.'::text,'буде'::text,'було б'::text,'було'::text,'Якщо він прикладе склянку до чола, його чоло буде холодним, бо склянка холодна.'::text),
(355812,39535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se pone el vaso en la frente, la frente ... fría, porque el vaso está frío.'::text,'estará'::text,'estaría'::text,'estuvo'::text,'Si se pone el vaso en la frente, la frente estará fría, porque el vaso está frío.'::text),
(355811,39535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il met le verre sur son front, son front ... froid, parce que le verre est froid.'::text,'sera'::text,'serait'::text,'était'::text,'S''il met le verre sur son front, son front sera froid, parce que le verre est froid.'::text),
(355814,39535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bardağı alnına koyarsa alnı soğuk ..., çünkü bardak soğuk.'::text,'olacak'::text,'olurdu'::text,'oldu'::text,'Bardağı alnına koyarsa alnı soğuk olacak, çünkü bardak soğuk.'::text),
(355815,39535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a homlokára teszi a poharat, a homloka hideg ..., mert a pohár hideg.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha a homlokára teszi a poharat, a homloka hideg lesz, mert a pohár hideg.'::text),
(355818,39536,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In ... des Nachmittags drückt sich das Subjekt ein kaltes Glas an die Stirn.'::text,'der Hitze'::text,'einer Hitze'::text,'Hitze'::text,'In der Hitze des Nachmittags drückt sich das Subjekt ein kaltes Glas an die Stirn.'::text),
(355822,39536,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У пообідню ... суб''єкт притискає холодну склянку до чола.'::text,'спеку'::text,'спеку'::text,'спеку'::text,'У пообідню спеку суб''єкт притискає холодну склянку до чола.'::text),
(355821,39536,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ... de la tarde, el sujeto se aprieta un vaso frío contra la frente.'::text,'el calor'::text,'un calor'::text,'calor'::text,'En el calor de la tarde, el sujeto se aprieta un vaso frío contra la frente.'::text),
(355820,39536,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans ... de l''après-midi, le sujet presse un verre froid contre son front.'::text,'la chaleur'::text,'une chaleur'::text,'chaleur'::text,'Dans la chaleur de l''après-midi, le sujet presse un verre froid contre son front.'::text),
(355823,39536,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğleden sonranın ... denek soğuk bir bardağı alnına bastırıyor.'::text,'sıcağında'::text,'bir sıcağında'::text,'sıcağında'::text,'Öğleden sonranın sıcağında denek soğuk bir bardağı alnına bastırıyor.'::text),
(355824,39536,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A délután ... az alany egy hideg poharat nyom a homlokához.'::text,'hőségében'::text,'egy hőségében'::text,'hőségében'::text,'A délután hőségében az alany egy hideg poharat nyom a homlokához.'::text),
(355827,39537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wusste, das kalte Glas ... für seine Stirn nicht ausreichen. Toller Plan, offensichtlich.'::text,'würde'::text,'wird'::text,'reicht'::text,'Er wusste, das kalte Glas würde für seine Stirn nicht ausreichen. Toller Plan, offensichtlich.'::text),
(355831,39537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він знав, що холодна склянка ... достатньою для його чола. Геніальний план, звісно.'::text,'не буде'::text,'не буде'::text,'не є'::text,'Він знав, що холодна склянка не буде достатньою для його чола. Геніальний план, звісно.'::text),
(355830,39537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que el vaso frío no ... suficiente para su frente. Gran plan, obviamente.'::text,'sería'::text,'será'::text,'es'::text,'Sabía que el vaso frío no sería suficiente para su frente. Gran plan, obviamente.'::text),
(355829,39537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il savait que le verre froid ne ... pas assez pour son front. Super plan, évidemment.'::text,'suffirait'::text,'suffira'::text,'suffit'::text,'Il savait que le verre froid ne suffirait pas assez pour son front. Super plan, évidemment.'::text),
(355832,39537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soğuk bardağın alnı için yeterli ... biliyordu. Harika plan, tabii ki.'::text,'olmayacağını'::text,'olmayacağını'::text,'olmadığını'::text,'Soğuk bardağın alnı için yeterli olmayacağını biliyordu. Harika plan, tabii ki.'::text),
(355833,39537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a hideg pohár nem ... elég a homlokának. Remek terv, nyilván.'::text,'lesz'::text,'lesz'::text,NULL::text,'Tudta, hogy a hideg pohár nem lesz elég a homlokának. Remek terv, nyilván.'::text),
(355845,39539,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er die Fernbedienung fand, ... seine Stirn schon eine Stunde lang geschwitzt. Perfektes Timing, offensichtlich.'::text,'hatte'::text,'hat'::text,'schwitzt'::text,'Als er die Fernbedienung fand, hatte seine Stirn schon eine Stunde lang geschwitzt. Perfektes Timing, offensichtlich.'::text),
(355849,39539,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він знайшов пульт, його чоло ... вже годину. Ідеальний таймінг, звісно.'::text,'пітніло'::text,'пітніє'::text,'пітніє'::text,'Поки він знайшов пульт, його чоло пітніло вже годину. Ідеальний таймінг, звісно.'::text),
(355848,39539,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando encontró el mando, su frente ... una hora. Timing perfecto, obviamente.'::text,'llevaba sudando'::text,'lleva sudando'::text,'está sudando'::text,'Cuando encontró el mando, su frente llevaba sudando una hora. Timing perfecto, obviamente.'::text),
(355847,39539,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a trouvé la télécommande, son front ... depuis une heure. Timing parfait, évidemment.'::text,'transpirait'::text,'transpire'::text,'transpire'::text,'Quand il a trouvé la télécommande, son front transpirait depuis une heure. Timing parfait, évidemment.'::text),
(355850,39539,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kumandayı bulduğunda alnı bir saattir ... zaten. Mükemmel zamanlama, tabii ki.'::text,'terliyordu'::text,'terliyor'::text,'terliyor'::text,'Kumandayı bulduğunda alnı bir saattir terliyordu zaten. Mükemmel zamanlama, tabii ki.'::text),
(355851,39539,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megtalálta a távirányítót, a homloka ... már egy órája. Tökéletes időzítés, nyilván.'::text,'izzadt'::text,'izzad'::text,'izzad'::text,'Mire megtalálta a távirányítót, a homloka izzadt már egy órája. Tökéletes időzítés, nyilván.'::text),
(355854,39540,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sobald er das Gerät einschaltet, ... die kalte Luft seine Stirn kühlen.'::text,'wird'::text,'kühlte'::text,'würde'::text,'Sobald er das Gerät einschaltet, wird die kalte Luft seine Stirn kühlen.'::text),
(355858,39540,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно він увімкне кондиціонер, холодне повітря ... йому чоло.'::text,'охолодить'::text,'охолодило'::text,'охолодило б'::text,'Щойно він увімкне кондиціонер, холодне повітря охолодить йому чоло.'::text),
(355857,39540,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En cuanto encienda el aparato, el aire frío le ... la frente.'::text,'refrescará'::text,'refrescó'::text,'refrescaría'::text,'En cuanto encienda el aparato, el aire frío le refrescará la frente.'::text),
(355856,39540,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dès qu''il allumera l''appareil, l''air froid lui ... le front.'::text,'rafraîchira'::text,'a rafraîchi'::text,'rafraîchirait'::text,'Dès qu''il allumera l''appareil, l''air froid lui rafraîchira le front.'::text),
(355859,39540,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cihazı açar açmaz soğuk hava alnını ...'::text,'serinletecek'::text,'serinletti'::text,'serinletirdi'::text,'Cihazı açar açmaz soğuk hava alnını serinletecek.'::text),
(355860,39540,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amint bekapcsolja a készüléket, a hideg levegő ... a homlokát.'::text,'lehűti'::text,'lehűtötte'::text,'lehűtené'::text,'Amint bekapcsolja a készüléket, a hideg levegő lehűti a homlokát.'::text),
(373737,41527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er wieder Flugzeuge am Zaun fotografieren, total besessen!'::text,'wird'::text,'wird'::text,'fotografiert'::text,'Morgen um diese Zeit wird er wieder Flugzeuge am Zaun fotografieren, total besessen!'::text),
(373741,41527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час він знову ... літаки біля паркану, повністю одержимий!'::text,'фотографуватиме'::text,'сфотографує'::text,'фотографує'::text,'Завтра в цей час він знову фотографуватиме літаки біля паркану, повністю одержимий!'::text),
(373740,41527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mañana a esta hora ... aviones otra vez en la valla, totalmente obsesionado!'::text,'estará fotografiando'::text,'fotografiará'::text,'fotografía'::text,'¡Mañana a esta hora estará fotografiando aviones otra vez en la valla, totalmente obsesionado!'::text),
(373739,41527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... encore des avions au grillage, complètement obsédé !'::text,'sera en train de photographier'::text,'photographiera'::text,'photographie'::text,'Demain à la même heure, il sera en train de photographier encore des avions au grillage, complètement obsédé !'::text),
(373742,41527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine çitin yanında uçakların fotoğrafını ..., tamamen takıntılı!'::text,'çekiyor olacak'::text,'çekecek'::text,'çekiyor'::text,'Yarın bu saatlerde yine çitin yanında uçakların fotoğrafını çekiyor olacak, tamamen takıntılı!'::text),
(373743,41527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint a kerítésnél ... a gépeket, teljesen megszállottan!'::text,'fogja fotózni'::text,'lefotózza'::text,'fotózza'::text,'Holnap ilyenkor megint a kerítésnél fogja fotózni a gépeket, teljesen megszállottan!'::text),
(373746,41528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er ein längeres Objektiv hätte, ... er das Flugzeug aus noch größerer Entfernung fotografieren.'::text,'würde'::text,'wird'::text,'fotografierte'::text,'Wenn er ein längeres Objektiv hätte, würde er das Flugzeug aus noch größerer Entfernung fotografieren.'::text),
(373750,41528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він мав довший об''єктив, він ... літак з ще більшої відстані.'::text,'сфотографував би'::text,'сфотографує'::text,'сфотографував'::text,'Якби він мав довший об''єктив, він сфотографував би літак з ще більшої відстані.'::text),
(373749,41528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tuviera un objetivo más largo, ... el avión desde aún más lejos.'::text,'fotografiaría'::text,'fotografiará'::text,'fotografió'::text,'Si tuviera un objetivo más largo, fotografiaría el avión desde aún más lejos.'::text),
(373748,41528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait un objectif plus long, il ... l''avion d''encore plus loin.'::text,'photographierait'::text,'photographiera'::text,'a photographié'::text,'S''il avait un objectif plus long, il photographierait l''avion d''encore plus loin.'::text),
(373751,41528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha uzun bir objektifi olsa uçağın fotoğrafını daha da uzaktan ...'::text,'çekerdi'::text,'çekecek'::text,'çekti'::text,'Daha uzun bir objektifi olsa uçağın fotoğrafını daha da uzaktan çekerdi.'::text),
(373752,41528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha hosszabb objektívje lenne, még messzebbről ... a gépet.'::text,'lefotózná'::text,'lefotózza'::text,'lefotózta'::text,'Ha hosszabb objektívje lenne, még messzebbről lefotózná a gépet.'::text),
(373755,41529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krass, es heißt, dass der grüne Jet diese Woche zehnmal von ihm ...!'::text,'fotografiert worden ist'::text,'fotografierte'::text,'hat fotografiert'::text,'Krass, es heißt, dass der grüne Jet diese Woche zehnmal von ihm fotografiert worden ist!'::text),
(373759,41529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, той зелений літак цього тижня ... ним десять разів!'::text,'був сфотографований'::text,'сфотографував'::text,'сфотографував'::text,'Та ну, кажуть, той зелений літак цього тижня був сфотографований ним десять разів!'::text),
(373758,41529,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No puede ser, dicen que ese avión verde ... por él diez veces esta semana!'::text,'ha sido fotografiado'::text,'fotografió'::text,'ha fotografiado'::text,'¡No puede ser, dicen que ese avión verde ha sido fotografiado por él diez veces esta semana!'::text),
(373757,41529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, il paraît que cet avion vert ... par lui dix fois cette semaine !'::text,'a été photographié'::text,'a photographié'::text,'a photographié'::text,'Sérieux, il paraît que cet avion vert a été photographié par lui dix fois cette semaine !'::text),
(373760,41529,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok artık, dediklerine göre o yeşil jet bu hafta onun tarafından on kez ...!'::text,'fotoğraflanmış'::text,'fotoğrafladı'::text,'fotoğraflamış'::text,'Yok artık, dediklerine göre o yeşil jet bu hafta onun tarafından on kez fotoğraflanmış!'::text),
(373761,41529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, állítólag az a zöld gép ezen a héten tízszer ... általa!'::text,'le lett fotózva'::text,'lefotózta'::text,'lefotózta'::text,'Ne már, állítólag az a zöld gép ezen a héten tízszer le lett fotózva általa!'::text),
(373764,41530,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann ... den grün-weißen Jet, als er über den Zaun flog.'::text,'fotografierte'::text,'wurde fotografiert'::text,'fotografierend'::text,'Der Mann fotografierte den grün-weißen Jet, als er über den Zaun flog.'::text),
(373768,41530,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік ... зелено-білий літак, коли той пролітав над парканом.'::text,'сфотографував'::text,'був сфотографований'::text,'фотографуючи'::text,'Чоловік сфотографував зелено-білий літак, коли той пролітав над парканом.'::text),
(373767,41530,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre ... el avión verde y blanco cuando pasó sobre la valla.'::text,'fotografió'::text,'fue fotografiado'::text,'fotografiando'::text,'El hombre fotografió el avión verde y blanco cuando pasó sobre la valla.'::text),
(373766,41530,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme ... l''avion vert et blanc quand il est passé au-dessus du grillage.'::text,'a photographié'::text,'a été photographié'::text,'photographiant'::text,'L''homme a photographié l''avion vert et blanc quand il est passé au-dessus du grillage.'::text),
(373769,41530,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam yeşil-beyaz jeti çitin üstünden geçerken ...'::text,'fotoğrafladı'::text,'fotoğraflandı'::text,'fotoğraflayarak'::text,'Adam yeşil-beyaz jeti çitin üstünden geçerken fotoğrafladı.'::text),
(373770,41530,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi ... a zöld-fehér gépet, amikor elhaladt a kerítés fölött.'::text,'lefotózta'::text,'le lett fotózva'::text,'fotózva'::text,'A férfi lefotózta a zöld-fehér gépet, amikor elhaladt a kerítés fölött.'::text),
(373782,41532,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jet, ... er fotografierte, war die 30. Ankunft im Tagesbericht.'::text,'den'::text,'der'::text,'dessen'::text,'Der Jet, den er fotografierte, war die 30. Ankunft im Tagesbericht.'::text),
(373786,41532,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літак, ... він сфотографував, був 30-м прибуттям у щоденному звіті.'::text,'який'::text,'хто'::text,'чий'::text,'Літак, який він сфотографував, був 30-м прибуттям у щоденному звіті.'::text),
(373785,41532,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El avión ... fotografió era la llegada número 30 del informe diario.'::text,'que'::text,'quien'::text,'cuyo'::text,'El avión que fotografió era la llegada número 30 del informe diario.'::text),
(373784,41532,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avion ... cet homme a photographié était la 30e arrivée du rapport quotidien.'::text,'que'::text,'qui'::text,'dont'::text,'L''avion que cet homme a photographié était la 30e arrivée du rapport quotidien.'::text),
(373787,41532,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... jet günlük rapordaki 30. varıştı.'::text,'Fotoğrafladığı'::text,NULL::text,NULL::text,'Fotoğrafladığı jet günlük rapordaki 30. varıştı.'::text),
(373788,41532,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gép, ... lefotózott, a napi jelentés 30. érkezése volt.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'A gép, amelyet lefotózott, a napi jelentés 30. érkezése volt.'::text),
(373791,41533,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... dasselbe Flugzeug auch am Tag davor fotografiert.'::text,'habe'::text,'hat'::text,'fotografiere'::text,'Er sagte, er habe dasselbe Flugzeug auch am Tag davor fotografiert.'::text),
(373795,41533,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що ... той самий літак і напередодні.'::text,'сфотографував'::text,'сфотографував'::text,'фотографує'::text,'Він сказав, що сфотографував той самий літак і напередодні.'::text),
(373794,41533,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... ese mismo avión también el día anterior.'::text,'había fotografiado'::text,'ha fotografiado'::text,'fotografía'::text,'Dijo que había fotografiado ese mismo avión también el día anterior.'::text),
(373793,41533,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... ce même avion la veille aussi.'::text,'avait photographié'::text,'a photographié'::text,'photographie'::text,'Il a dit qu''il avait photographié ce même avion la veille aussi.'::text),
(373796,41533,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynı uçağı bir gün önce de ... söyledi.'::text,'fotoğrafladığını'::text,'fotoğrafladığını'::text,'fotoğrafladığını'::text,'Aynı uçağı bir gün önce de fotoğrafladığını söyledi.'::text),
(373797,41533,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy ugyanazt a gépet előző nap is ...'::text,'lefotózta'::text,'lefotózta'::text,'fotózza'::text,'Azt mondta, hogy ugyanazt a gépet előző nap is lefotózta.'::text),
(373800,41534,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... früher nur Vögel, aber jetzt liebt er Flugzeuge.'::text,'fotografierte'::text,'würde fotografieren'::text,'war gewohnt zu fotografieren'::text,'Er fotografierte früher nur Vögel, aber jetzt liebt er Flugzeuge.'::text),
(373804,41534,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше він ... лише птахів, а тепер обожнює літаки.'::text,'фотографував'::text,'фотографував би'::text,'звик фотографувати'::text,'Раніше він фотографував лише птахів, а тепер обожнює літаки.'::text),
(373803,41534,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes ... solo pájaros, pero ahora le encantan los aviones.'::text,'solía fotografiar'::text,'fotografiaría'::text,'estaba acostumbrado a fotografiar'::text,'Antes solía fotografiar solo pájaros, pero ahora le encantan los aviones.'::text),
(373802,41534,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, il ne ... que des oiseaux, mais maintenant il adore les avions.'::text,'photographiait'::text,'photographierait'::text,'avait l''habitude de photographier'::text,'Avant, il ne photographiait que des oiseaux, mais maintenant il adore les avions.'::text),
(373805,41534,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden sadece kuşları ..., ama şimdi uçaklara bayılıyor.'::text,'fotoğraflardı'::text,'fotoğraflardı'::text,'fotoğraflamaya alışkındı'::text,'Eskiden sadece kuşları fotoğraflardı, ama şimdi uçaklara bayılıyor.'::text),
(373806,41534,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen csak madarakat ..., de most imádja a repülőket.'::text,'fotózott'::text,'fotózna'::text,'hozzá volt szokva fotózni'::text,'Régen csak madarakat fotózott, de most imádja a repülőket.'::text),
(373809,41535,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er kann es kaum erwarten, den Jet ..., wenn er über den Zaun fliegt.'::text,'zu fotografieren'::text,'fotografierend'::text,'fotografieren'::text,'Er kann es kaum erwarten, den Jet zu fotografieren, wenn er über den Zaun fliegt.'::text),
(373813,41535,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він не може дочекатися, щоб ... літак, коли той пролітатиме над парканом.'::text,'сфотографувати'::text,'фотографуючи'::text,'сфотографувати'::text,'Він не може дочекатися, щоб сфотографувати літак, коли той пролітатиме над парканом.'::text),
(373812,41535,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está deseando ... el avión cuando pase sobre la valla.'::text,'fotografiar'::text,'fotografiando'::text,'fotografiar'::text,'Está deseando fotografiar el avión cuando pase sobre la valla.'::text),
(373811,41535,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a hâte de ... l''avion quand il passera au-dessus du grillage.'::text,'photographier'::text,'photographiant'::text,'photographier'::text,'Il a hâte de photographier l''avion quand il passera au-dessus du grillage.'::text),
(373814,41535,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jet çitin üstünden geçerken onu ... sabırsızlanıyor.'::text,'fotoğraflamak için'::text,'fotoğraflayarak'::text,'fotoğraflamak'::text,'Jet çitin üstünden geçerken onu fotoğraflamak için sabırsızlanıyor.'::text),
(373815,41535,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alig várja, hogy ... a gépet, amikor elhalad a kerítés fölött.'::text,'lefotózza'::text,'fotózva'::text,'lefotózza'::text,'Alig várja, hogy lefotózza a gépet, amikor elhalad a kerítés fölött.'::text),
(373827,41537,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade den Jet, als er über seinen Kopf donnerte. Absolut unvergesslich!'::text,'fotografierte'::text,'hatte fotografiert'::text,'fotografiert'::text,'Er fotografierte gerade den Jet, als er über seinen Kopf donnerte. Absolut unvergesslich!'::text),
(373831,41537,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... літак, коли той з ревом пролетів над його головою. Абсолютно незабутньо!'::text,'фотографував'::text,'сфотографував'::text,'фотографує'::text,'Він фотографував літак, коли той з ревом пролетів над його головою. Абсолютно незабутньо!'::text),
(373830,41537,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el avión cuando rugió sobre su cabeza. ¡Absolutamente inolvidable!'::text,'Estaba fotografiando'::text,'Había fotografiado'::text,'Fotografía'::text,'Estaba fotografiando el avión cuando rugió sobre su cabeza. ¡Absolutamente inolvidable!'::text),
(373829,41537,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''avion quand il a rugi au-dessus de sa tête. Absolument inoubliable !'::text,'photographiait'::text,'avait photographié'::text,'photographie'::text,'Il photographiait l''avion quand il a rugi au-dessus de sa tête. Absolument inoubliable !'::text),
(373832,41537,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jet gürleyerek başının üstünden geçtiğinde onu ...! Kesinlikle unutulmaz!'::text,'fotoğraflıyordu'::text,'fotoğraflamıştı'::text,'fotoğraflıyor'::text,'Jet gürleyerek başının üstünden geçtiğinde onu fotoğraflıyordu! Kesinlikle unutulmaz!'::text),
(373833,41537,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a gépet, amikor elzúgott a feje fölött. Felejthetetlen!'::text,'fotózta'::text,'lefotózta'::text,'fotózza'::text,'Épp fotózta a gépet, amikor elzúgott a feje fölött. Felejthetetlen!'::text),
(346530,38504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... gerade die Rolltreppe runter, als sie die Abflugtafel sah, ohne Witz.'::text,'fuhr'::text,'fuhr'::text,'ist gefahren'::text,'Bro, sie fuhr gerade die Rolltreppe runter, als sie die Abflugtafel sah, ohne Witz.'::text),
(346534,38504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... ескалатором униз, коли побачила табло вильотів, без брехні.'::text,'їхала'::text,'з''їхала'::text,'з''їхала'::text,'Бро, вона їхала ескалатором униз, коли побачила табло вильотів, без брехні.'::text),
(346533,38504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... por la escalera mecánica cuando vio el panel de salidas, sin mentir.'::text,'estaba bajando'::text,'bajó'::text,'ha bajado'::text,'Bro, estaba bajando por la escalera mecánica cuando vio el panel de salidas, sin mentir.'::text),
(346532,38504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... l''escalator quand elle a vu le tableau des départs, sans mentir.'::text,'descendait'::text,'a descendu'::text,'a descendu'::text,'Frère, elle descendait l''escalator quand elle a vu le tableau des départs, sans mentir.'::text),
(346535,38504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kalkış panosunu gördüğünde yürüyen merdivenle ..., yemin ederim.'::text,'iniyordu'::text,'indi'::text,'indi'::text,'Kanka, kalkış panosunu gördüğünde yürüyen merdivenle iniyordu, yemin ederim.'::text),
(346536,38504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp ... a mozgólépcsőn, amikor meglátta az indulási táblát, komolyan.'::text,'ment lefelé'::text,'lement'::text,'lement'::text,'Tesó, épp ment lefelé a mozgólépcsőn, amikor meglátta az indulási táblát, komolyan.'::text),
(346539,38505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die heutigen Abflugzeiten ... um 6 Uhr auf der Tafel angezeigt, lange vor der Deadline.'::text,'wurden'::text,'zeigten'::text,'werden'::text,'Die heutigen Abflugzeiten wurden um 6 Uhr auf der Tafel angezeigt, lange vor der Deadline.'::text),
(346543,38505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогоднішній час вильотів ... на табло о 6:00, задовго до дедлайну.'::text,'було опубліковано'::text,'опублікував'::text,'публікується'::text,'Сьогоднішній час вильотів було опубліковано на табло о 6:00, задовго до дедлайну.'::text),
(346542,38505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los horarios de salida de hoy ... en el panel a las 6:00, mucho antes del plazo.'::text,'fueron publicados'::text,'publicaron'::text,'son publicados'::text,'Los horarios de salida de hoy fueron publicados en el panel a las 6:00, mucho antes del plazo.'::text),
(346541,38505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les horaires de départ du jour ... sur le tableau à 6 h, bien avant la deadline.'::text,'ont été affichés'::text,'ont affiché'::text,'sont affichés'::text,'Les horaires de départ du jour ont été affichés sur le tableau à 6 h, bien avant la deadline.'::text),
(346544,38505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugünün kalkış saatleri, son tarihten çok önce, saat 6''da panoya ...'::text,'asıldı'::text,'astı'::text,'asılıyor'::text,'Bugünün kalkış saatleri, son tarihten çok önce, saat 6''da panoya asıldı.'::text),
(346545,38505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mai indulási időpontok reggel 6-kor ... a táblára, jóval a határidő előtt.'::text,'ki lettek téve'::text,'kitették'::text,'ki vannak téve'::text,'A mai indulási időpontok reggel 6-kor ki lettek téve a táblára, jóval a határidő előtt.'::text),
(346548,38506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tafel ... jeden Abflug, deshalb ist sie ja eine Abflugtafel.'::text,'zeigt'::text,'wird gezeigt'::text,'zeigend'::text,'Die Tafel zeigt jeden Abflug, deshalb ist sie ja eine Abflugtafel.'::text),
(346552,38506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Табло ... кожен виліт, тому воно й табло вильотів.'::text,'показує'::text,'показується'::text,'показуючи'::text,'Табло показує кожен виліт, тому воно й табло вильотів.'::text),
(346551,38506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El panel ... cada salida, por eso es un panel de salidas.'::text,'muestra'::text,'es mostrado'::text,'mostrando'::text,'El panel muestra cada salida, por eso es un panel de salidas.'::text),
(346550,38506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tableau ... chaque départ, c''est pour ça que c''est un tableau des départs.'::text,'affiche'::text,'est affiché'::text,'affichant'::text,'Le tableau affiche chaque départ, c''est pour ça que c''est un tableau des départs.'::text),
(346553,38506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pano her kalkışı ..., bu yüzden kalkış panosu zaten.'::text,'gösteriyor'::text,'gösteriliyor'::text,'göstererek'::text,'Pano her kalkışı gösteriyor, bu yüzden kalkış panosu zaten.'::text),
(346554,38506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tábla ... minden indulást, ezért indulási tábla.'::text,'mutat'::text,'mutatva van'::text,'mutatva'::text,'A tábla mutat minden indulást, ezért indulási tábla.'::text),
(346557,38507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reisende ... auf einen Abflug warten, wie ihr Koffer und ihr Nackenkissen nahelegen.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Die Reisende muss auf einen Abflug warten, wie ihr Koffer und ihr Nackenkissen nahelegen.'::text),
(346561,38507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мандрівниця ... чекати на виліт, на що вказують її валіза й подушка для шиї.'::text,'мусить'::text,'не може'::text,'повинна'::text,'Мандрівниця мусить чекати на виліт, на що вказують її валіза й подушка для шиї.'::text),
(346560,38507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La viajera ... estar esperando una salida, como indican su maleta y su almohada de viaje.'::text,'debe de'::text,'no puede'::text,'debería'::text,'La viajera debe de estar esperando una salida, como indican su maleta y su almohada de viaje.'::text),
(346559,38507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voyageuse ... attendre un départ, comme l''indiquent sa valise et son coussin de voyage.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'La voyageuse doit attendre un départ, comme l''indiquent sa valise et son coussin de voyage.'::text),
(346562,38507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yolcu, bavulu ve boyun yastığından anlaşıldığı üzere bir kalkışı bekliyor ...'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Yolcu, bavulu ve boyun yastığından anlaşıldığı üzere bir kalkışı bekliyor olmalı.'::text),
(346563,38507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utazó ... egy indulásra vár, ahogy a bőröndje és a nyakpárnája is mutatja.'::text,'biztosan'::text,'nem lehet, hogy'::text,'valószínűleg'::text,'Az utazó biztosan egy indulásra vár, ahogy a bőröndje és a nyakpárnája is mutatja.'::text),
(346566,38508,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tafel, ... jeden Abflug zeigt, hängt über der Rolltreppe.'::text,'die'::text,'wer'::text,'wo'::text,'Die Tafel, die jeden Abflug zeigt, hängt über der Rolltreppe.'::text),
(346570,38508,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Табло, ... показує кожен виліт, висить над ескалатором.'::text,'яке'::text,'хто'::text,'де'::text,'Табло, яке показує кожен виліт, висить над ескалатором.'::text),
(346569,38508,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El panel ... muestra cada salida está colgado sobre la escalera mecánica.'::text,'que'::text,'quien'::text,'donde'::text,'El panel que muestra cada salida está colgado sobre la escalera mecánica.'::text),
(346568,38508,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tableau ... affiche chaque départ est accroché au-dessus de l''escalator.'::text,'qui'::text,'qui'::text,'où'::text,'Le tableau qui affiche chaque départ est accroché au-dessus de l''escalator.'::text),
(346571,38508,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kalkışı ... pano yürüyen merdivenin üstünde asılı.'::text,'gösteren'::text,NULL::text,NULL::text,'Her kalkışı gösteren pano yürüyen merdivenin üstünde asılı.'::text),
(346572,38508,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tábla, ... minden indulást mutat, a mozgólépcső fölött lóg.'::text,'amely'::text,'aki'::text,'ahol'::text,'A tábla, amely minden indulást mutat, a mozgólépcső fölött lóg.'::text),
(346575,38509,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, dass sie ihre Abflugzeit auf der großen Tafel ...'::text,'gefunden hatte'::text,'gefunden hat'::text,'findet'::text,'Sie sagte, dass sie ihre Abflugzeit auf der großen Tafel gefunden hatte.'::text),
(346579,38509,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... свій час вильоту на великому табло.'::text,'знайшла'::text,'знайшла'::text,'знаходить'::text,'Вона сказала, що знайшла свій час вильоту на великому табло.'::text),
(346578,38509,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... su hora de salida en el panel grande.'::text,'había encontrado'::text,'ha encontrado'::text,'encuentra'::text,'Dijo que había encontrado su hora de salida en el panel grande.'::text),
(346577,38509,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... son heure de départ sur le grand tableau.'::text,'avait trouvé'::text,'a trouvé'::text,'trouve'::text,'Elle a dit qu''elle avait trouvé son heure de départ sur le grand tableau.'::text),
(346580,38509,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalkış saatini büyük panoda ... söyledi.'::text,'bulduğunu'::text,'bulduğunu'::text,'bulduğunu'::text,'Kalkış saatini büyük panoda bulduğunu söyledi.'::text),
(346581,38509,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy ... az indulási idejét a nagy táblán.'::text,'megtalálta'::text,'megtalálta'::text,'megtalálja'::text,'Azt mondta, hogy megtalálta az indulási idejét a nagy táblán.'::text),
(346593,38511,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie brennt buchstäblich darauf, den Wasserfall vor ihrem Abflug ...!'::text,'zu sehen'::text,'sehend'::text,'sehen'::text,'Sie brennt buchstäblich darauf, den Wasserfall vor ihrem Abflug zu sehen!'::text),
(346597,38511,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона буквально помирає від бажання ... водоспад перед вильотом!'::text,'побачити'::text,'бачачи'::text,'побачити'::text,'Вона буквально помирає від бажання побачити водоспад перед вильотом!'::text),
(346596,38511,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se muere literalmente por ... la cascada antes de su salida!'::text,'ver'::text,'viendo'::text,'ver'::text,'¡Se muere literalmente por ver la cascada antes de su salida!'::text),
(346595,38511,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle meurt littéralement d''envie de ... la cascade avant son départ !'::text,'voir'::text,'voyant'::text,'voir'::text,'Elle meurt littéralement d''envie de voir la cascade avant son départ !'::text),
(346598,38511,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kalkışından önce şelaleyi ... resmen ölüyor!'::text,'görmek için'::text,'görerek'::text,'görmek'::text,'Kalkışından önce şelaleyi görmek için resmen ölüyor!'::text),
(346599,38511,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szó szerint meghal, hogy ... a vízesést az indulása előtt!'::text,'láthassa'::text,'látva'::text,'lássa'::text,'Szó szerint meghal, hogy láthassa a vízesést az indulása előtt!'::text),
(346602,38512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, sie hat mir erzählt, ... sei größer als ihre ganze Wohnung gewesen.'::text,'die Abflugtafel'::text,'eine Abflugtafel'::text,'Abflugtafel'::text,'Girl, sie hat mir erzählt, die Abflugtafel sei größer als ihre ganze Wohnung gewesen.'::text),
(346606,38512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що ... було більшим за всю її квартиру.'::text,'табло вильотів'::text,'табло вильотів'::text,'табло вильотів'::text,'Подруго, вона сказала мені, що табло вильотів було більшим за всю її квартиру.'::text),
(346605,38512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que ... era más grande que todo su piso.'::text,'el panel de salidas'::text,'un panel de salidas'::text,'panel de salidas'::text,'Amiga, me dijo que el panel de salidas era más grande que todo su piso.'::text),
(346604,38512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit que ... était plus grand que tout son appart.'::text,'le tableau des départs'::text,'un tableau des départs'::text,'tableau des départs'::text,'Meuf, elle m''a dit que le tableau des départs était plus grand que tout son appart.'::text),
(346607,38512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana ... tüm dairesinden daha büyük olduğunu söyledi.'::text,'kalkış panosunun'::text,'bir kalkış panosunun'::text,'kalkış panosunun'::text,'Kızım, bana kalkış panosunun tüm dairesinden daha büyük olduğunu söyledi.'::text),
(346608,38512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy ... nagyobb volt, mint az egész lakása.'::text,'az indulási tábla'::text,'egy indulási tábla'::text,'indulási tábla'::text,'Csajszi, azt mondta, hogy az indulási tábla nagyobb volt, mint az egész lakása.'::text),
(346620,38514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bruh, bis zu dieser Reise ... sie noch nie so eine große Abflugtafel gesehen, echt.'::text,'hatte'::text,'hat'::text,'war'::text,'Bruh, bis zu dieser Reise hatte sie noch nie so eine große Abflugtafel gesehen, echt.'::text),
(346624,38514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до тієї поїздки вона ... ніколи не бачила такого великого табло вильотів, реально.'::text,''::text,NULL::text,'була'::text,'Бро, до тієї поїздки вона ніколи не бачила такого великого табло вильотів, реально.'::text),
(346623,38514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, hasta ese viaje nunca ... visto un panel de salidas tan grande, en serio.'::text,'había'::text,'ha'::text,'estaba'::text,'Bro, hasta ese viaje nunca había visto un panel de salidas tan grande, en serio.'::text),
(346622,38514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, avant ce voyage, elle n''... jamais vu un tableau des départs aussi grand, grave.'::text,'avait'::text,'a'::text,'était'::text,'Frère, avant ce voyage, elle n''avait jamais vu un tableau des départs aussi grand, grave.'::text),
(346625,38514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yolculuğa kadar ... hiç bu kadar büyük bir kalkış panosu görmemişti, cidden.'::text,''::text,NULL::text,NULL::text,'Kanka, o yolculuğa kadar hiç bu kadar büyük bir kalkış panosu görmemişti, cidden.'::text),
(346626,38514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, addig az útig ... soha nem látott ilyen nagy indulási táblát, komolyan.'::text,''::text,NULL::text,'volt'::text,'Tesó, addig az útig soha nem látott ilyen nagy indulási táblát, komolyan.'::text),
(378966,42108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau ihn dir an: Sobald die Katze ihn berührt, ... er, als wäre es das Ende der Welt!'::text,'reagiert'::text,'wird reagieren'::text,'reagiert gerade'::text,'Schau ihn dir an: Sobald die Katze ihn berührt, reagiert er, als wäre es das Ende der Welt!'::text),
(378970,42108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивись на нього: щойно кішка його торкнеться, він ..., ніби настав кінець світу!'::text,'відреагує'::text,'реагуватиме'::text,'реагує'::text,'Дивись на нього: щойно кішка його торкнеться, він відреагує, ніби настав кінець світу!'::text),
(378969,42108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Míralo: ¡en cuanto el gato lo toque, ... como si fuera el fin del mundo!'::text,'reaccionará'::text,'estará reaccionando'::text,'está reaccionando'::text,'Míralo: ¡en cuanto el gato lo toque, reaccionará como si fuera el fin del mundo!'::text),
(378968,42108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde-le : dès que le chat le touche, il ... comme si c''était la fin du monde !'::text,'réagira'::text,'sera en train de réagir'::text,'réagit'::text,'Regarde-le : dès que le chat le touche, il réagira comme si c''était la fin du monde !'::text),
(378971,42108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İzle onu: kedi ona dokunduğu an dünyanın sonu gelmiş gibi ...!'::text,'tepki verecek'::text,'tepki veriyor olacak'::text,'tepki veriyor'::text,'İzle onu: kedi ona dokunduğu an dünyanın sonu gelmiş gibi tepki verecek!'::text),
(378972,42108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyeld: amint a macska hozzáér, úgy ..., mintha itt lenne a világvége!'::text,'reagál'::text,'fog reagálni'::text,'reagál éppen'::text,'Figyeld: amint a macska hozzáér, úgy reagál, mintha itt lenne a világvége!'::text),
(378984,42110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Augen haben sehr schnell auf die Katze reagiert, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Seine Augen haben sehr schnell auf die Katze reagiert, nicht wahr?'::text),
(378988,42110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його очі дуже швидко відреагували на кішку, ...?'::text,'чи не так'::text,'чи не так'::text,'чи не так'::text,'Його очі дуже швидко відреагували на кішку, чи не так?'::text),
(378987,42110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus ojos reaccionaron muy rápido al gato, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Sus ojos reaccionaron muy rápido al gato, ¿verdad?'::text),
(378986,42110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses yeux ont réagi très vite au chat, ... ?'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'Ses yeux ont réagi très vite au chat, pas vrai ?'::text),
(378989,42110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözleri kediye çok hızlı tepki verdi, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Gözleri kediye çok hızlı tepki verdi, değil mi?'::text),
(378990,42110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szeme nagyon gyorsan reagált a macskára, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A szeme nagyon gyorsan reagált a macskára, ugye?'::text),
(378993,42111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Augen haben auf die Katze reagiert, und ...'::text,'seine Nase auch.'::text,'seine Nase auch.'::text,'seine Nase auch nicht.'::text,'Seine Augen haben auf die Katze reagiert, und seine Nase auch.'::text),
(378997,42111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його очі відреагували на кішку, і ...'::text,'ніс теж.'::text,'ніс теж.'::text,'ніс теж ні.'::text,'Його очі відреагували на кішку, і ніс теж.'::text),
(378996,42111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus ojos reaccionaron al gato, y ...'::text,'su nariz también.'::text,'su nariz también.'::text,'su nariz tampoco.'::text,'Sus ojos reaccionaron al gato, y su nariz también.'::text),
(378995,42111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses yeux ont réagi au chat, et ...'::text,'son nez aussi.'::text,'son nez aussi.'::text,'son nez non plus.'::text,'Ses yeux ont réagi au chat, et son nez aussi.'::text),
(378998,42111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözleri kediye tepki verdi, ...'::text,'burnu da.'::text,'burnu da.'::text,'burnu da vermedi.'::text,'Gözleri kediye tepki verdi, burnu da.'::text),
(378999,42111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szeme reagált a macskára, és ...'::text,'az orra is.'::text,'az orra is.'::text,'az orra sem.'::text,'A szeme reagált a macskára, és az orra is.'::text),
(379002,42112,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Besuchs wird er auf jede erdenkliche Weise auf die Katze ...'::text,'reagiert haben'::text,'reagieren'::text,'am Reagieren sein'::text,'Bis zum Ende des Besuchs wird er auf jede erdenkliche Weise auf die Katze reagiert haben.'::text),
(379006,42112,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця візиту він ... на кішку всіма можливими способами.'::text,'відреагує'::text,'відреагує'::text,'реагуватиме'::text,'До кінця візиту він відреагує на кішку всіма можливими способами.'::text),
(379005,42112,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de la visita, ... al gato de todas las formas posibles.'::text,'habrá reaccionado'::text,'reaccionará'::text,'estará reaccionando'::text,'Para el final de la visita, habrá reaccionado al gato de todas las formas posibles.'::text),
(379004,42112,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de la visite, il ... au chat de toutes les façons possibles.'::text,'aura réagi'::text,'réagira'::text,'sera en train de réagir'::text,'D''ici la fin de la visite, il aura réagi au chat de toutes les façons possibles.'::text),
(379007,42112,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziyaretin sonuna kadar kediye akla gelebilecek her şekilde ...'::text,'tepki vermiş olacak'::text,'tepki verecek'::text,'tepki veriyor olacak'::text,'Ziyaretin sonuna kadar kediye akla gelebilecek her şekilde tepki vermiş olacak.'::text),
(379008,42112,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A látogatás végére már minden lehetséges módon ... a macskára.'::text,'reagált'::text,'reagál'::text,'reagálni fog'::text,'A látogatás végére már minden lehetséges módon reagált a macskára.'::text),
(379011,42113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Katze nicht gestreichelt hätte, ... er nicht so reagiert. Tolle Entscheidung, offensichtlich.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn er die Katze nicht gestreichelt hätte, hätte er nicht so reagiert. Tolle Entscheidung, offensichtlich.'::text),
(379015,42113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не гладив кішку, він не ... так. Чудове рішення, звісно.'::text,'відреагував би'::text,'відреагує'::text,'відреагував'::text,'Якби він не гладив кішку, він не відреагував би так. Чудове рішення, звісно.'::text),
(379014,42113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera acariciado al gato, no ... así. Gran decisión, obviamente.'::text,'habría reaccionado'::text,'reaccionará'::text,'reaccionó'::text,'Si no hubiera acariciado al gato, no habría reaccionado así. Gran decisión, obviamente.'::text),
(379013,42113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas caressé le chat, il ... comme ça. Super décision, évidemment.'::text,'n''aurait pas réagi'::text,'ne réagira pas'::text,'n''a pas réagi'::text,'S''il n''avait pas caressé le chat, il n''aurait pas réagi comme ça. Super décision, évidemment.'::text),
(379016,42113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kediyi okşamasaydı ... böyle. Harika karar, tabii ki.'::text,'tepki vermezdi'::text,'tepki vermeyecek'::text,'tepki vermedi'::text,'Kediyi okşamasaydı tepki vermezdi böyle. Harika karar, tabii ki.'::text),
(379017,42113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem simogatta volna meg a macskát, nem ... így. Remek döntés, nyilván.'::text,'reagált volna'::text,'fog reagálni'::text,'reagált'::text,'Ha nem simogatta volna meg a macskát, nem reagált volna így. Remek döntés, nyilván.'::text),
(379020,42114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er hat zugegeben, früher schon heftig auf Katzen ..., echt.'::text,'reagiert zu haben'::text,'zu reagieren'::text,'reagiert'::text,'Bro, er hat zugegeben, früher schon heftig auf Katzen reagiert zu haben, echt.'::text),
(379024,42114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він зізнався, що й раніше ... на котів погано, реально.'::text,'реагував'::text,'реагувати'::text,'реагував'::text,'Бро, він зізнався, що й раніше реагував на котів погано, реально.'::text),
(379023,42114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, admitió ... mal a los gatos antes, en serio.'::text,'haber reaccionado'::text,'reaccionar'::text,'reaccionó'::text,'Bro, admitió haber reaccionado mal a los gatos antes, en serio.'::text),
(379022,42114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, il a avoué ... mal aux chats avant, grave.'::text,'avoir réagi'::text,'réagir'::text,'a réagi'::text,'Frère, il a avoué avoir réagi mal aux chats avant, grave.'::text),
(379025,42114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, daha önce de kedilere kötü ... itiraf etti, cidden.'::text,'tepki verdiğini'::text,'tepki vermeyi'::text,'tepki verdi'::text,'Kanka, daha önce de kedilere kötü tepki verdiğini itiraf etti, cidden.'::text),
(379026,42114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, beismerte, hogy korábban is rosszul ... a macskákra, komolyan.'::text,'reagált'::text,'reagálni'::text,'reagált'::text,'Tesó, beismerte, hogy korábban is rosszul reagált a macskákra, komolyan.'::text),
(379029,42115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Bro, er ... die Katze nicht anfassen sollen; jeder weiß, dass er auf Katzen reagiert, echt.'::text,'hätte'::text,'darf'::text,'konnte'::text,'Nee Bro, er hätte die Katze nicht anfassen sollen; jeder weiß, dass er auf Katzen reagiert, echt.'::text),
(379033,42115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні, бро, ... торкатися тієї кішки; всі знають, що в нього реакція на котів, реально.'::text,'йому не варто було'::text,'йому не можна'::text,'він не міг'::text,'Ні, бро, йому не варто було торкатися тієї кішки; всі знають, що в нього реакція на котів, реально.'::text),
(379032,42115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, bro, no ... tocado a ese gato; todo el mundo sabe que reacciona a los gatos, en serio.'::text,'debería haber'::text,'debe haber'::text,'pudo'::text,'Qué va, bro, no debería haber tocado a ese gato; todo el mundo sabe que reacciona a los gatos, en serio.'::text),
(379031,42115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frère, il ... toucher ce chat ; tout le monde sait qu''il réagit aux chats, grave.'::text,'n''aurait pas dû'::text,'ne doit pas'::text,'ne pouvait pas'::text,'Non frère, il n''aurait pas dû toucher ce chat ; tout le monde sait qu''il réagit aux chats, grave.'::text),
(379034,42115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o kediye ...; herkes kedilere tepki verdiğini biliyor, cidden.'::text,'dokunmamalıydı'::text,'dokunmamış olmalı'::text,'dokunamazdı'::text,'Yok kanka, o kediye dokunmamalıydı; herkes kedilere tepki verdiğini biliyor, cidden.'::text),
(379035,42115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, ... hozzáérnie ahhoz a macskához; mindenki tudja, hogy reagál a macskákra, komolyan.'::text,'nem kellett volna'::text,'nem szabad'::text,'nem tudott'::text,'Nem, tesó, nem kellett volna hozzáérnie ahhoz a macskához; mindenki tudja, hogy reagál a macskákra, komolyan.'::text),
(379038,42116,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er reagierte, ließ er die Katze gemäß Protokoll innerhalb von 30 Sekunden ...'::text,'raustragen'::text,'raustragen'::text,'raustragend'::text,'Als er reagierte, ließ er die Katze gemäß Protokoll innerhalb von 30 Sekunden raustragen.'::text),
(379042,42116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно він відреагував, він розпорядився ... кішку протягом 30 секунд, згідно з протоколом.'::text,'винести'::text,'винести'::text,'виносячи'::text,'Щойно він відреагував, він розпорядився винести кішку протягом 30 секунд, згідно з протоколом.'::text),
(379041,42116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En cuanto reaccionó, hizo que ... al gato en menos de 30 segundos, según el protocolo.'::text,'sacaran'::text,'sacar'::text,'sacando'::text,'En cuanto reaccionó, hizo que sacaran al gato en menos de 30 segundos, según el protocolo.'::text),
(379040,42116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dès qu''il a réagi, il a fait ... le chat en moins de 30 secondes, selon le protocole.'::text,'sortir'::text,'sortir'::text,'sortant'::text,'Dès qu''il a réagi, il a fait sortir le chat en moins de 30 secondes, selon le protocole.'::text),
(379043,42116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepki verir vermez, protokole göre kediyi 30 saniye içinde ...'::text,'dışarı çıkarttırdı'::text,'dışarı çıkarttırdı'::text,'dışarı çıkararak'::text,'Tepki verir vermez, protokole göre kediyi 30 saniye içinde dışarı çıkarttırdı.'::text),
(379044,42116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amint reagált, a protokoll szerint 30 másodpercen belül ... a macskát.'::text,'kivitette'::text,'kivitette'::text,'kivíve'::text,'Amint reagált, a protokoll szerint 30 másodpercen belül kivitette a macskát.'::text),
(379056,42118,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Subjekt, ... Augen innerhalb von Sekunden reagierten, ist offensichtlich allergisch gegen Katzen.'::text,'dessen'::text,'das'::text,'welches'::text,'Das Subjekt, dessen Augen innerhalb von Sekunden reagierten, ist offensichtlich allergisch gegen Katzen.'::text),
(379060,42118,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Суб''єкт, ... очі відреагували за лічені секунди, очевидно, має алергію на котів.'::text,'чиї'::text,'який'::text,'котрий'::text,'Суб''єкт, чиї очі відреагували за лічені секунди, очевидно, має алергію на котів.'::text),
(379059,42118,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto, ... ojos reaccionaron en segundos, es evidentemente alérgico a los gatos.'::text,'cuyos'::text,'que'::text,'el cual'::text,'El sujeto, cuyos ojos reaccionaron en segundos, es evidentemente alérgico a los gatos.'::text),
(379058,42118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet, ... les yeux ont réagi en quelques secondes, est manifestement allergique aux chats.'::text,'dont'::text,'qui'::text,'lequel'::text,'Le sujet, dont les yeux ont réagi en quelques secondes, est manifestement allergique aux chats.'::text),
(379061,42118,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözleri saniyeler içinde tepki ... denek, belli ki kedilere alerjik.'::text,'veren'::text,NULL::text,NULL::text,'Gözleri saniyeler içinde tepki veren denek, belli ki kedilere alerjik.'::text),
(379062,42118,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany, ... szeme másodpercek alatt reagált, nyilvánvalóan allergiás a macskákra.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Az alany, akinek a szeme másodpercek alatt reagált, nyilvánvalóan allergiás a macskákra.'::text),
(357339,39705,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich gerade seitlich durch die Lücke, als er zum Himmel hochsah.'::text,'schob'::text,'schob'::text,'hat geschoben'::text,'Er schob sich gerade seitlich durch die Lücke, als er zum Himmel hochsah.'::text),
(357343,39705,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... боком крізь щілину, коли подивився на небо.'::text,'протискався'::text,'протиснувся'::text,'протиснувся'::text,'Він протискався боком крізь щілину, коли подивився на небо.'::text),
(357342,39705,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de lado por el hueco cuando miró al cielo.'::text,'Se estaba colando'::text,'Se coló'::text,'Se ha colado'::text,'Se estaba colando de lado por el hueco cuando miró al cielo.'::text),
(357341,39705,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... de côté dans l''interstice quand il a levé les yeux vers le ciel.'::text,'se faufilait'::text,'s''est faufilé'::text,'s''est faufilé'::text,'Il se faufilait de côté dans l''interstice quand il a levé les yeux vers le ciel.'::text),
(357344,39705,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gökyüzüne baktığında boşluktan yan yan ...'::text,'geçiyordu'::text,'geçti'::text,'geçti'::text,'Gökyüzüne baktığında boşluktan yan yan geçiyordu.'::text),
(357345,39705,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp oldalazva ... a résen, amikor felnézett az égre.'::text,'araszolt át'::text,'átaraszolt'::text,'átaraszolt'::text,'Épp oldalazva araszolt át a résen, amikor felnézett az égre.'::text),
(357348,39706,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich schon den ganzen Vormittag durch enge Lücken in der Medina.'::text,'zwängt'::text,'zwängt'::text,'zwängt'::text,'Er zwängt sich schon den ganzen Vormittag durch enge Lücken in der Medina.'::text),
(357352,39706,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він увесь ранок ... крізь вузькі щілини в медині.'::text,'протискається'::text,'протискається'::text,'протискається'::text,'Він увесь ранок протискається крізь вузькі щілини в медині.'::text),
(357351,39706,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... por huecos estrechos de la medina toda la mañana.'::text,'Lleva colándose'::text,'Se está colando'::text,'Se cuela'::text,'Lleva colándose por huecos estrechos de la medina toda la mañana.'::text),
(357350,39706,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait toute la matinée qu''il se ... dans les passages étroits de la médina.'::text,'faufile'::text,'faufile'::text,'faufile'::text,'Ça fait toute la matinée qu''il se faufile dans les passages étroits de la médina.'::text),
(357353,39706,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sabah medinadaki dar boşluklardan ...'::text,'geçiyor'::text,'geçiyor'::text,'geçer'::text,'Bütün sabah medinadaki dar boşluklardan geçiyor.'::text),
(357354,39706,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délelőtt ... a medina szűk résein.'::text,'préselődik át'::text,'préselődik át'::text,'préselődik át'::text,'Egész délelőtt préselődik át a medina szűk résein.'::text),
(357357,39707,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... in die Lücke, schob sich hindurch und kam lachend heraus.'::text,'trat'::text,'trat gerade'::text,'ist getreten'::text,'Er trat in die Lücke, schob sich hindurch und kam lachend heraus.'::text),
(357361,39707,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... у щілину, протиснувся крізь неї й вийшов, сміючись.'::text,'ступив'::text,'ступав'::text,'ступив'::text,'Він ступив у щілину, протиснувся крізь неї й вийшов, сміючись.'::text),
(357360,39707,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... en el hueco, se coló y salió riéndose.'::text,'Entró'::text,'Estaba entrando'::text,'Ha entrado'::text,'Entró en el hueco, se coló y salió riéndose.'::text),
(357359,39707,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans l''interstice, s''est faufilé et est ressorti en riant.'::text,'est entré'::text,'entrait'::text,'est entré'::text,'Il est entré dans l''interstice, s''est faufilé et est ressorti en riant.'::text),
(357362,39707,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşluğa ..., içinden sıyrılıp geçti ve gülerek çıktı.'::text,'girdi'::text,'giriyordu'::text,'girdi'::text,'Boşluğa girdi, içinden sıyrılıp geçti ve gülerek çıktı.'::text),
(357363,39707,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a résbe, átaraszolt rajta, és nevetve jött ki.'::text,'Belépett'::text,'Épp lépett be'::text,'Belépett'::text,'Belépett a résbe, átaraszolt rajta, és nevetve jött ki.'::text),
(357366,39708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, er hat sich heute schon durch so fünf Lücken ..., ohne Witz.'::text,'gequetscht'::text,'gequetscht'::text,'quetschte'::text,'Bro, er hat sich heute schon durch so fünf Lücken gequetscht, ohne Witz.'::text),
(357370,39708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він сьогодні вже ... крізь щілин п''ять, без брехні.'::text,'протиснувся'::text,'протискався'::text,'протиснувся'::text,'Бро, він сьогодні вже протиснувся крізь щілин п''ять, без брехні.'::text),
(357369,39708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, hoy ya se ... por como cinco huecos, sin mentir.'::text,'ha colado'::text,'ha estado colando'::text,'coló'::text,'Bro, hoy ya se ha colado por como cinco huecos, sin mentir.'::text),
(357368,39708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, aujourd''hui il ... dans genre cinq passages, sans mentir.'::text,'s''est faufilé'::text,'se faufile'::text,'s''est faufilé'::text,'Frère, aujourd''hui il s''est faufilé dans genre cinq passages, sans mentir.'::text),
(357371,39708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bugün şimdiye kadar beş boşluktan falan ..., yemin ederim.'::text,'sıkışarak geçti'::text,'geçip duruyor'::text,'geçti'::text,'Kanka, bugün şimdiye kadar beş boşluktan falan sıkışarak geçti, yemin ederim.'::text),
(357372,39708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ma eddig vagy öt résen ... át, komolyan.'::text,'préselődött'::text,'préselődik'::text,'préselődött'::text,'Tesó, ma eddig vagy öt résen préselődött át, komolyan.'::text),
(357375,39709,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 10 Uhr ... er sich durch die Lücke gezwängt und den Treffpunkt erreicht.'::text,'hatte'::text,'hat'::text,'zwängt'::text,'Bis 10 Uhr hatte er sich durch die Lücke gezwängt und den Treffpunkt erreicht.'::text),
(357379,39709,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 10:00 він ... крізь щілину й дістався місця зустрічі.'::text,'протиснувся'::text,'протиснувся'::text,'протискається'::text,'До 10:00 він протиснувся крізь щілину й дістався місця зустрічі.'::text),
(357378,39709,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para las 10:00 ya se ... por el hueco y había llegado al punto de encuentro.'::text,'había colado'::text,'ha colado'::text,'cuela'::text,'Para las 10:00 ya se había colado por el hueco y había llegado al punto de encuentro.'::text),
(357377,39709,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 10 h, il ... par l''interstice et avait atteint le point de rendez-vous.'::text,'s''était faufilé'::text,'s''est faufilé'::text,'se faufile'::text,'À 10 h, il s''était faufilé par l''interstice et avait atteint le point de rendez-vous.'::text),
(357380,39709,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat 10''a kadar boşluktan ... ve buluşma noktasına varmıştı.'::text,'sıkışarak geçmişti'::text,'geçti'::text,'geçiyor'::text,'Saat 10''a kadar boşluktan sıkışarak geçmişti ve buluşma noktasına varmıştı.'::text),
(357381,39709,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délelőtt 10-re már ... a résen, és elérte a találkozási pontot.'::text,'átpréselődött'::text,'átpréselődött'::text,'préselődik át'::text,'Délelőtt 10-re már átpréselődött a résen, és elérte a találkozási pontot.'::text),
(357384,39710,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Lücke eng ist, ... er seitwärts, weil enge Lücken eng sind.'::text,'geht'::text,'würde gehen'::text,'ging'::text,'Wenn die Lücke eng ist, geht er seitwärts, weil enge Lücken eng sind.'::text),
(357388,39710,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо щілина вузька, він ... боком, бо вузькі щілини вузькі.'::text,'піде'::text,'пішов би'::text,'пішов'::text,'Якщо щілина вузька, він піде боком, бо вузькі щілини вузькі.'::text),
(357387,39710,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hueco es estrecho, ... de lado, porque los huecos estrechos son estrechos.'::text,'caminará'::text,'caminaría'::text,'caminó'::text,'Si el hueco es estrecho, caminará de lado, porque los huecos estrechos son estrechos.'::text),
(357386,39710,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''interstice est étroit, il ... de côté, parce que les interstices étroits sont étroits.'::text,'marchera'::text,'marcherait'::text,'a marché'::text,'Si l''interstice est étroit, il marchera de côté, parce que les interstices étroits sont étroits.'::text),
(357389,39710,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşluk darsa yan yan ..., çünkü dar boşluklar dardır.'::text,'yürüyecek'::text,'yürürdü'::text,'yürüdü'::text,'Boşluk darsa yan yan yürüyecek, çünkü dar boşluklar dardır.'::text),
(357390,39710,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a rés szűk, oldalazva ..., mert a szűk rések szűkek.'::text,'fog menni'::text,'menne'::text,'ment'::text,'Ha a rés szűk, oldalazva fog menni, mert a szűk rések szűkek.'::text),
(357393,39711,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wäre die Lücke deutlich breiter, ... das Subjekt vorwärts statt seitwärts gehen.'::text,'würde'::text,'wird'::text,'geht'::text,'Wäre die Lücke deutlich breiter, würde das Subjekt vorwärts statt seitwärts gehen.'::text),
(357397,39711,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби щілина була значно ширшою, суб''єкт ... вперед, а не боком.'::text,'ішов би'::text,'піде'::text,'іде'::text,'Якби щілина була значно ширшою, суб''єкт ішов би вперед, а не боком.'::text),
(357396,39711,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el hueco fuera considerablemente más ancho, el sujeto ... hacia delante en lugar de lateralmente.'::text,'caminaría'::text,'caminará'::text,'camina'::text,'Si el hueco fuera considerablemente más ancho, el sujeto caminaría hacia delante en lugar de lateralmente.'::text),
(357395,39711,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''interstice était nettement plus large, le sujet ... vers l''avant plutôt que de côté.'::text,'marcherait'::text,'marchera'::text,'marche'::text,'Si l''interstice était nettement plus large, le sujet marcherait vers l''avant plutôt que de côté.'::text),
(357398,39711,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşluk kayda değer ölçüde daha geniş olsaydı, denek yan yan değil ileri doğru ...'::text,'yürürdü'::text,'yürüyecek'::text,'yürüyor'::text,'Boşluk kayda değer ölçüde daha geniş olsaydı, denek yan yan değil ileri doğru yürürdü.'::text),
(357399,39711,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a rés jelentősen szélesebb lenne, az alany előre ... oldalazás helyett.'::text,'menne'::text,'fog menni'::text,'megy'::text,'Ha a rés jelentősen szélesebb lenne, az alany előre menne oldalazás helyett.'::text),
(357420,39714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... die Lücke sehr eng war, kam er mit Rucksack durch.'::text,'Obwohl'::text,'Trotz'::text,'Weil'::text,'Obwohl die Lücke sehr eng war, kam er mit Rucksack durch.'::text),
(357424,39714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... щілина була дуже вузька, він пройшов крізь неї з рюкзаком на спині.'::text,'Хоча'::text,'Попри'::text,'Бо'::text,'Хоча щілина була дуже вузька, він пройшов крізь неї з рюкзаком на спині.'::text),
(357423,39714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el hueco era muy estrecho, pasó con la mochila puesta.'::text,'Aunque'::text,'A pesar de'::text,'Porque'::text,'Aunque el hueco era muy estrecho, pasó con la mochila puesta.'::text),
(357422,39714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''interstice était très étroit, il est passé avec son sac à dos.'::text,'Même si'::text,'Malgré'::text,'Parce que'::text,'Même si l''interstice était très étroit, il est passé avec son sac à dos.'::text),
(357425,39714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşluk çok dar ..., sırt çantasıyla geçti.'::text,'olmasına rağmen'::text,'rağmen'::text,'olduğu için'::text,'Boşluk çok dar olmasına rağmen, sırt çantasıyla geçti.'::text),
(357426,39714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a rés nagyon szűk volt, átjutott a hátizsákjával.'::text,'Bár'::text,'Ellenére'::text,'Mivel'::text,'Bár a rés nagyon szűk volt, átjutott a hátizsákjával.'::text),
(357429,39715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende der Reise ... er sich durch jede enge Lücke der Stadt gezwängt haben. Voll entspannend, klar.'::text,'wird'::text,'wird'::text,'zwängt'::text,'Bis zum Ende der Reise wird er sich durch jede enge Lücke der Stadt gezwängt haben. Voll entspannend, klar.'::text),
(357433,39715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця подорожі він ... крізь кожну вузьку щілину в місті. Явно відпочинок.'::text,'протиснеться'::text,'протиснеться'::text,'протискається'::text,'До кінця подорожі він протиснеться крізь кожну вузьку щілину в місті. Явно відпочинок.'::text),
(357432,39715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final del viaje, se ... por cada hueco estrecho de la ciudad. Relajante, está claro.'::text,'habrá colado'::text,'colará'::text,'cuela'::text,'Para el final del viaje, se habrá colado por cada hueco estrecho de la ciudad. Relajante, está claro.'::text),
(357431,39715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du voyage, il se ... dans chaque passage étroit de la ville. Super reposant, clairement.'::text,'sera faufilé'::text,'faufilera'::text,'faufile'::text,'D''ici la fin du voyage, il se sera faufilé dans chaque passage étroit de la ville. Super reposant, clairement.'::text),
(357434,39715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gezinin sonuna kadar şehirdeki her dar boşluktan ..., belli ki çok dinlendirici.'::text,'geçmiş olacak'::text,'geçecek'::text,'geçiyor'::text,'Gezinin sonuna kadar şehirdeki her dar boşluktan geçmiş olacak, belli ki çok dinlendirici.'::text),
(357435,39715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utazás végére ... a város minden szűk résén. Nyilván pihentető.'::text,'átpréselődik'::text,'átpréselődik'::text,'préselődik át'::text,'Az utazás végére átpréselődik a város minden szűk résén. Nyilván pihentető.'::text),
(376689,41855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, angeblich ... sie vor den Gefängnistoren, als er rauskam.'::text,'wartete'::text,'wartete'::text,'hat gewartet'::text,'Girl, angeblich wartete sie vor den Gefängnistoren, als er rauskam.'::text),
(376693,41855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона ... біля воріт в''язниці, коли він вийшов.'::text,'чекала'::text,'зачекала'::text,'почекала'::text,'Подруго, кажуть, вона чекала біля воріт в''язниці, коли він вийшов.'::text),
(376692,41855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que ... en las puertas de la cárcel cuando él salió.'::text,'estaba esperando'::text,'esperó'::text,'ha esperado'::text,'Amiga, parece que estaba esperando en las puertas de la cárcel cuando él salió.'::text),
(376691,41855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle ... devant les portes de la prison quand il est sorti.'::text,'attendait'::text,'a attendu'::text,'a attendu'::text,'Meuf, apparemment elle attendait devant les portes de la prison quand il est sorti.'::text),
(376694,41855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, söylenene göre o çıktığında hapishane kapısının önünde ...'::text,'bekliyormuş'::text,'beklemiş'::text,'beklemiş'::text,'Kızım, söylenene göre o çıktığında hapishane kapısının önünde bekliyormuş.'::text),
(376695,41855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ott ... a börtön kapuja előtt, amikor kijött.'::text,'várt'::text,'megvárta'::text,'várt'::text,'Csajszi, állítólag ott várt a börtön kapuja előtt, amikor kijött.'::text),
(376698,41856,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Familien ... schon seit Mittag vor dem Gefängnis. Eine sehr kurze Wartezeit, klar.'::text,'warten'::text,'warten'::text,'warten'::text,'Diese Familien warten schon seit Mittag vor dem Gefängnis. Eine sehr kurze Wartezeit, klar.'::text),
(376702,41856,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці родини ... біля в''язниці з полудня. Дуже коротке очікування, звісно.'::text,'чекають'::text,'чекають'::text,'чекають'::text,'Ці родини чекають біля в''язниці з полудня. Дуже коротке очікування, звісно.'::text),
(376701,41856,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estas familias ... fuera de la cárcel desde el mediodía. Una espera cortísima, claro.'::text,'llevan esperando'::text,'están esperando'::text,'esperan'::text,'Estas familias llevan esperando fuera de la cárcel desde el mediodía. Una espera cortísima, claro.'::text),
(376700,41856,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces familles ... devant la prison depuis midi. Une attente très courte, clairement.'::text,'attendent'::text,'attendent'::text,'attendent'::text,'Ces familles attendent devant la prison depuis midi. Une attente très courte, clairement.'::text),
(376703,41856,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu aileler öğlenden beri hapishanenin önünde ..., çok kısa bir bekleyiş tabii.'::text,'bekliyor'::text,'bekliyor'::text,'bekler'::text,'Bu aileler öğlenden beri hapishanenin önünde bekliyor, çok kısa bir bekleyiş tabii.'::text),
(376704,41856,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezek a családok dél óta ... a börtön előtt. Nagyon rövid várakozás, egyértelműen.'::text,'várnak'::text,'várnak'::text,'várnak'::text,'Ezek a családok dél óta várnak a börtön előtt. Nagyon rövid várakozás, egyértelműen.'::text),
(376707,41857,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Männer ... bei Sonnenuntergang aus dem Gefängnis entlassen. Tolles Timing, offensichtlich.'::text,'wurden'::text,'entließen'::text,'entlassend'::text,'Die Männer wurden bei Sonnenuntergang aus dem Gefängnis entlassen. Tolles Timing, offensichtlich.'::text),
(376711,41857,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловіки ... з в''язниці на заході сонця. Чудовий таймінг, звісно.'::text,'були звільнені'::text,'звільнили'::text,'звільняючи'::text,'Чоловіки були звільнені з в''язниці на заході сонця. Чудовий таймінг, звісно.'::text),
(376710,41857,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los hombres ... de la cárcel al atardecer. Gran timing, obviamente.'::text,'fueron liberados'::text,'liberaron'::text,'liberando'::text,'Los hombres fueron liberados de la cárcel al atardecer. Gran timing, obviamente.'::text),
(376709,41857,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hommes ... de prison au coucher du soleil. Super timing, évidemment.'::text,'ont été libérés'::text,'ont libéré'::text,'libérant'::text,'Les hommes ont été libérés de prison au coucher du soleil. Super timing, évidemment.'::text),
(376712,41857,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlar gün batımında hapisten ..., harika zamanlama tabii ki.'::text,'tahliye edildi'::text,'tahliye etti'::text,'tahliye ederek'::text,'Adamlar gün batımında hapisten tahliye edildi, harika zamanlama tabii ki.'::text),
(376713,41857,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfiakat naplementekor ... a börtönből. Remek időzítés, nyilván.'::text,'engedték ki'::text,'kiengedték'::text,'kiengedve'::text,'A férfiakat naplementekor engedték ki a börtönből. Remek időzítés, nyilván.'::text),
(376716,41858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Typ ... voll happy sein, aus dem Knast raus zu sein, echt.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Bro, der Typ muss voll happy sein, aus dem Knast raus zu sein, echt.'::text),
(376720,41858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, цей чувак ... бути страшенно щасливим, що вийшов з тюрми, реально.'::text,'мусить'::text,'не може'::text,'не повинен'::text,'Бро, цей чувак мусить бути страшенно щасливим, що вийшов з тюрми, реально.'::text),
(376719,41858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ese tío ... estar feliz de haber salido de la cárcel, en serio.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Bro, ese tío debe de estar feliz de haber salido de la cárcel, en serio.'::text),
(376718,41858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, ce mec ... être trop content d''être sorti de taule, grave.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Frère, ce mec doit être trop content d''être sorti de taule, grave.'::text),
(376721,41858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o adam hapisten çıktığı için çok mutlu ..., cidden.'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Kanka, o adam hapisten çıktığı için çok mutlu olmalı, cidden.'::text),
(376722,41858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az a csávó ... nagyon boldog, hogy kijött a sittről, komolyan.'::text,'biztos'::text,'nem lehet'::text,'nem kéne, hogy legyen'::text,'Tesó, az a csávó biztos nagyon boldog, hogy kijött a sittről, komolyan.'::text),
(376725,41859,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, der Typ, ... als Erster aus dem Knast kam, ging direkt zu der Frau, echt.'::text,'der'::text,'der'::text,'dessen'::text,'Nee, der Typ, der als Erster aus dem Knast kam, ging direkt zu der Frau, echt.'::text),
(376729,41859,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні, той чувак, ... першим вийшов з тюрми, пішов просто до тієї жінки, реально.'::text,'який'::text,'який'::text,'чий'::text,'Ні, той чувак, який першим вийшов з тюрми, пішов просто до тієї жінки, реально.'::text),
(376728,41859,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, el tío ... salió primero de la cárcel fue directo a esa mujer, en serio.'::text,'que'::text,'que'::text,'cuyo'::text,'Qué va, el tío que salió primero de la cárcel fue directo a esa mujer, en serio.'::text),
(376727,41859,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non, le mec ... est sorti de taule en premier est allé direct vers cette femme, grave.'::text,'qui'::text,'qui'::text,'dont'::text,'Non, le mec qui est sorti de taule en premier est allé direct vers cette femme, grave.'::text),
(376730,41859,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, hapisten ilk ... adam direkt o kadına gitti, cidden.'::text,'çıkan'::text,NULL::text,NULL::text,'Yok, hapisten ilk çıkan adam direkt o kadına gitti, cidden.'::text),
(376731,41859,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, a csávó, ... elsőként jött ki a sittről, egyből ahhoz a nőhöz ment, komolyan.'::text,'aki'::text,'amelyik'::text,'akinek a'::text,'Nem, a csávó, aki elsőként jött ki a sittről, egyből ahhoz a nőhöz ment, komolyan.'::text),
(376743,41861,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der bärtige Mann ... früher in diesem Gefängnis, aber jetzt geht er nach Hause.'::text,'lebte'::text,'würde leben'::text,'war gewohnt zu leben'::text,'Der bärtige Mann lebte früher in diesem Gefängnis, aber jetzt geht er nach Hause.'::text),
(376747,41861,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бородатий чоловік ... в цій в''язниці, але тепер він їде додому.'::text,'колись жив'::text,'жив би'::text,'звик жити'::text,'Бородатий чоловік колись жив в цій в''язниці, але тепер він їде додому.'::text),
(376746,41861,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre de barba ... vivir en esta cárcel, pero ahora se va a casa.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'El hombre de barba solía vivir en esta cárcel, pero ahora se va a casa.'::text),
(376745,41861,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme barbu ... dans cette prison, mais maintenant il rentre chez lui.'::text,'vivait'::text,'vivrait'::text,'avait l''habitude de vivre'::text,'L''homme barbu vivait dans cette prison, mais maintenant il rentre chez lui.'::text),
(376748,41861,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sakallı adam eskiden bu hapishanede ..., ama şimdi eve gidiyor.'::text,'yaşardı'::text,'yaşardı'::text,'yaşamaya alışkındı'::text,'Sakallı adam eskiden bu hapishanede yaşardı, ama şimdi eve gidiyor.'::text),
(376749,41861,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szakállas férfi régen ebben a börtönben ..., de most hazamegy.'::text,'élt'::text,'élne'::text,'volt hozzászokva élni'::text,'A szakállas férfi régen ebben a börtönben élt, de most hazamegy.'::text),
(376752,41862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Männer freuen sich darauf, nach dem Gefängnis nach Hause ...'::text,'zu gehen'::text,'gehen'::text,'zu gehen'::text,'Die Männer freuen sich darauf, nach dem Gefängnis nach Hause zu gehen.'::text),
(376756,41862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловіки з нетерпінням чекають, коли ... додому після в''язниці.'::text,'підуть'::text,'іти'::text,'піти'::text,'Чоловіки з нетерпінням чекають, коли підуть додому після в''язниці.'::text),
(376755,41862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los hombres tienen ganas de ... a casa después de la cárcel.'::text,'ir'::text,'ir'::text,'ir'::text,'Los hombres tienen ganas de ir a casa después de la cárcel.'::text),
(376754,41862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hommes ont hâte de ... chez eux après la prison.'::text,'rentrer'::text,'rentrer'::text,'rentrer'::text,'Les hommes ont hâte de rentrer chez eux après la prison.'::text),
(376757,41862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adamlar hapisten sonra eve ... sabırsızlanıyor.'::text,'gitmek için'::text,'gitmek'::text,'gitmeye'::text,'Adamlar hapisten sonra eve gitmek için sabırsızlanıyor.'::text),
(376758,41862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfiak alig várják, hogy a börtön után ... haza.'::text,'menjenek'::text,'menni'::text,'menni'::text,'A férfiak alig várják, hogy a börtön után menjenek haza.'::text),
(376761,41863,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach Jahren ... umarmt der bärtige Mann seine Familie.'::text,'im Gefängnis'::text,'in dem Gefängnis'::text,'in einem Gefängnis'::text,'Nach Jahren im Gefängnis umarmt der bärtige Mann seine Familie.'::text),
(376765,41863,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після років у ... бородатий чоловік обіймає свою родину.'::text,'в''язниці'::text,'в''язниці'::text,'в''язниці'::text,'Після років у в''язниці бородатий чоловік обіймає свою родину.'::text),
(376764,41863,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tras años en ..., el hombre de barba abraza a su familia.'::text,'la cárcel'::text,'la cárcel'::text,'una cárcel'::text,'Tras años en la cárcel, el hombre de barba abraza a su familia.'::text),
(376763,41863,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après des années ..., l''homme barbu serre sa famille dans ses bras.'::text,'en prison'::text,'dans la prison'::text,'dans une prison'::text,'Après des années en prison, l''homme barbu serre sa famille dans ses bras.'::text),
(376766,41863,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yıllarca ... kaldıktan sonra sakallı adam ailesine sarılıyor.'::text,'hapiste'::text,'hapiste'::text,'bir hapiste'::text,'Yıllarca hapiste kaldıktan sonra sakallı adam ailesine sarılıyor.'::text),
(376767,41863,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... töltött évek után a szakállas férfi megöleli a családját.'::text,'Börtönben'::text,'A börtönben'::text,'Egy börtönben'::text,'Börtönben töltött évek után a szakállas férfi megöleli a családját.'::text),
(376770,41864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, die sagen, er ... gerade aus dem Gefängnis, und sie weint!'::text,'läuft'::text,'läuft'::text,'ist gelaufen'::text,'Omg, die sagen, er läuft gerade aus dem Gefängnis, und sie weint!'::text),
(376774,41864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, кажуть, він прямо зараз ... з в''язниці, а вона плаче!'::text,'виходить'::text,'виходить'::text,'вийшов'::text,'Боже, кажуть, він прямо зараз виходить з в''язниці, а вона плаче!'::text),
(376773,41864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dios, dicen que ... de la cárcel ahora mismo y ella está llorando!'::text,'está saliendo'::text,'sale'::text,'ha salido'::text,'¡Dios, dicen que está saliendo de la cárcel ahora mismo y ella está llorando!'::text),
(376772,41864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, on dit qu''il ... de prison là maintenant, et elle pleure !'::text,'est en train de sortir'::text,'sort'::text,'est sorti'::text,'Omg, on dit qu''il est en train de sortir de prison là maintenant, et elle pleure !'::text),
(376775,41864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, dediklerine göre şu an hapisten ... ve kadın ağlıyor!'::text,'çıkıyormuş'::text,'çıkarmış'::text,'çıkmış'::text,'Aman tanrım, dediklerine göre şu an hapisten çıkıyormuş ve kadın ağlıyor!'::text),
(376776,41864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, azt mondják, épp most ... ki a börtönből, és a nő sír!'::text,'jön'::text,'jön'::text,'jött'::text,'Úristen, azt mondják, épp most jön ki a börtönből, és a nő sír!'::text),
(330402,36712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jetzt schon seit zwei Minuten durch die ganze Hymne. Total trockene Augen, offensichtlich.'::text,'weint'::text,'weint'::text,'weint'::text,'Sie weint jetzt schon seit zwei Minuten durch die ganze Hymne. Total trockene Augen, offensichtlich.'::text),
(330406,36712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під час гімну вона ... вже дві хвилини. Абсолютно сухі очі, звісно.'::text,'плаче'::text,'плаче'::text,'плаче'::text,'Під час гімну вона плаче вже дві хвилини. Абсолютно сухі очі, звісно.'::text),
(330405,36712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... durante todo el himno desde hace dos minutos. Ojos totalmente secos, obviamente.'::text,'Llora'::text,'Está llorando'::text,'Llora'::text,'Llora durante todo el himno desde hace dos minutos. Ojos totalmente secos, obviamente.'::text),
(330404,36712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait deux minutes qu''elle ... pendant l''hymne. Les yeux complètement secs, évidemment.'::text,'pleure'::text,'pleure'::text,'pleure'::text,'Ça fait deux minutes qu''elle pleure pendant l''hymne. Les yeux complètement secs, évidemment.'::text),
(330407,36712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Marş boyunca iki dakikadır ..., gözleri tamamen kupkuru tabii ki.'::text,'ağlıyor'::text,'ağlıyor'::text,'ağlar'::text,'Marş boyunca iki dakikadır ağlıyor, gözleri tamamen kupkuru tabii ki.'::text),
(330408,36712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már két perce ... a himnusz alatt. Teljesen száraz szemek, nyilván.'::text,'sír'::text,'sír'::text,'sír'::text,'Már két perce sír a himnusz alatt. Teljesen száraz szemek, nyilván.'::text),
(330411,36713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... gerade die Hymne, als die Tränen kamen, ohne Witz.'::text,'sang'::text,'sang'::text,'hat gesungen'::text,'Bro, sie sang gerade die Hymne, als die Tränen kamen, ohne Witz.'::text),
(330415,36713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... гімн, коли покотилися сльози, без брехні.'::text,'співала'::text,'заспівала'::text,'заспівала'::text,'Бро, вона співала гімн, коли покотилися сльози, без брехні.'::text),
(330414,36713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... el himno cuando empezaron las lágrimas, sin mentir.'::text,'estaba cantando'::text,'cantó'::text,'ha cantado'::text,'Bro, estaba cantando el himno cuando empezaron las lágrimas, sin mentir.'::text),
(330413,36713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle ... l''hymne quand les larmes ont commencé, sans mentir.'::text,'chantait'::text,'a chanté'::text,'a chanté'::text,'Frère, elle chantait l''hymne quand les larmes ont commencé, sans mentir.'::text),
(330416,36713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gözyaşları başladığında marşı ..., yemin ederim.'::text,'söylüyordu'::text,'söyledi'::text,'söyledi'::text,'Kanka, gözyaşları başladığında marşı söylüyordu, yemin ederim.'::text),
(330417,36713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp ... a himnuszt, amikor jöttek a könnyek, komolyan.'::text,'énekelte'::text,'elénekelte'::text,'elénekelte'::text,'Tesó, épp énekelte a himnuszt, amikor jöttek a könnyek, komolyan.'::text),
(330420,36714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, als die Hymne vorbei war, ... sie schon so dreimal geweint, echt.'::text,'hatte'::text,'hat'::text,'weinte'::text,'Alter, als die Hymne vorbei war, hatte sie schon so dreimal geweint, echt.'::text),
(330424,36714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, поки гімн закінчився, вона вже ... разів три, реально.'::text,'розплакалася'::text,'розплакалася'::text,'розплакалася'::text,'Чувак, поки гімн закінчився, вона вже розплакалася разів три, реально.'::text),
(330423,36714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, para cuando terminó el himno, ya ... como tres veces, en serio.'::text,'había llorado'::text,'ha llorado'::text,'lloró'::text,'Tío, para cuando terminó el himno, ya había llorado como tres veces, en serio.'::text),
(330422,36714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, quand l''hymne s''est terminé, elle ... déjà genre trois fois, grave.'::text,'avait pleuré'::text,'a pleuré'::text,'a pleuré'::text,'Mec, quand l''hymne s''est terminé, elle avait pleuré déjà genre trois fois, grave.'::text),
(330425,36714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dostum, marş bittiğinde çoktan üç kez falan ..., cidden.'::text,'ağlamıştı'::text,'ağladı'::text,'ağladı'::text,'Dostum, marş bittiğinde çoktan üç kez falan ağlamıştı, cidden.'::text),
(330426,36714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, mire a himnusznak vége lett, már vagy háromszor ..., komolyan.'::text,'elsírta magát'::text,'elsírta magát'::text,'elsírta magát'::text,'Haver, mire a himnusznak vége lett, már vagy háromszor elsírta magát, komolyan.'::text),
(330429,36715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... das Team vor dem Finale die Hymne singen.'::text,'wird'::text,'wird'::text,'singt'::text,'Morgen um diese Zeit wird das Team vor dem Finale die Hymne singen.'::text),
(330433,36715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час команда ... гімн перед фіналом.'::text,'співатиме'::text,'заспіває'::text,'співає'::text,'Завтра в цей час команда співатиме гімн перед фіналом.'::text),
(330432,36715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el equipo ... el himno antes de la final.'::text,'estará cantando'::text,'cantará'::text,'canta'::text,'Mañana a esta hora, el equipo estará cantando el himno antes de la final.'::text),
(330431,36715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, l''équipe ... l''hymne avant la finale.'::text,'sera en train de chanter'::text,'chantera'::text,'chante'::text,'Demain à la même heure, l''équipe sera en train de chanter l''hymne avant la finale.'::text),
(330434,36715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte takım finalden önce marşı ...'::text,'söylüyor olacak'::text,'söyleyecek'::text,'söylüyor'::text,'Yarın bu saatte takım finalden önce marşı söylüyor olacak.'::text),
