(350215,38913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона розчулилася під час пісні, і ...'::text,'її подруги по команді теж.'::text,'її подруги по команді теж ні.'::text,'її подруги по команді теж.'::text,'Подруго, кажуть, вона розчулилася під час пісні, і її подруги по команді теж.'::text),
(350214,38913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que se emocionó durante la canción, y ...'::text,'sus compañeras también.'::text,'sus compañeras tampoco.'::text,'sus compañeras también.'::text,'Amiga, parece que se emocionó durante la canción, y sus compañeras también.'::text),
(350213,38913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle a été émue pendant la chanson, et ...'::text,'ses coéquipières aussi.'::text,'ses coéquipières non plus.'::text,'ses coéquipières aussi.'::text,'Meuf, apparemment elle a été émue pendant la chanson, et ses coéquipières aussi.'::text),
(350216,38913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, söylenene göre şarkı sırasında duygulanmış, ...'::text,'takım arkadaşları da.'::text,'takım arkadaşları da duygulanmamış.'::text,'takım arkadaşları da.'::text,'Kızım, söylenene göre şarkı sırasında duygulanmış, takım arkadaşları da.'::text),
(350217,38913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag elérzékenyült a dal alatt, és ...'::text,'a csapattársai is.'::text,'a csapattársai sem.'::text,'a csapattársai is.'::text,'Csajszi, állítólag elérzékenyült a dal alatt, és a csapattársai is.'::text),
(350220,38914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... das ganze Lied lang gesungen, bevor du zu emotional wurdest, um weiterzumachen.'::text,'hattest'::text,'hast'::text,'singst'::text,'Ehrlich, du hattest das ganze Lied lang gesungen, bevor du zu emotional wurdest, um weiterzumachen.'::text),
(350224,38914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... всю пісню, перш ніж надто розчулилася, щоб продовжувати.'::text,'співала'::text,'співаєш'::text,'співаєш'::text,'Чесно, ти співала всю пісню, перш ніж надто розчулилася, щоб продовжувати.'::text),
(350223,38914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... toda la canción antes de emocionarte demasiado para seguir.'::text,'habías estado cantando'::text,'has estado cantando'::text,'estás cantando'::text,'Sinceramente, habías estado cantando toda la canción antes de emocionarte demasiado para seguir.'::text),
(350222,38914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... pendant toute la chanson avant d''être trop émue pour continuer.'::text,'avais chanté'::text,'as chanté'::text,'chantes'::text,'Franchement, tu avais chanté pendant toute la chanson avant d''être trop émue pour continuer.'::text),
(350225,38914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, devam edemeyecek kadar duygulanmadan önce bütün şarkı boyunca ...'::text,'söylüyordun'::text,'söylüyorsun'::text,'söylüyorsun'::text,'Açıkçası, devam edemeyecek kadar duygulanmadan önce bütün şarkı boyunca söylüyordun.'::text),
(350226,38914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, az egész dalt ..., mielőtt túlságosan elérzékenyültél ahhoz, hogy folytasd.'::text,'végigénekelted'::text,'énekled'::text,'énekled'::text,'Őszintén, az egész dalt végigénekelted, mielőtt túlságosan elérzékenyültél ahhoz, hogy folytasd.'::text),
(350238,38916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Abpfiff ... diese emotionale Spielerin neunzig Minuten lang geweint haben. Total ruhig, offensichtlich.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis zum Abpfiff wird diese emotionale Spielerin neunzig Minuten lang geweint haben. Total ruhig, offensichtlich.'::text),
(350242,38916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До фінального свистка ця емоційна гравчиня ... дев''яносто хвилин. Абсолютно спокійна, звісно.'::text,'проплаче'::text,'плакатиме'::text,'плакатиме'::text,'До фінального свистка ця емоційна гравчиня проплаче дев''яносто хвилин. Абсолютно спокійна, звісно.'::text),
(350241,38916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final del partido, esta jugadora tan emotiva ... noventa minutos. Totalmente tranquila, obviamente.'::text,'habrá estado llorando'::text,'estará llorando'::text,'llorará'::text,'Al final del partido, esta jugadora tan emotiva habrá estado llorando noventa minutos. Totalmente tranquila, obviamente.'::text),
(350240,38916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin du match, cette joueuse émotive ... pendant quatre-vingt-dix minutes. Totalement calme, évidemment.'::text,'aura pleuré'::text,'sera en train de pleurer'::text,'pleurera'::text,'D''ici la fin du match, cette joueuse émotive aura pleuré pendant quatre-vingt-dix minutes. Totalement calme, évidemment.'::text),
(350243,38916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maç bittiğinde bu duygusal oyuncu doksan dakika boyunca ..., tamamen sakin tabii ki.'::text,'ağlamış olacak'::text,'ağlıyor olacak'::text,'ağlayacak'::text,'Maç bittiğinde bu duygusal oyuncu doksan dakika boyunca ağlamış olacak, tamamen sakin tabii ki.'::text),
(350244,38916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lefújásig ez az érzelmes játékos ... kilencven percen át. Teljesen nyugodt, nyilván.'::text,'sírni fog'::text,'sírni fog'::text,'sírni fog'::text,'A lefújásig ez az érzelmes játékos sírni fog kilencven percen át. Teljesen nyugodt, nyilván.'::text),
(350247,38917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie nicht so emotional gewesen wäre, ... sie das ganze Lied zu Ende gesungen. Nicht ideal.'::text,'hätte'::text,'würde'::text,'sang'::text,'Wenn sie nicht so emotional gewesen wäre, hätte sie das ganze Lied zu Ende gesungen. Nicht ideal.'::text),
(350251,38917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не була такою емоційною, вона ... всю пісню. Не ідеально.'::text,'доспівала б'::text,'доспівала б'::text,'доспівала'::text,'Якби вона не була такою емоційною, вона доспівала б всю пісню. Не ідеально.'::text),
(350250,38917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera estado tan emocionada, ... toda la canción. No es lo ideal.'::text,'habría terminado'::text,'terminaría'::text,'terminó'::text,'Si no hubiera estado tan emocionada, habría terminado toda la canción. No es lo ideal.'::text),
(350249,38917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas été aussi émue, elle ... toute la chanson. Pas idéal.'::text,'aurait fini'::text,'finirait'::text,'a fini'::text,'Si elle n''avait pas été aussi émue, elle aurait fini toute la chanson. Pas idéal.'::text),
(350252,38917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar duygusal olmasaydı şarkının tamamını ..., hiç ideal değil.'::text,'bitirmiş olurdu'::text,'bitirirdi'::text,'bitirdi'::text,'Bu kadar duygusal olmasaydı şarkının tamamını bitirmiş olurdu, hiç ideal değil.'::text),
(350253,38917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lett volna ennyire érzelmes, ... az egész dalt. Nem ideális.'::text,'végigénekelte volna'::text,'végigénekelné'::text,'végigénekelte'::text,'Ha nem lett volna ennyire érzelmes, végigénekelte volna az egész dalt. Nem ideális.'::text),
(350256,38918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bruh, wenn sie nicht so emotional geworden wäre, ... sie jetzt noch mit dem Team am Singen, echt.'::text,'wäre'::text,'wäre gewesen'::text,'wird'::text,'Bruh, wenn sie nicht so emotional geworden wäre, wäre sie jetzt noch mit dem Team am Singen, echt.'::text),
(350260,38918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби вона так не розчулилася, вона ... з командою прямо зараз, реально.'::text,'досі співала б'::text,'досі співала б'::text,'досі співатиме'::text,'Бро, якби вона так не розчулилася, вона досі співала б з командою прямо зараз, реально.'::text),
(350259,38918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si no se hubiera emocionado tanto, ... cantando con el equipo ahora mismo, en serio.'::text,'seguiría'::text,'habría seguido'::text,'seguirá'::text,'Bro, si no se hubiera emocionado tanto, seguiría cantando con el equipo ahora mismo, en serio.'::text),
(350258,38918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si elle n''avait pas été aussi émue, elle ... en train de chanter avec l''équipe là, grave.'::text,'serait encore'::text,'aurait encore été'::text,'sera encore'::text,'Frère, si elle n''avait pas été aussi émue, elle serait encore en train de chanter avec l''équipe là, grave.'::text),
(350261,38918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu kadar duygulanmasaydı şu an hâlâ takımla şarkı ..., cidden.'::text,'söylüyor olurdu'::text,'söylüyor olmuş olurdu'::text,'söylüyor olacak'::text,'Kanka, bu kadar duygulanmasaydı şu an hâlâ takımla şarkı söylüyor olurdu, cidden.'::text),
(350262,38918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nem érzékenyült volna el ennyire, most is ... a csapattal, komolyan.'::text,'énekelne'::text,'énekelt volna'::text,'énekelni fog'::text,'Tesó, ha nem érzékenyült volna el ennyire, most is énekelne a csapattal, komolyan.'::text),
(377274,41920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine ältere Frau ... gerade ins Mikrofon, als der ganze Pub zu jubeln begann.'::text,'sang'::text,'sang'::text,'hat gesungen'::text,'Eine ältere Frau sang gerade ins Mikrofon, als der ganze Pub zu jubeln begann.'::text),
(377278,41920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літня жінка ... в мікрофон, коли весь паб почав радісно вигукувати.'::text,'співала'::text,'заспівала'::text,'заспівала'::text,'Літня жінка співала в мікрофон, коли весь паб почав радісно вигукувати.'::text),
(377277,41920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una señora mayor ... al micrófono cuando todo el pub empezó a vitorear.'::text,'estaba cantando'::text,'cantó'::text,'ha cantado'::text,'Una señora mayor estaba cantando al micrófono cuando todo el pub empezó a vitorear.'::text),
(377276,41920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une dame âgée ... dans le micro quand tout le pub s''est mis à acclamer.'::text,'chantait'::text,'a chanté'::text,'a chanté'::text,'Une dame âgée chantait dans le micro quand tout le pub s''est mis à acclamer.'::text),
(377279,41920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün pub tezahürat yapmaya başladığında yaşlı bir kadın mikrofona ...'::text,'şarkı söylüyordu'::text,'şarkı söyledi'::text,'şarkı söyledi'::text,'Bütün pub tezahürat yapmaya başladığında yaşlı bir kadın mikrofona şarkı söylüyordu.'::text),
(377280,41920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy idős nő épp ... a mikrofonba, amikor az egész kocsma ujjongani kezdett.'::text,'énekelt'::text,'belénekelt'::text,'belénekelt'::text,'Egy idős nő épp énekelt a mikrofonba, amikor az egész kocsma ujjongani kezdett.'::text),
(377283,41921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Leute in diesem Pub ... die ganze Nacht schon Lieder.'::text,'singen'::text,'sangen'::text,'singen'::text,'Die Leute in diesem Pub singen die ganze Nacht schon Lieder.'::text),
(377287,41921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди в цьому пабі ... пісні всю ніч.'::text,'співають'::text,'співали'::text,'співають'::text,'Люди в цьому пабі співають пісні всю ніч.'::text),
(377286,41921,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gente de este pub ... canciones toda la noche.'::text,'lleva cantando'::text,'cantó'::text,'está cantando'::text,'La gente de este pub lleva cantando canciones toda la noche.'::text),
(377285,41921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gens de ce pub ... des chansons toute la nuit.'::text,'chantent'::text,'ont chanté'::text,'chantent'::text,'Les gens de ce pub chantent des chansons toute la nuit.'::text),
(377288,41921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu pubdaki insanlar bütün gece şarkı ...'::text,'söylüyor'::text,'söyledi'::text,'söylüyor'::text,'Bu pubdaki insanlar bütün gece şarkı söylüyor.'::text),
(377289,41921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a kocsmában az emberek egész éjjel ... a dalokat.'::text,'éneklik'::text,'énekelték'::text,'éneklik'::text,'Ebben a kocsmában az emberek egész éjjel éneklik a dalokat.'::text),
(377292,41922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die alte Frau sang, ... der Pub schon jedes Lied gehört. Wirklich eine ruhige Nacht.'::text,'hatte'::text,'hat'::text,'hört'::text,'Als die alte Frau sang, hatte der Pub schon jedes Lied gehört. Wirklich eine ruhige Nacht.'::text),
(377296,41922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки стара пані заспівала, паб уже ... кожну пісню. Справді тиха ніч.'::text,'почув'::text,'почув'::text,'чує'::text,'Поки стара пані заспівала, паб уже почув кожну пісню. Справді тиха ніч.'::text),
(377295,41922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando la señora cantó, el pub ya ... todas las canciones. Una noche muy tranquila, de verdad.'::text,'había oído'::text,'ha oído'::text,'oye'::text,'Para cuando la señora cantó, el pub ya había oído todas las canciones. Una noche muy tranquila, de verdad.'::text),
(377294,41922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la vieille dame a chanté, le pub ... déjà entendu toutes les chansons. Vraiment une nuit calme.'::text,'avait'::text,'a'::text,'entend'::text,'Quand la vieille dame a chanté, le pub avait déjà entendu toutes les chansons. Vraiment une nuit calme.'::text),
(377297,41922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı kadın şarkı söylediğinde pub her şarkıyı çoktan ..., gerçekten sakin bir gece.'::text,'duymuştu'::text,'duydu'::text,'duyuyor'::text,'Yaşlı kadın şarkı söylediğinde pub her şarkıyı çoktan duymuştu, gerçekten sakin bir gece.'::text),
(377298,41922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az idős nő énekelt, a kocsma ... már minden dalt. Tényleg csendes éjszaka.'::text,'hallott'::text,'hallott'::text,'hall'::text,'Mire az idős nő énekelt, a kocsma hallott már minden dalt. Tényleg csendes éjszaka.'::text),
(377301,41923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um Mitternacht ... der ganze Pub immer noch mit ihr mitsingen. Ein ruhiger Abend, offensichtlich.'::text,'wird'::text,'wird'::text,'singt'::text,'Um Mitternacht wird der ganze Pub immer noch mit ihr mitsingen. Ein ruhiger Abend, offensichtlich.'::text),
(377305,41923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Опівночі весь паб ... разом з нею. Спокійний вечір, звісно.'::text,'усе ще співатиме'::text,'усе ще співатиме'::text,'усе ще співає'::text,'Опівночі весь паб усе ще співатиме разом з нею. Спокійний вечір, звісно.'::text),
(377304,41923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A medianoche, todo el pub ... con ella. Una noche tranquila, obviamente.'::text,'seguirá cantando'::text,'seguirá cantando'::text,'sigue cantando'::text,'A medianoche, todo el pub seguirá cantando con ella. Una noche tranquila, obviamente.'::text),
(377303,41923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À minuit, tout le pub ... avec elle. Une soirée calme, évidemment.'::text,'chantera encore'::text,'chantera encore'::text,'chante encore'::text,'À minuit, tout le pub chantera encore avec elle. Une soirée calme, évidemment.'::text),
(377306,41923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısı bütün pub hâlâ onunla birlikte ..., sakin bir akşam tabii ki.'::text,'şarkı söylüyor olacak'::text,'şarkı söyleyecek'::text,'şarkı söylüyor'::text,'Gece yarısı bütün pub hâlâ onunla birlikte şarkı söylüyor olacak, sakin bir akşam tabii ki.'::text),
(377307,41923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélkor az egész kocsma még mindig ... vele. Nyugodt este, nyilván.'::text,'énekelni fog'::text,'énekelni fog'::text,'énekel'::text,'Éjfélkor az egész kocsma még mindig énekelni fog vele. Nyugodt este, nyilván.'::text),
(377310,41924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, gib mir das Mikro, ich ... ein Lied für den ganzen Pub, ohne Witz.'::text,'singe'::text,'werde singen'::text,'singe gerade'::text,'Bro, gib mir das Mikro, ich singe ein Lied für den ganzen Pub, ohne Witz.'::text),
(377314,41924,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, дай мікрофон, я ... пісню для всього пабу, без брехні.'::text,'заспіваю'::text,'співатиму'::text,'співаю'::text,'Бро, дай мікрофон, я заспіваю пісню для всього пабу, без брехні.'::text),
(377313,41924,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, dame el micro, ... una canción para todo el pub, sin mentir.'::text,'cantaré'::text,'estaré cantando'::text,'estoy cantando'::text,'Bro, dame el micro, cantaré una canción para todo el pub, sin mentir.'::text),
(377312,41924,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, passe-moi le micro, je ... une chanson pour tout le pub, sans mentir.'::text,'vais chanter'::text,'serai en train de chanter'::text,'chante'::text,'Frère, passe-moi le micro, je vais chanter une chanson pour tout le pub, sans mentir.'::text),
(377315,41924,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, mikrofonu ver, bütün pub için bir şarkı ..., yemin ederim.'::text,'söyleyeceğim'::text,'söylüyor olacağım'::text,'söylüyorum'::text,'Kanka, mikrofonu ver, bütün pub için bir şarkı söyleyeceğim, yemin ederim.'::text),
(377316,41924,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, add ide a mikrofont, ... egy dalt az egész kocsmának, komolyan.'::text,'elénekelek'::text,'énekelni fogok'::text,'éneklek'::text,'Tesó, add ide a mikrofont, elénekelek egy dalt az egész kocsmának, komolyan.'::text),
(377319,41925,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn du in diesem Pub ein Mikro ..., singt immer jemand, echt.'::text,'hinhältst'::text,'hinhieltest'::text,'hinhalten wirst'::text,'Bro, wenn du in diesem Pub ein Mikro hinhältst, singt immer jemand, echt.'::text),
(377323,41925,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо в цьому пабі ... мікрофон, хтось завжди співає, реально.'::text,'простягаєш'::text,'простягнув'::text,'простягнеш'::text,'Бро, якщо в цьому пабі простягаєш мікрофон, хтось завжди співає, реально.'::text),
(377322,41925,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si ... un micro en este pub, siempre canta alguien, en serio.'::text,'ofreces'::text,'ofreciste'::text,'ofrecerás'::text,'Bro, si ofreces un micro en este pub, siempre canta alguien, en serio.'::text),
(377321,41925,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si tu ... un micro dans ce pub, quelqu''un chante toujours, grave.'::text,'tends'::text,'as tendu'::text,'tendras'::text,'Frère, si tu tends un micro dans ce pub, quelqu''un chante toujours, grave.'::text),
(377324,41925,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu pubda bir mikrofon ..., hep biri şarkı söyler, cidden.'::text,'uzatırsan'::text,'uzattıysan'::text,'uzatacaksan'::text,'Kanka, bu pubda bir mikrofon uzatırsan, hep biri şarkı söyler, cidden.'::text),
(377325,41925,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha ebben a kocsmában ... egy mikrofont, mindig valaki énekel, komolyan.'::text,'odanyújtasz'::text,'odanyújtottál'::text,'oda fogsz nyújtani'::text,'Tesó, ha ebben a kocsmában odanyújtasz egy mikrofont, mindig valaki énekel, komolyan.'::text),
(377328,41926,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn heute Abend 20 weitere Leute singen, ... der Pub sein Getränkeziel.'::text,'erreicht'::text,'würde erreichen'::text,'erreichte'::text,'Wenn heute Abend 20 weitere Leute singen, erreicht der Pub sein Getränkeziel.'::text),
(377332,41926,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо сьогодні ввечері заспівають ще 20 людей, паб ... свою ціль із продажу напоїв.'::text,'досягне'::text,'досяг би'::text,'досяг'::text,'Якщо сьогодні ввечері заспівають ще 20 людей, паб досягне свою ціль із продажу напоїв.'::text),
(377331,41926,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si esta noche cantan 20 personas más, el pub ... su objetivo de bebidas.'::text,'alcanzará'::text,'alcanzaría'::text,'alcanzó'::text,'Si esta noche cantan 20 personas más, el pub alcanzará su objetivo de bebidas.'::text),
(377330,41926,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si 20 personnes de plus chantent ce soir, le pub ... son objectif de boissons.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Si 20 personnes de plus chantent ce soir, le pub atteindra son objectif de boissons.'::text),
(377333,41926,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam 20 kişi daha şarkı söylerse pub içecek hedefine ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Bu akşam 20 kişi daha şarkı söylerse pub içecek hedefine ulaşacak.'::text),
(377334,41926,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ma este még 20 ember énekel, a kocsma ... az italforgalmi célját.'::text,'eléri'::text,'elérné'::text,'elérte'::text,'Ha ma este még 20 ember énekel, a kocsma eléri az italforgalmi célját.'::text),
(377337,41927,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn dieser Pub ruhig wäre, ... er eine Bibliothek, weil Bibliotheken ruhig sind.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn dieser Pub ruhig wäre, wäre er eine Bibliothek, weil Bibliotheken ruhig sind.'::text),
(377341,41927,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби цей паб був тихим, він ... бібліотекою, бо бібліотеки тихі.'::text,'був би'::text,'буде'::text,'є'::text,'Якби цей паб був тихим, він був би бібліотекою, бо бібліотеки тихі.'::text),
(377340,41927,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si este pub fuera tranquilo, ... una biblioteca, porque las bibliotecas son tranquilas.'::text,'sería'::text,'será'::text,'es'::text,'Si este pub fuera tranquilo, sería una biblioteca, porque las bibliotecas son tranquilas.'::text),
(377339,41927,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ce pub était calme, ce ... une bibliothèque, parce que les bibliothèques sont calmes.'::text,'serait'::text,'sera'::text,'est'::text,'Si ce pub était calme, ce serait une bibliothèque, parce que les bibliothèques sont calmes.'::text),
(377342,41927,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu pub sessiz olsaydı bir kütüphane ..., çünkü kütüphaneler sessizdir.'::text,'olurdu'::text,'olacak'::text,NULL::text,'Bu pub sessiz olsaydı bir kütüphane olurdu, çünkü kütüphaneler sessizdir.'::text),
(377343,41927,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ez a kocsma csendes lenne, könyvtár ..., mert a könyvtárak csendesek.'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha ez a kocsma csendes lenne, könyvtár lenne, mert a könyvtárak csendesek.'::text),
(377346,41928,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mikrofon ... an jeden Tisch im Pub weitergereicht, wie im Filmmaterial zu sehen ist.'::text,'wird'::text,'reicht'::text,'reicht gerade'::text,'Das Mikrofon wird an jeden Tisch im Pub weitergereicht, wie im Filmmaterial zu sehen ist.'::text),
(377350,41928,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мікрофон ... до кожного столу в пабі, як видно на записі.'::text,'передається'::text,'передає'::text,'передає'::text,'Мікрофон передається до кожного столу в пабі, як видно на записі.'::text),
(377349,41928,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El micrófono ... a cada mesa del pub, como se observa en la grabación.'::text,'es pasado'::text,'pasa'::text,'está pasando'::text,'El micrófono es pasado a cada mesa del pub, como se observa en la grabación.'::text),
(377348,41928,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le micro ... à chaque table du pub, comme on l''observe sur les images.'::text,'est tendu'::text,'tend'::text,'est en train de tendre'::text,'Le micro est tendu à chaque table du pub, comme on l''observe sur les images.'::text),
(377351,41928,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Görüntülerde gözlemlendiği üzere mikrofon pubdaki her masaya ...'::text,'uzatılıyor'::text,'uzatıyor'::text,'uzatıyor'::text,'Görüntülerde gözlemlendiği üzere mikrofon pubdaki her masaya uzatılıyor.'::text),
(377352,41928,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mikrofont a kocsma minden asztalához ..., ahogy a felvételen megfigyelhető.'::text,'odaadják'::text,'odaadja'::text,'odaadja'::text,'A mikrofont a kocsma minden asztalához odaadják, ahogy a felvételen megfigyelhető.'::text),
(377364,41930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der ganze Pub jubelt, also ... die alte Frau eine sehr gute Sängerin sein.'::text,'muss'::text,'kann nicht'::text,'sollte nicht'::text,'Der ganze Pub jubelt, also muss die alte Frau eine sehr gute Sängerin sein.'::text),
(377368,41930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Весь паб радіє, тож стара пані ... бути дуже хорошою співачкою.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Весь паб радіє, тож стара пані мусить бути дуже хорошою співачкою.'::text),
(377367,41930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo el pub está vitoreando, así que la señora ... ser muy buena cantante.'::text,'debe de'::text,'no puede'::text,'no debería'::text,'Todo el pub está vitoreando, así que la señora debe de ser muy buena cantante.'::text),
(377366,41930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le pub acclame, donc la vieille dame ... être une très bonne chanteuse.'::text,'doit'::text,'ne peut pas'::text,'ne devrait pas'::text,'Tout le pub acclame, donc la vieille dame doit être une très bonne chanteuse.'::text),
(377369,41930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün pub tezahürat yapıyor, demek ki yaşlı kadın çok iyi bir şarkıcı ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Bütün pub tezahürat yapıyor, demek ki yaşlı kadın çok iyi bir şarkıcı olmalı.'::text),
(377370,41930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész kocsma ujjong, szóval az idős nő ... nagyon jó énekes.'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem kéne, hogy'::text,'Az egész kocsma ujjong, szóval az idős nő biztosan nagyon jó énekes.'::text),
(330753,36751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Applaus gestern Abend soll der lauteste der ganzen Tour ...'::text,'gewesen sein'::text,'sein'::text,'seiend'::text,'Der Applaus gestern Abend soll der lauteste der ganzen Tour gewesen sein.'::text),
(330757,36751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що вчорашні оплески ... найгучнішими за весь тур.'::text,'були'::text,'є'::text,'бувши'::text,'Кажуть, що вчорашні оплески були найгучнішими за весь тур.'::text),
(330756,36751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que el aplauso de anoche ... el más fuerte de toda la gira.'::text,'fue'::text,'es'::text,'siendo'::text,'Se dice que el aplauso de anoche fue el más fuerte de toda la gira.'::text),
(330755,36751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que les applaudissements d''hier soir ... les plus forts de toute la tournée.'::text,'ont été'::text,'sont'::text,'étant'::text,'On dit que les applaudissements d''hier soir ont été les plus forts de toute la tournée.'::text),
(330758,36751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşamki alkışın tüm turnenin en gürültülüsü ... söyleniyor.'::text,'olduğu'::text,'olduğu'::text,'olarak'::text,'Dün akşamki alkışın tüm turnenin en gürültülüsü olduğu söyleniyor.'::text),
(330759,36751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, a tegnap esti taps ... az egész turné leghangosabb tapsa.'::text,'volt'::text,NULL::text,'lévén'::text,'Azt mondják, a tegnap esti taps volt az egész turné leghangosabb tapsa.'::text),
(330762,36752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast versprochen, den Applaus die ganze Nacht am Laufen ..., und ehrlich, du hast es geschafft. Respekt.'::text,'zu halten'::text,'haltend'::text,'gehalten zu haben'::text,'Du hast versprochen, den Applaus die ganze Nacht am Laufen zu halten, und ehrlich, du hast es geschafft. Respekt.'::text),
(330766,36752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти пообіцяв ... оплески всю ніч, і чесно, тобі вдалося. Респект.'::text,'підтримувати'::text,'підтримуючи'::text,'підтримав'::text,'Ти пообіцяв підтримувати оплески всю ніч, і чесно, тобі вдалося. Респект.'::text),
(330765,36752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prometiste ... el aplauso toda la noche y, sinceramente, lo hiciste. Respeto.'::text,'mantener'::text,'manteniendo'::text,'haber mantenido'::text,'Prometiste mantener el aplauso toda la noche y, sinceramente, lo hiciste. Respeto.'::text),
(330764,36752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as promis de ... les applaudissements toute la nuit, et franchement, tu l''as fait. Respect.'::text,'faire durer'::text,'faisant durer'::text,'avoir fait durer'::text,'Tu as promis de faire durer les applaudissements toute la nuit, et franchement, tu l''as fait. Respect.'::text),
(330767,36752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alkışı bütün gece ... söz verdin ve açıkçası başardın. Saygılar.'::text,'sürdürmeye'::text,'sürdürerek'::text,'sürdürmüş olmaya'::text,'Alkışı bütün gece sürdürmeye söz verdin ve açıkçası başardın. Saygılar.'::text),
(330768,36752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megígérted, hogy egész éjjel ... a tapsot, és őszintén, sikerült. Respekt.'::text,'fenntartod'::text,'fenntartva'::text,'fenntartottad'::text,'Megígérted, hogy egész éjjel fenntartod a tapsot, és őszintén, sikerült. Respekt.'::text),
(330771,36753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach all dem Applaus ... er seinen Händen eine Pause gönnen sollen. Offensichtlich hat es ihnen gefallen.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Nach all dem Applaus hätte er seinen Händen eine Pause gönnen sollen. Offensichtlich hat es ihnen gefallen.'::text),
(330775,36753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після всіх цих оплесків ... рукам відпочити. Явно їм це сподобалося.'::text,'йому варто було дати'::text,'він, мабуть, дав'::text,'він не міг дати'::text,'Після всіх цих оплесків йому варто було дати рукам відпочити. Явно їм це сподобалося.'::text),
(330774,36753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un descanso a sus manos después de tanto aplauso. Está claro que les encantó.'::text,'Debería haber dado'::text,'Debe de haber dado'::text,'No puede haber dado'::text,'Debería haber dado un descanso a sus manos después de tanto aplauso. Está claro que les encantó.'::text),
(330773,36753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... une pause à ses mains après tous ces applaudissements. Visiblement, elles ont adoré.'::text,'aurait dû donner'::text,'a dû donner'::text,'n''a pas pu donner'::text,'Il aurait dû donner une pause à ses mains après tous ces applaudissements. Visiblement, elles ont adoré.'::text),
(330776,36753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bunca alkıştan sonra ellerini ..., belli ki bayıldılar.'::text,'dinlendirmeliydi'::text,'dinlendirmiş olmalı'::text,'dinlendirmiş olamaz'::text,'Bunca alkıştan sonra ellerini dinlendirmeliydi, belli ki bayıldılar.'::text),
(330777,36753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennyi taps után ... a kezét. Nyilván imádták.'::text,'pihentetnie kellett volna'::text,'biztos pihentette'::text,'nem pihentethette'::text,'Ennyi taps után pihentetnie kellett volna a kezét. Nyilván imádták.'::text),
(330780,36754,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... so leisen, zurückhaltenden Applaus gehört. Natürlich.'::text,'habe ich'::text,'ich habe'::text,'ich hörte'::text,'Nie habe ich so leisen, zurückhaltenden Applaus gehört. Natürlich.'::text),
(330784,36754,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... таких тихих, стриманих оплесків. Звісно.'::text,'я не чув'::text,'я не чув'::text,'я не чув'::text,'Ніколи я не чув таких тихих, стриманих оплесків. Звісно.'::text),
(330783,36754,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... un aplauso tan silencioso y contenido. Obviamente.'::text,'he oído'::text,'he oído'::text,'oí'::text,'Nunca he oído un aplauso tan silencioso y contenido. Obviamente.'::text),
(330782,36754,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... des applaudissements aussi discrets et retenus. Évidemment.'::text,'n''ai-je entendu'::text,'je n''ai entendu'::text,'je n''ai entendu'::text,'Jamais n''ai-je entendu des applaudissements aussi discrets et retenus. Évidemment.'::text),
(330785,36754,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç ... bu kadar sessiz, ölçülü bir alkış. Tabii ki.'::text,'duymadım'::text,'duymadım'::text,'duymadım'::text,'Hiç duymadım bu kadar sessiz, ölçülü bir alkış. Tabii ki.'::text),
(330786,36754,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... ilyen halk, visszafogott tapsot. Nyilván.'::text,'nem hallottam'::text,'nem hallottam'::text,'nem hallottam'::text,'Soha nem hallottam ilyen halk, visszafogott tapsot. Nyilván.'::text),
(330789,36755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er brachte die ganze Reihe dazu, noch lauteren Applaus ..., ein ruhiger Abend, offensichtlich.'::text,'zu spenden'::text,'spenden'::text,'spendete'::text,'Er brachte die ganze Reihe dazu, noch lauteren Applaus zu spenden, ein ruhiger Abend, offensichtlich.'::text),
(330793,36755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він змусив увесь ряд ... ще гучніші оплески. Тихий вечір, звісно.'::text,'влаштувати'::text,'влаштувати'::text,'влаштував'::text,'Він змусив увесь ряд влаштувати ще гучніші оплески. Тихий вечір, звісно.'::text),
(330792,36755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Consiguió que toda la fila ... un aplauso más fuerte. Una noche tranquila, obviamente.'::text,'diera'::text,'dar'::text,'dio'::text,'Consiguió que toda la fila diera un aplauso más fuerte. Una noche tranquila, obviamente.'::text),
(330791,36755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a poussé toute la rangée à ... des applaudissements encore plus forts. Une soirée calme, évidemment.'::text,'donner'::text,'donner'::text,'a donné'::text,'Il a poussé toute la rangée à donner des applaudissements encore plus forts. Une soirée calme, évidemment.'::text),
(330794,36755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün sırayı daha yüksek sesle ... ikna etti, sakin bir gece tabii ki.'::text,'alkışlamaya'::text,'alkışla'::text,'alkışladı'::text,'Bütün sırayı daha yüksek sesle alkışlamaya ikna etti, sakin bir gece tabii ki.'::text),
(330795,36755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rávette az egész sort, hogy ... még hangosabban. Nyugodt este, nyilván.'::text,'tapsoljon'::text,'tapsol'::text,'tapsolt'::text,'Rávette az egész sort, hogy tapsoljon még hangosabban. Nyugodt este, nyilván.'::text),
(330798,36756,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Künstler wünscht sich, der Applaus ... die ganze Nacht dauern.'::text,'würde'::text,'wird'::text,'dauert'::text,'Der Künstler wünscht sich, der Applaus würde die ganze Nacht dauern.'::text),
(330802,36756,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Виконавець хотів би, щоб оплески ... всю ніч.'::text,'тривали'::text,'триватимуть'::text,'тривають'::text,'Виконавець хотів би, щоб оплески тривали всю ніч.'::text),
(330801,36756,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El artista desearía que el aplauso ... toda la noche.'::text,'durara'::text,'durará'::text,'dura'::text,'El artista desearía que el aplauso durara toda la noche.'::text),
(330800,36756,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''artiste aimerait que les applaudissements ... toute la nuit.'::text,'durent'::text,'dureront'::text,'durent'::text,'L''artiste aimerait que les applaudissements durent toute la nuit.'::text),
(330803,36756,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sanatçı alkışın bütün gece ... istiyor.'::text,'sürmesini'::text,'süreceğini'::text,'sürdüğünü'::text,'Sanatçı alkışın bütün gece sürmesini istiyor.'::text),
(330804,36756,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az előadó azt szeretné, ha a taps egész éjjel ...'::text,'tartana'::text,'tart majd'::text,'tart'::text,'Az előadó azt szeretné, ha a taps egész éjjel tartana.'::text),
(330807,36757,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann, ... Sonnenbrille auf seinem Kopf sitzt, führt den Applaus in seiner Reihe an.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Mann, dessen Sonnenbrille auf seinem Kopf sitzt, führt den Applaus in seiner Reihe an.'::text),
(330811,36757,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік, ... сонцезахисні окуляри сидять на голові, веде оплески у своєму ряду.'::text,'чиї'::text,'який'::text,'котрий'::text,'Чоловік, чиї сонцезахисні окуляри сидять на голові, веде оплески у своєму ряду.'::text),
(330810,36757,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre, ... gafas de sol están sobre su cabeza, dirige el aplauso de su fila.'::text,'cuyas'::text,'que'::text,'el cual'::text,'El hombre, cuyas gafas de sol están sobre su cabeza, dirige el aplauso de su fila.'::text),
(330809,36757,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme, ... les lunettes de soleil sont posées sur sa tête, mène les applaudissements de sa rangée.'::text,'dont'::text,'qui'::text,'lequel'::text,'L''homme, dont les lunettes de soleil sont posées sur sa tête, mène les applaudissements de sa rangée.'::text),
(330812,36757,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Güneş gözlüğü başında ... adam sırasındaki alkışa öncülük ediyor.'::text,'duran'::text,NULL::text,NULL::text,'Güneş gözlüğü başında duran adam sırasındaki alkışa öncülük ediyor.'::text),
(330813,36757,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi, ... napszemüvege a fején van, vezeti a tapsot a sorában.'::text,'akinek a'::text,'aki'::text,'amely'::text,'A férfi, akinek a napszemüvege a fején van, vezeti a tapsot a sorában.'::text),
(330816,36758,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., den er dem Künstler spendete, war der lauteste im Saal.'::text,'Der Applaus'::text,'Applaus'::text,'Ein Applaus'::text,'Der Applaus, den er dem Künstler spendete, war der lauteste im Saal.'::text),
(330820,36758,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., які він подарував виконавцеві, були найгучнішими в залі.'::text,'Оплески'::text,'Оплески'::text,'Оплески'::text,'Оплески, які він подарував виконавцеві, були найгучнішими в залі.'::text),
(330819,36758,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... que le dio al artista fue el más fuerte de la sala.'::text,'El aplauso'::text,'Aplauso'::text,'Un aplauso'::text,'El aplauso que le dio al artista fue el más fuerte de la sala.'::text),
(330818,36758,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... qu''il a offerts à l''artiste étaient les plus forts de la salle.'::text,'Les applaudissements'::text,'Applaudissements'::text,'Des applaudissements'::text,'Les applaudissements qu''il a offerts à l''artiste étaient les plus forts de la salle.'::text),
(330821,36758,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sanatçıya tuttuğu ... salondaki en gürültülüydü.'::text,'alkış'::text,'alkış'::text,'bir alkış'::text,'Sanatçıya tuttuğu alkış salondaki en gürültülüydü.'::text),
(330822,36758,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amit az előadónak adott, a leghangosabb volt a teremben.'::text,'A taps'::text,'Taps'::text,'Egy taps'::text,'A taps, amit az előadónak adott, a leghangosabb volt a teremben.'::text),
(330825,36759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hob die Hände hoch, ... sein Applaus die Bühne erreichte.'::text,'damit'::text,'im Falle'::text,'trotz'::text,'Er hob die Hände hoch, damit sein Applaus die Bühne erreichte.'::text),
(330829,36759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він високо підняв руки, ... його оплески долетіли до сцени.'::text,'щоб'::text,'у разі'::text,'попри'::text,'Він високо підняв руки, щоб його оплески долетіли до сцени.'::text),
(330828,36759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Levantó las manos bien alto ... su aplauso llegara al escenario.'::text,'para que'::text,'en caso de'::text,'a pesar de'::text,'Levantó las manos bien alto para que su aplauso llegara al escenario.'::text),
(330827,36759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a levé les mains bien haut ... ses applaudissements atteignent la scène.'::text,'pour que'::text,'en cas de'::text,'malgré'::text,'Il a levé les mains bien haut pour que ses applaudissements atteignent la scène.'::text),
(330830,36759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alkışı sahneye ... ellerini yukarı kaldırdı.'::text,'ulaşsın diye'::text,'ulaşması durumunda'::text,'ulaşmasına rağmen'::text,'Alkışı sahneye ulaşsın diye ellerini yukarı kaldırdı.'::text),
(330831,36759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Magasra emelte a kezét, ... a tapsa elérje a színpadot.'::text,'hogy'::text,'esetén'::text,'ellenére'::text,'Magasra emelte a kezét, hogy a tapsa elérje a színpadot.'::text),
(330843,36761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... du den lautesten Applaus im Raum, ehrlich.'::text,'spendest'::text,'spendest'::text,'hast gespendet'::text,'Gerade spendest du den lautesten Applaus im Raum, ehrlich.'::text),
(330847,36761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз ти ... найгучніші оплески в кімнаті, чесно.'::text,'влаштовуєш'::text,'влаштовуєш'::text,'влаштував'::text,'Прямо зараз ти влаштовуєш найгучніші оплески в кімнаті, чесно.'::text),
(330846,36761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... el aplauso más fuerte de la sala, sinceramente.'::text,'estás dando'::text,'das'::text,'has dado'::text,'Ahora mismo estás dando el aplauso más fuerte de la sala, sinceramente.'::text),
(330845,36761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Là, maintenant, tu ... les applaudissements les plus forts de la salle, franchement.'::text,'fais'::text,'fais'::text,'as fait'::text,'Là, maintenant, tu fais les applaudissements les plus forts de la salle, franchement.'::text),
(330848,36761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an odadaki en gürültülü alkışı sen ..., açıkçası.'::text,'tutuyorsun'::text,'tutarsın'::text,'tuttun'::text,'Şu an odadaki en gürültülü alkışı sen tutuyorsun, açıkçası.'::text),
(330849,36761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most épp te ... a leghangosabban a teremben, őszintén.'::text,'tapsolsz'::text,'tapsolsz'::text,'tapsoltál'::text,'Most épp te tapsolsz a leghangosabban a teremben, őszintén.'::text),
(335100,37234,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, die Kundin hat mir erzählt, die Visagistin ... gerade die Creme in ihre Haut, als sie einschlief.'::text,'verblendete'::text,'verblendete'::text,'hat verblendet'::text,'Girl, die Kundin hat mir erzählt, die Visagistin verblendete gerade die Creme in ihre Haut, als sie einschlief.'::text),
(335104,37234,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, клієнтка сказала мені, що візажистка ... крем у шкіру, коли вона заснула.'::text,'розтушовувала'::text,'розтушувала'::text,'розтушувала'::text,'Подруго, клієнтка сказала мені, що візажистка розтушовувала крем у шкіру, коли вона заснула.'::text),
(335103,37234,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, la clienta me dijo que la maquilladora ... la crema en su piel cuando se quedó dormida.'::text,'estaba difuminando'::text,'difuminó'::text,'ha difuminado'::text,'Amiga, la clienta me dijo que la maquilladora estaba difuminando la crema en su piel cuando se quedó dormida.'::text),
(335102,37234,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, la cliente m''a dit que la maquilleuse ... la crème dans sa peau quand elle s''est endormie.'::text,'estompait'::text,'a estompé'::text,'a estompé'::text,'Meuf, la cliente m''a dit que la maquilleuse estompait la crème dans sa peau quand elle s''est endormie.'::text),
(335105,37234,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, müşteri bana, uyuyakaldığında makyözün kremi cildine ... anlattı.'::text,'dağıtmakta olduğunu'::text,'dağıttığını'::text,'dağıttığını'::text,'Kızım, müşteri bana, uyuyakaldığında makyözün kremi cildine dağıtmakta olduğunu anlattı.'::text),
(335106,37234,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a vendég azt mondta, hogy a sminkes épp ... a krémet a bőrén, amikor elaludt.'::text,'dolgozta el'::text,'eldolgozta'::text,'eldolgozta'::text,'Csajszi, a vendég azt mondta, hogy a sminkes épp dolgozta el a krémet a bőrén, amikor elaludt.'::text),
(335109,37235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, angeblich ... die Visagistin schon zwanzig Minuten lang Creme auf ihrem Gesicht.'::text,'verblendet'::text,'verblendet'::text,'verblendet'::text,'Hör zu, angeblich verblendet die Visagistin schon zwanzig Minuten lang Creme auf ihrem Gesicht.'::text),
(335113,37235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, візажистка ... крем на її обличчі вже двадцять хвилин.'::text,'розтушовує'::text,'розтушовує'::text,'розтушовує'::text,'Слухай, кажуть, візажистка розтушовує крем на її обличчі вже двадцять хвилин.'::text),
(335112,37235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, parece que la maquilladora ... crema en su cara veinte minutos.'::text,'lleva difuminando'::text,'está difuminando'::text,'difumina'::text,'Oye, parece que la maquilladora lleva difuminando crema en su cara veinte minutos.'::text),
(335111,37235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment la maquilleuse ... de la crème sur son visage depuis vingt minutes.'::text,'estompe'::text,'estompe'::text,'estompe'::text,'Écoute, apparemment la maquilleuse estompe de la crème sur son visage depuis vingt minutes.'::text),
(335114,37235,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, söylenene göre makyöz yirmi dakikadır yüzüne krem ...'::text,'dağıtıyormuş'::text,'dağıtıyormuş'::text,'dağıtırmış'::text,'Dinle, söylenene göre makyöz yirmi dakikadır yüzüne krem dağıtıyormuş.'::text),
(335115,37235,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a sminkes már húsz perce ... a krémet az arcán.'::text,'dolgozza el'::text,'dolgozza el'::text,'dolgozza el'::text,'Figyelj, állítólag a sminkes már húsz perce dolgozza el a krémet az arcán.'::text),
(335118,37236,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, sie ... gerade den letzten Streifen, als die Visagistin zum Puder wechselte.'::text,'verblendete'::text,'verblendete'::text,'hat verblendet'::text,'Rate mal, ich hab gehört, sie verblendete gerade den letzten Streifen, als die Visagistin zum Puder wechselte.'::text),
(335122,37236,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що вона ... останню смужку, коли візажистка перейшла на пудру.'::text,'розтушовувала'::text,'розтушувала'::text,'розтушувала'::text,'Уяви, я чула, що вона розтушовувала останню смужку, коли візажистка перейшла на пудру.'::text),
(335121,37236,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, me dijeron que ... la última raya cuando la maquilladora pasó a los polvos.'::text,'estaba difuminando'::text,'difuminó'::text,'ha difuminado'::text,'Adivina, me dijeron que estaba difuminando la última raya cuando la maquilladora pasó a los polvos.'::text),
(335120,37236,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, il paraît qu''elle ... la dernière bande quand la maquilleuse est passée à la poudre.'::text,'estompait'::text,'a estompé'::text,'a estompé'::text,'Devine quoi, il paraît qu''elle estompait la dernière bande quand la maquilleuse est passée à la poudre.'::text),
(335123,37236,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duyduğuma göre makyöz pudraya geçtiğinde o son çizgiyi ...'::text,'dağıtıyormuş'::text,'dağıtmış'::text,'dağıtmış'::text,'Bil bakalım, duyduğuma göre makyöz pudraya geçtiğinde o son çizgiyi dağıtıyormuş.'::text),
(335124,37236,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy épp ... az utolsó csíkot, amikor a sminkes átváltott a púderre.'::text,'dolgozta el'::text,'eldolgozta'::text,'eldolgozta'::text,'Képzeld, azt hallottam, hogy épp dolgozta el az utolsó csíkot, amikor a sminkes átváltott a púderre.'::text),
(335127,37237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Low-key beeindruckt: Du ... die Streifen so gut verblendet, dass sie verschwunden sind.'::text,'hast'::text,'hast'::text,'verblendest'::text,'Low-key beeindruckt: Du hast die Streifen so gut verblendet, dass sie verschwunden sind.'::text),
(335131,37237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лоукі вражена: ти ... ці смужки так добре, що вони зникли.'::text,'розтушувала'::text,'розтушовувала'::text,'розтушовуєш'::text,'Лоукі вражена: ти розтушувала ці смужки так добре, що вони зникли.'::text),
(335130,37237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, me flipa: ... esas rayas tan bien que han desaparecido.'::text,'has difuminado'::text,'has estado difuminando'::text,'estás difuminando'::text,'La verdad, me flipa: has difuminado esas rayas tan bien que han desaparecido.'::text),
(335129,37237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Low-key impressionné : tu ... ces bandes si bien qu''elles ont disparu.'::text,'as estompé'::text,'as estompé'::text,'estompes'::text,'Low-key impressionné : tu as estompé ces bandes si bien qu''elles ont disparu.'::text),
(335132,37237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası etkilendim: o çizgileri öyle güzel ... ki kayboldular.'::text,'dağıttın'::text,'dağıtıyordun'::text,'dağıtıyorsun'::text,'Açıkçası etkilendim: o çizgileri öyle güzel dağıttın ki kayboldular.'::text),
(335133,37237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lowkey le vagyok nyűgözve: olyan jól ... azokat a csíkokat, hogy eltűntek.'::text,'eldolgoztad'::text,'dolgoztad el'::text,'dolgozod el'::text,'Lowkey le vagyok nyűgözve: olyan jól eldolgoztad azokat a csíkokat, hogy eltűntek.'::text),
(335136,37238,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Visagistin zum Pinsel griff, ... der Schwamm schon alle Cremestreifen verblendet.'::text,'hatte'::text,'hat'::text,'verblendet'::text,'Als die Visagistin zum Pinsel griff, hatte der Schwamm schon alle Cremestreifen verblendet.'::text),
(335140,37238,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки візажистка взяла пензлик, спонж уже ... всі смужки крему.'::text,'розтушував'::text,'розтушував'::text,'розтушовує'::text,'Поки візажистка взяла пензлик, спонж уже розтушував всі смужки крему.'::text),
(335139,37238,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando la maquilladora cogió la brocha, la esponja ya ... todas las rayas de crema.'::text,'había difuminado'::text,'ha difuminado'::text,'difumina'::text,'Cuando la maquilladora cogió la brocha, la esponja ya había difuminado todas las rayas de crema.'::text),
(335138,37238,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la maquilleuse a pris le pinceau, l''éponge ... déjà estompé toutes les bandes de crème.'::text,'avait'::text,'a'::text,'estompe'::text,'Quand la maquilleuse a pris le pinceau, l''éponge avait déjà estompé toutes les bandes de crème.'::text),
(335141,37238,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz fırçayı aldığında sünger bütün krem çizgilerini çoktan ...'::text,'dağıtmıştı'::text,'dağıttı'::text,'dağıtıyor'::text,'Makyöz fırçayı aldığında sünger bütün krem çizgilerini çoktan dağıtmıştı.'::text),
(335142,37238,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a sminkes felvette az ecsetet, a szivacs már ... az összes krémcsíkot.'::text,'eldolgozta'::text,'eldolgozta'::text,'eldolgozza'::text,'Mire a sminkes felvette az ecsetet, a szivacs már eldolgozta az összes krémcsíkot.'::text),
(335145,37239,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Visagistin die Creme gut verblendet, ... die Streifen in der Haut.'::text,'verschwinden'::text,'würden verschwinden'::text,'verschwanden'::text,'Wenn die Visagistin die Creme gut verblendet, verschwinden die Streifen in der Haut.'::text),
(335149,37239,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо візажистка добре розтушує крем, смужки ... в шкірі.'::text,'зникнуть'::text,'зникли б'::text,'зникли'::text,'Якщо візажистка добре розтушує крем, смужки зникнуть в шкірі.'::text),
(335148,37239,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la maquilladora difumina bien la crema, las rayas ... en la piel.'::text,'desaparecerán'::text,'desaparecerían'::text,'desaparecieron'::text,'Si la maquilladora difumina bien la crema, las rayas desaparecerán en la piel.'::text),
(335147,37239,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la maquilleuse estompe bien la crème, les bandes ... dans la peau.'::text,'disparaîtront'::text,'disparaîtraient'::text,'ont disparu'::text,'Si la maquilleuse estompe bien la crème, les bandes disparaîtront dans la peau.'::text),
(335150,37239,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz kremi iyi dağıtırsa çizgiler ciltte ...'::text,'kaybolacak'::text,'kaybolurdu'::text,'kayboldu'::text,'Makyöz kremi iyi dağıtırsa çizgiler ciltte kaybolacak.'::text),
(335151,37239,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sminkes jól eldolgozza a krémet, a csíkok ... a bőrben.'::text,'eltűnnek'::text,'eltűnnének'::text,'eltűntek'::text,'Ha a sminkes jól eldolgozza a krémet, a csíkok eltűnnek a bőrben.'::text),
(335154,37240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Visagistin die Creme nicht verblendete, ... die Streifen auf dem Gesicht der Frau.'::text,'blieben'::text,'werden bleiben'::text,'bleiben'::text,'Wenn die Visagistin die Creme nicht verblendete, blieben die Streifen auf dem Gesicht der Frau.'::text),
(335158,37240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби візажистка не розтушувала крем, смужки ... на обличчі жінки.'::text,'залишилися б'::text,'залишаться'::text,'залишаються'::text,'Якби візажистка не розтушувала крем, смужки залишилися б на обличчі жінки.'::text),
(335157,37240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la maquilladora no difuminara la crema, las rayas ... en la cara de la mujer.'::text,'se quedarían'::text,'se quedarán'::text,'se quedan'::text,'Si la maquilladora no difuminara la crema, las rayas se quedarían en la cara de la mujer.'::text),
(335156,37240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la maquilleuse n''estompait pas la crème, les bandes ... sur le visage de la femme.'::text,'resteraient'::text,'resteront'::text,'restent'::text,'Si la maquilleuse n''estompait pas la crème, les bandes resteraient sur le visage de la femme.'::text),
(335159,37240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz kremi dağıtmasa çizgiler kadının yüzünde ...'::text,'kalırdı'::text,'kalacak'::text,'kalıyor'::text,'Makyöz kremi dağıtmasa çizgiler kadının yüzünde kalırdı.'::text),
(335160,37240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sminkes nem dolgozná el a krémet, a csíkok ... a nő arcán.'::text,'maradnának'::text,'maradnak majd'::text,'maradnak'::text,'Ha a sminkes nem dolgozná el a krémet, a csíkok maradnának a nő arcán.'::text),
(335172,37242,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Visagistin ... jeden einzelnen Streifen, sonst wäre dieses Gesicht eine totale Katastrophe!'::text,'verblendete'::text,'wurde verblendet'::text,'verblendend'::text,'Die Visagistin verblendete jeden einzelnen Streifen, sonst wäre dieses Gesicht eine totale Katastrophe!'::text),
(335176,37242,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візажистка ... кожну смужку, інакше це обличчя було б повною катастрофою!'::text,'розтушувала'::text,'була розтушована'::text,'розтушовуючи'::text,'Візажистка розтушувала кожну смужку, інакше це обличчя було б повною катастрофою!'::text),
(335175,37242,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La maquilladora ... cada una de las rayas, o esta cara sería un desastre total!'::text,'difuminó'::text,'fue difuminada'::text,'difuminando'::text,'¡La maquilladora difuminó cada una de las rayas, o esta cara sería un desastre total!'::text),
(335174,37242,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilleuse ... chaque bande, sinon ce visage serait une catastrophe totale !'::text,'a estompé'::text,'a été estompée'::text,'estompant'::text,'La maquilleuse a estompé chaque bande, sinon ce visage serait une catastrophe totale !'::text),
(335177,37242,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makyöz her bir çizgiyi ..., yoksa bu yüz tam bir felaket olurdu!'::text,'dağıttı'::text,'dağıtıldı'::text,'dağıtarak'::text,'Makyöz her bir çizgiyi dağıttı, yoksa bu yüz tam bir felaket olurdu!'::text),
(335178,37242,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sminkes ... minden egyes csíkot, különben ez az arc totális katasztrófa lenne!'::text,'eldolgozott'::text,'el lett dolgozva'::text,'eldolgozva'::text,'A sminkes eldolgozott minden egyes csíkot, különben ez az arc totális katasztrófa lenne!'::text),
(335181,37243,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Visagistin ... die Creme eine Ewigkeit lang verblendet, bevor die Streifen endlich für immer verschwanden!'::text,'hatte'::text,'hat'::text,'verblendet'::text,'Die Visagistin hatte die Creme eine Ewigkeit lang verblendet, bevor die Streifen endlich für immer verschwanden!'::text),
(335185,37243,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Візажистка ... крем цілу вічність, перш ніж смужки нарешті зникли назавжди!'::text,'розтушовувала'::text,'розтушовує'::text,'розтушовує'::text,'Візажистка розтушовувала крем цілу вічність, перш ніж смужки нарешті зникли назавжди!'::text),
(335184,37243,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La maquilladora ... la crema una eternidad antes de que las rayas por fin desaparecieran para siempre!'::text,'llevaba difuminando'::text,'lleva difuminando'::text,'difumina'::text,'¡La maquilladora llevaba difuminando la crema una eternidad antes de que las rayas por fin desaparecieran para siempre!'::text),
(335183,37243,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquilleuse ... la crème pendant une éternité avant que les bandes disparaissent enfin pour toujours !'::text,'avait estompé'::text,'a estompé'::text,'estompe'::text,'La maquilleuse avait estompé la crème pendant une éternité avant que les bandes disparaissent enfin pour toujours !'::text),
(335186,37243,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çizgiler sonunda sonsuza dek kaybolmadan önce makyöz kremi asırlarca ...!'::text,'dağıtıyordu'::text,'dağıtıyor'::text,'dağıtır'::text,'Çizgiler sonunda sonsuza dek kaybolmadan önce makyöz kremi asırlarca dağıtıyordu!'::text),
(335187,37243,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sminkes egy örökkévalóságig ... a krémet, mire a csíkok végre örökre eltűntek!'::text,'dolgozta el'::text,'dolgozza el'::text,'dolgozza el'::text,'A sminkes egy örökkévalóságig dolgozta el a krémet, mire a csíkok végre örökre eltűntek!'::text),
(369579,41065,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, das Modell, ... du mit den winzigen Türmen gebaut hast, ist der Wahnsinn.'::text,'das'::text,'der'::text,'wo'::text,'Ehrlich, das Modell, das du mit den winzigen Türmen gebaut hast, ist der Wahnsinn.'::text),
(369583,41065,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, макет, ... ти збудувала з крихітними вежами, неймовірний.'::text,'який'::text,'хто'::text,'де'::text,'Чесно, макет, який ти збудувала з крихітними вежами, неймовірний.'::text),
(369582,41065,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, la maqueta ... hiciste con torres diminutas es increíble.'::text,'que'::text,'quien'::text,'donde'::text,'Sinceramente, la maqueta que hiciste con torres diminutas es increíble.'::text),
(369581,41065,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, la maquette ... tu as construite avec des tours minuscules est incroyable.'::text,'que'::text,'qui'::text,'où'::text,'Franchement, la maquette que tu as construite avec des tours minuscules est incroyable.'::text),
(369584,41065,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, minik kulelerle ... maket harika.'::text,'yaptığın'::text,NULL::text,NULL::text,'Açıkçası, minik kulelerle yaptığın maket harika.'::text),
(369585,41065,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a makett, ... apró tornyokkal építettél, csodás.'::text,'amit'::text,'aki'::text,'ahol'::text,'Őszintén, a makett, amit apró tornyokkal építettél, csodás.'::text),
(369588,41066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Kollege sagte, sie ... das Modell in der Nacht davor fertiggestellt. Eindeutig eine entspannte Woche.'::text,'habe'::text,'hat'::text,'stellt'::text,'Ihr Kollege sagte, sie habe das Modell in der Nacht davor fertiggestellt. Eindeutig eine entspannte Woche.'::text),
(369592,41066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її колега сказав, що вона ... макет напередодні ввечері. Явно розслаблений тиждень.'::text,'доробила'::text,'доробила'::text,'доробляє'::text,'Її колега сказав, що вона доробила макет напередодні ввечері. Явно розслаблений тиждень.'::text),
(369591,41066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su compañero dijo que ... la maqueta la noche anterior. Una semana relajada, está claro.'::text,'había terminado'::text,'ha terminado'::text,'termina'::text,'Su compañero dijo que había terminado la maqueta la noche anterior. Una semana relajada, está claro.'::text),
(369590,41066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son collègue a dit qu''elle ... la maquette la veille au soir. Clairement une semaine reposante.'::text,'avait terminé'::text,'a terminé'::text,'termine'::text,'Son collègue a dit qu''elle avait terminé la maquette la veille au soir. Clairement une semaine reposante.'::text),
(369593,41066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş arkadaşı, maketi bir önceki gece ... söyledi. Belli ki rahat bir hafta.'::text,'bitirdiğini'::text,'bitirdiğini'::text,'bitirdiğini'::text,'İş arkadaşı, maketi bir önceki gece bitirdiğini söyledi. Belli ki rahat bir hafta.'::text),
(369594,41066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kollégája azt mondta, hogy előző éjjel ... a makettet. Egyértelműen pihentető hét.'::text,'fejezte be'::text,'fejezte be'::text,'fejezi be'::text,'A kollégája azt mondta, hogy előző éjjel fejezte be a makettet. Egyértelműen pihentető hét.'::text),
(369606,41068,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hörte auf, am Plan ..., und verschob einen winzigen Turm am Modell.'::text,'zu zeichnen'::text,'um zu zeichnen'::text,'zeichnen'::text,'Sie hörte auf, am Plan zu zeichnen, und verschob einen winzigen Turm am Modell.'::text),
(369610,41068,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона перестала ... план і пересунула одну крихітну вежу на макеті.'::text,'креслити'::text,'щоб креслити'::text,'креслити'::text,'Вона перестала креслити план і пересунула одну крихітну вежу на макеті.'::text),
(369609,41068,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dejó de ... el plano y movió una torre diminuta de la maqueta.'::text,'dibujar'::text,'para dibujar'::text,'dibujar'::text,'Dejó de dibujar el plano y movió una torre diminuta de la maqueta.'::text),
(369608,41068,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a arrêté de ... le plan et a déplacé une petite tour sur la maquette.'::text,'dessiner'::text,'pour dessiner'::text,'dessiner'::text,'Elle a arrêté de dessiner le plan et a déplacé une petite tour sur la maquette.'::text),
(369611,41068,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planı ... bıraktı ve maketteki minik bir kuleyi oynattı.'::text,'çizmeyi'::text,'çizmek için'::text,'çiz'::text,'Planı çizmeyi bıraktı ve maketteki minik bir kuleyi oynattı.'::text),
(369612,41068,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abbahagyta a terv ..., és arrébb tett egy apró tornyot a maketten.'::text,'rajzolását'::text,'hogy rajzoljon'::text,'rajzol'::text,'Abbahagyta a terv rajzolását, és arrébb tett egy apró tornyot a maketten.'::text),
(369615,41069,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Modell der Stadt ist sehr detailliert, ...?'::text,'nicht wahr'::text,'nicht wahr'::text,'nicht wahr'::text,'Das Modell der Stadt ist sehr detailliert, nicht wahr?'::text),
(369619,41069,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Макет міста дуже детальний, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Макет міста дуже детальний, правда?'::text),
(369618,41069,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maqueta de la ciudad es muy detallada, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La maqueta de la ciudad es muy detallada, ¿verdad?'::text),
(369617,41069,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maquette de la ville est très détaillée, ... ?'::text,'non'::text,'non'::text,'non'::text,'La maquette de la ville est très détaillée, non ?'::text),
(369620,41069,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehir maketi çok detaylı, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Şehir maketi çok detaylı, değil mi?'::text),
(369621,41069,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A város makettje nagyon részletes, ...?'::text,'nem igaz'::text,'nem igaz'::text,'nem igaz'::text,'A város makettje nagyon részletes, nem igaz?'::text),
(369624,41070,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totale Obsession! Sie liebt das Modell über alles, und ...'::text,'ihre Kollegen auch.'::text,'ihre Kollegen auch.'::text,'ihre Kollegen auch nicht.'::text,'Totale Obsession! Sie liebt das Modell über alles, und ihre Kollegen auch.'::text),
(369628,41070,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Повна одержимість! Вона просто обожнює цей макет, і ...'::text,'її колеги теж.'::text,'її колеги теж.'::text,'її колеги теж ні.'::text,'Повна одержимість! Вона просто обожнює цей макет, і її колеги теж.'::text),
(369627,41070,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Obsesión total! Le encanta la maqueta, y ...'::text,'a sus compañeros también.'::text,'a sus compañeros también.'::text,'a sus compañeros tampoco.'::text,'¡Obsesión total! Le encanta la maqueta, y a sus compañeros también.'::text),
(369626,41070,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obsession totale ! Elle adore la maquette, et ...'::text,'ses collègues aussi.'::text,'ses collègues aussi.'::text,'ses collègues non plus.'::text,'Obsession totale ! Elle adore la maquette, et ses collègues aussi.'::text),
(369629,41070,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir takıntı! Maketi resmen seviyor, ...'::text,'iş arkadaşları da.'::text,'iş arkadaşları da.'::text,'iş arkadaşları da sevmiyor.'::text,'Tam bir takıntı! Maketi resmen seviyor, iş arkadaşları da.'::text),
(369630,41070,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Totális megszállottság! Egyszerűen imádja a makettet, és ...'::text,'a kollégái is.'::text,'a kollégái is.'::text,'a kollégái sem.'::text,'Totális megszállottság! Egyszerűen imádja a makettet, és a kollégái is.'::text),
(369642,41072,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pass auf: Ihr Kollege hat mir erzählt, dass sie bis Montag das ganze Modell ...'::text,'fertig haben wird'::text,'fertigstellen wird'::text,'am Fertigstellen sein wird'::text,'Pass auf: Ihr Kollege hat mir erzählt, dass sie bis Montag das ganze Modell fertig haben wird.'::text),
(369646,41072,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай: її колега сказав мені, що до понеділка вона ... весь макет.'::text,'доробить'::text,'доробить'::text,'дороблятиме'::text,'Слухай: її колега сказав мені, що до понеділка вона доробить весь макет.'::text),
(369645,41072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atención: su compañero me dijo que para el lunes ... toda la maqueta.'::text,'habrá terminado'::text,'terminará'::text,'estará terminando'::text,'Atención: su compañero me dijo que para el lunes habrá terminado toda la maqueta.'::text),
(369644,41072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute ça : son collègue m''a dit que d''ici lundi, elle ... toute la maquette.'::text,'aura terminé'::text,'terminera'::text,'sera en train de terminer'::text,'Écoute ça : son collègue m''a dit que d''ici lundi, elle aura terminé toute la maquette.'::text),
(369647,41072,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şuna bak: iş arkadaşı bana pazartesiye kadar bütün maketi ... söyledi.'::text,'bitirmiş olacağını'::text,'bitireceğini'::text,'bitiriyor olacağını'::text,'Şuna bak: iş arkadaşı bana pazartesiye kadar bütün maketi bitirmiş olacağını söyledi.'::text),
(369648,41072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj: a kollégája azt mondta, hogy hétfőre ... az egész makettet.'::text,'befejezi'::text,'be fogja fejezni'::text,'épp befejezi'::text,'Figyelj: a kollégája azt mondta, hogy hétfőre befejezi az egész makettet.'::text),
(369651,41073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, dass sie im Juni schon ein ganzes Jahr an diesem Modell ...'::text,'gearbeitet haben wird'::text,'arbeiten wird'::text,'arbeiten wird'::text,'Hör zu, ich hab gehört, dass sie im Juni schon ein ganzes Jahr an diesem Modell gearbeitet haben wird.'::text),
(369655,41073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що в червні вона вже цілий рік ... над цим макетом.'::text,'працюватиме'::text,'працюватиме'::text,'працюватиме'::text,'Слухай, я чула, що в червні вона вже цілий рік працюватиме над цим макетом.'::text),
(369654,41073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijeron que para junio ... en esta maqueta un año entero.'::text,'habrá estado trabajando'::text,'estará trabajando'::text,'trabajará'::text,'Oye, me dijeron que para junio habrá estado trabajando en esta maqueta un año entero.'::text),
(369653,41073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il paraît que d''ici juin, elle ... sur cette maquette pendant une année entière.'::text,'aura travaillé'::text,'travaillera'::text,'travaillera'::text,'Écoute, il paraît que d''ici juin, elle aura travaillé sur cette maquette pendant une année entière.'::text),
(369656,41073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre haziranda bu maket üzerinde tam bir yıldır ...'::text,'çalışıyor olacakmış'::text,'çalışıyor olacakmış'::text,'çalışacakmış'::text,'Dinle, duyduğuma göre haziranda bu maket üzerinde tam bir yıldır çalışıyor olacakmış.'::text),
(369657,41073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy júniusban már egy egész éve ... ezen a maketten.'::text,'fog dolgozni'::text,'fog dolgozni'::text,'fog dolgozni'::text,'Figyelj, azt hallottam, hogy júniusban már egy egész éve fog dolgozni ezen a maketten.'::text),
(369660,41074,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Modell nicht gebaut hätte, ... das Team das Problem mit dem Turm nicht bemerkt.'::text,'hätte'::text,'wird'::text,'bemerkte'::text,'Wenn sie das Modell nicht gebaut hätte, hätte das Team das Problem mit dem Turm nicht bemerkt.'::text),
(369664,41074,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не збудувала макет, команда ... проблему з вежею.'::text,'не помітила б'::text,'не помітить'::text,'не помітила'::text,'Якби вона не збудувала макет, команда не помітила б проблему з вежею.'::text),
(369663,41074,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera construido la maqueta, el equipo ... el problema de la torre.'::text,'no habría notado'::text,'no notará'::text,'no notó'::text,'Si no hubiera construido la maqueta, el equipo no habría notado el problema de la torre.'::text),
(369662,41074,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas construit la maquette, l''équipe ... le problème de la tour.'::text,'n''aurait pas remarqué'::text,'ne remarquera pas'::text,'n''a pas remarqué'::text,'Si elle n''avait pas construit la maquette, l''équipe n''aurait pas remarqué le problème de la tour.'::text),
(369665,41074,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maketi yapmasaydı ekip kuledeki sorunu ...'::text,'fark etmezdi'::text,'fark etmeyecek'::text,'fark etmedi'::text,'Maketi yapmasaydı ekip kuledeki sorunu fark etmezdi.'::text),
(369666,41074,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem építette volna meg a makettet, a csapat ... a toronnyal kapcsolatos problémát.'::text,'nem vette volna észre'::text,'nem fogja észrevenni'::text,'nem vette észre'::text,'Ha nem építette volna meg a makettet, a csapat nem vette volna észre a toronnyal kapcsolatos problémát.'::text),
(369669,41075,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du dieses Modell nicht gebaut hättest, ... diese Türme jetzt nicht so beeindruckend aus.'::text,'sähen'::text,'hätten ausgesehen'::text,'werden aussehen'::text,'Ehrlich, wenn du dieses Modell nicht gebaut hättest, sähen diese Türme jetzt nicht so beeindruckend aus.'::text),
(369673,41075,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти не збудувала той макет, ці вежі зараз не ... так вражаюче.'::text,'виглядали б'::text,'виглядали б'::text,'виглядатимуть'::text,'Чесно, якби ти не збудувала той макет, ці вежі зараз не виглядали б так вражаюче.'::text),
(369672,41075,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, si no hubieras construido esa maqueta, estas torres no ... tan impresionantes ahora.'::text,'se verían'::text,'se habrían visto'::text,'se verán'::text,'Sinceramente, si no hubieras construido esa maqueta, estas torres no se verían tan impresionantes ahora.'::text),
(369671,41075,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu n''avais pas construit cette maquette, ces tours ... aussi impressionnantes maintenant.'::text,'n''auraient pas l''air'::text,'n''auraient pas eu l''air'::text,'n''auront pas l''air'::text,'Franchement, si tu n''avais pas construit cette maquette, ces tours n''auraient pas l''air aussi impressionnantes maintenant.'::text),
(369674,41075,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o maketi yapmasaydın bu kuleler şu an bu kadar etkileyici ...'::text,'görünmezdi'::text,'görünmemiş olurdu'::text,'görünmeyecek'::text,'Açıkçası, o maketi yapmasaydın bu kuleler şu an bu kadar etkileyici görünmezdi.'::text),
(369675,41075,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nem építetted volna meg azt a makettet, ezek a tornyok most nem ... ilyen lenyűgözőnek.'::text,'tűnnének'::text,'tűntek volna'::text,'fognak tűnni'::text,'Őszintén, ha nem építetted volna meg azt a makettet, ezek a tornyok most nem tűnnének ilyen lenyűgözőnek.'::text),
(400368,44486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Sonnenuntergang wird er den riesigen Gletscher von jedem Aussichtspunkt aus ...'::text,'gesehen haben'::text,'sehen'::text,'sehen'::text,'Bis zum Sonnenuntergang wird er den riesigen Gletscher von jedem Aussichtspunkt aus gesehen haben.'::text),
(400372,44486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця він ... величезний льодовик з кожного оглядового майданчика.'::text,'побачить'::text,'побачить'::text,'бачитиме'::text,'До заходу сонця він побачить величезний льодовик з кожного оглядового майданчика.'::text),
(400371,44486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el atardecer, ... el enorme glaciar desde todos los miradores.'::text,'habrá visto'::text,'verá'::text,'estará viendo'::text,'Para el atardecer, habrá visto el enorme glaciar desde todos los miradores.'::text),
(400370,44486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, il ... l''immense glacier depuis chaque point de vue.'::text,'aura vu'::text,'verra'::text,'sera en train de voir'::text,'D''ici le coucher du soleil, il aura vu l''immense glacier depuis chaque point de vue.'::text),
(400373,44486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar devasa buzulu her seyir noktasından ...'::text,'görmüş olacak'::text,'görecek'::text,'görüyor olacak'::text,'Gün batımına kadar devasa buzulu her seyir noktasından görmüş olacak.'::text),
(400374,44486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naplementére ... a hatalmas gleccsert minden kilátópontról.'::text,'megnézi'::text,'megnézi'::text,'nézni fogja'::text,'Naplementére megnézi a hatalmas gleccsert minden kilátópontról.'::text),
(400377,44487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... er schon drei Stunden lang auf den riesigen Gletscher gestarrt haben.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Mittag wird er schon drei Stunden lang auf den riesigen Gletscher gestarrt haben.'::text),
(400381,44487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня він уже три години ... на величезний льодовик.'::text,'дивитиметься'::text,'дивитиметься'::text,'дивитиметься'::text,'До полудня він уже три години дивитиметься на величезний льодовик.'::text),
(400380,44487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, ... tres horas mirando fijamente el enorme glaciar.'::text,'llevará'::text,'estará'::text,'habrá estado'::text,'Para el mediodía, llevará tres horas mirando fijamente el enorme glaciar.'::text),
(400379,44487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, il ... l''immense glacier pendant trois heures.'::text,'aura fixé'::text,'sera en train de fixer'::text,'aura fixé'::text,'D''ici midi, il aura fixé l''immense glacier pendant trois heures.'::text),
(400382,44487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğleye kadar üç saattir devasa buzula ...'::text,'bakıyor olacak'::text,'bakıyor olacak'::text,'bakmış olacak'::text,'Öğleye kadar üç saattir devasa buzula bakıyor olacak.'::text),
(400383,44487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre már három órája ... a hatalmas gleccsert.'::text,'bámulja'::text,'bámulja'::text,'bámulja'::text,'Délre már három órája bámulja a hatalmas gleccsert.'::text),
(400386,44488,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein winziger Gletscher, klar. Hätte er ein breiteres Objektiv mitgebracht, ... das Foto das riesige Eis gezeigt.'::text,'hätte'::text,'wird'::text,'zeigte'::text,'Ein winziger Gletscher, klar. Hätte er ein breiteres Objektiv mitgebracht, hätte das Foto das riesige Eis gezeigt.'::text),
(400390,44488,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Крихітний льодовик, звісно. Якби він узяв ширший об''єктив, фото ... цей величезний лід.'::text,'показало б'::text,'покаже'::text,'показало'::text,'Крихітний льодовик, звісно. Якби він узяв ширший об''єктив, фото показало б цей величезний лід.'::text),
(400389,44488,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un glaciar diminuto, obviamente. Si hubiera traído un objetivo más ancho, la foto ... el enorme hielo.'::text,'habría mostrado'::text,'mostrará'::text,'mostró'::text,'Un glaciar diminuto, obviamente. Si hubiera traído un objetivo más ancho, la foto habría mostrado el enorme hielo.'::text),
(400388,44488,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un glacier minuscule, évidemment. S''il avait pris un objectif plus large, la photo ... l''immense glace.'::text,'aurait montré'::text,'montrera'::text,'a montré'::text,'Un glacier minuscule, évidemment. S''il avait pris un objectif plus large, la photo aurait montré l''immense glace.'::text),
(400391,44488,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minicik bir buzul, tabii ki. Daha geniş bir objektif getirseydi fotoğraf o devasa buzu ...'::text,'gösterirdi'::text,'gösterecek'::text,'gösterdi'::text,'Minicik bir buzul, tabii ki. Daha geniş bir objektif getirseydi fotoğraf o devasa buzu gösterirdi.'::text),
(400392,44488,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Apró gleccser, nyilván. Ha szélesebb objektívet hozott volna, a fotó ... a hatalmas jeget.'::text,'megmutatta volna'::text,'megmutatja'::text,'megmutatta'::text,'Apró gleccser, nyilván. Ha szélesebb objektívet hozott volna, a fotó megmutatta volna a hatalmas jeget.'::text),
(400395,44489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein leicht großer Eiswürfel. Wäre er nicht hergeflogen, ... er jetzt nicht auf diesen riesigen Gletscher schauen.'::text,'würde'::text,'hätte'::text,'wird'::text,'Ein leicht großer Eiswürfel. Wäre er nicht hergeflogen, würde er jetzt nicht auf diesen riesigen Gletscher schauen.'::text),
(400399,44489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи великий кубик льоду. Якби він сюди не прилетів, він зараз не ... на цей величезний льодовик.'::text,'дивився б'::text,'дивився б'::text,'дивитиметься'::text,'Трохи великий кубик льоду. Якби він сюди не прилетів, він зараз не дивився б на цей величезний льодовик.'::text),
(400398,44489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un cubito de hielo algo grande. Si no hubiera volado hasta aquí, ahora no ... este enorme glaciar.'::text,'estaría mirando'::text,'habría mirado'::text,'mirará'::text,'Un cubito de hielo algo grande. Si no hubiera volado hasta aquí, ahora no estaría mirando este enorme glaciar.'::text),
(400397,44489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un glaçon légèrement grand. S''il n''était pas venu en avion, il ... pas ce glacier immense en ce moment.'::text,'ne regarderait'::text,'n''aurait regardé'::text,'ne regardera'::text,'Un glaçon légèrement grand. S''il n''était pas venu en avion, il ne regarderait pas ce glacier immense en ce moment.'::text),
(400400,44489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hafif büyükçe bir buz küpü. Buraya uçmasaydı şu an bu devasa buzula ...'::text,'bakıyor olmazdı'::text,'bakmamış olurdu'::text,'bakmayacak'::text,'Hafif büyükçe bir buz küpü. Buraya uçmasaydı şu an bu devasa buzula bakıyor olmazdı.'::text),
(400401,44489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Enyhén nagy jégkocka. Ha nem repült volna ide, most nem ... ezt a hatalmas gleccsert.'::text,'nézné'::text,'nézte volna'::text,'fogja nézni'::text,'Enyhén nagy jégkocka. Ha nem repült volna ide, most nem nézné ezt a hatalmas gleccsert.'::text),
(400404,44490,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass dieser riesige Gletscher seit Tausenden von Jahren ..., und jetzt schmilzt er für immer!'::text,'dort gestanden hat'::text,'dort steht'::text,'stehend'::text,'Man glaubt, dass dieser riesige Gletscher seit Tausenden von Jahren dort gestanden hat, und jetzt schmilzt er für immer!'::text),
(400408,44490,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що цей величезний льодовик ... тисячі років, а тепер він тане назавжди!'::text,'простояв'::text,'стоїть'::text,'стоячи'::text,'Вважається, що цей величезний льодовик простояв тисячі років, а тепер він тане назавжди!'::text),
(400407,44490,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se cree que este enorme glaciar ... durante miles de años, y ahora se está derritiendo para siempre!'::text,'ha permanecido'::text,'permanece'::text,'permaneciendo'::text,'¡Se cree que este enorme glaciar ha permanecido durante miles de años, y ahora se está derritiendo para siempre!'::text),
(400406,44490,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que cet immense glacier ... là pendant des milliers d''années, et maintenant il fond pour toujours !'::text,'est resté'::text,'reste'::text,'restant'::text,'On pense que cet immense glacier est resté là pendant des milliers d''années, et maintenant il fond pour toujours !'::text),
(400409,44490,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu devasa buzulun binlerce yıldır orada ... düşünülüyor ve şimdi sonsuza dek eriyor!'::text,'durduğu'::text,'durduğu'::text,'durarak'::text,'Bu devasa buzulun binlerce yıldır orada durduğu düşünülüyor ve şimdi sonsuza dek eriyor!'::text),
(400410,44490,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy ez a hatalmas gleccser évezredek óta ..., és most örökre elolvad!'::text,'ott áll'::text,'ott áll'::text,'állva'::text,'Úgy tartják, hogy ez a hatalmas gleccser évezredek óta ott áll, és most örökre elolvad!'::text),
(400413,44491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er bestand darauf, den riesigen Gletscher allein ..., egal wie furchtbar kalt es war!'::text,'zu sehen'::text,'zu sehen'::text,'sehen'::text,'Er bestand darauf, den riesigen Gletscher allein zu sehen, egal wie furchtbar kalt es war!'::text),
(400417,44491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він наполіг на тому, щоб ... величезний льодовик сам, попри моторошний холод!'::text,'побачити'::text,'побачити'::text,'побачити'::text,'Він наполіг на тому, щоб побачити величезний льодовик сам, попри моторошний холод!'::text),
(400416,44491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Insistió en ... el enorme glaciar solo, sin importar el frío aterrador!'::text,'ver'::text,'ver'::text,'ver'::text,'¡Insistió en ver el enorme glaciar solo, sin importar el frío aterrador!'::text),
(400415,44491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a tenu à ... l''immense glacier seul, malgré le froid terrifiant !'::text,'voir'::text,'voir'::text,'voir'::text,'Il a tenu à voir l''immense glacier seul, malgré le froid terrifiant !'::text),
(400418,44491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korkunç soğuğa rağmen devasa buzulu tek başına ... ısrar etti!'::text,'görmekte'::text,'görmeye'::text,'gör'::text,'Korkunç soğuğa rağmen devasa buzulu tek başına görmekte ısrar etti!'::text),
(400419,44491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ragaszkodott hozzá, hogy egyedül ... a hatalmas gleccsert, bármilyen ijesztő is a hideg!'::text,'lássa'::text,'lássa'::text,'lássa'::text,'Ragaszkodott hozzá, hogy egyedül lássa a hatalmas gleccsert, bármilyen ijesztő is a hideg!'::text),
(400431,44493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie in seinem Leben ... eine so riesige Eiswand gesehen.'::text,'hatte er'::text,'er hatte'::text,'sah er'::text,'Nie in seinem Leben hatte er eine so riesige Eiswand gesehen.'::text),
(400435,44493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи в житті ... такої величезної стіни льоду.'::text,'він не бачив'::text,'він не бачив'::text,'він не бачив'::text,'Ніколи в житті він не бачив такої величезної стіни льоду.'::text),
(400434,44493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca en su vida ... una pared de hielo tan enorme.'::text,'había visto'::text,'había visto'::text,'vio'::text,'Nunca en su vida había visto una pared de hielo tan enorme.'::text),
(400433,44493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais de sa vie ... un mur de glace aussi immense.'::text,'n''avait-il vu'::text,'il n''avait vu'::text,'ne vit-il'::text,'Jamais de sa vie n''avait-il vu un mur de glace aussi immense.'::text),
(400436,44493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayatında hiç bu kadar devasa bir buz duvarı ...'::text,'görmemişti'::text,'görmemişti'::text,'görmedi'::text,'Hayatında hiç bu kadar devasa bir buz duvarı görmemişti.'::text),
(400437,44493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha életében ... ilyen hatalmas jégfalat.'::text,'nem látott'::text,'nem látott'::text,'nem látott'::text,'Soha életében nem látott ilyen hatalmas jégfalat.'::text),
(400440,44494,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er muss jemanden dazu bringen, ein Pic von ihm mit dem riesigen Gletscher ..., ohne Witz.'::text,'zu machen'::text,'machen'::text,'machend'::text,'Yo, er muss jemanden dazu bringen, ein Pic von ihm mit dem riesigen Gletscher zu machen, ohne Witz.'::text),
(400444,44494,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, йому треба когось попросити ... фотку з тим величезним льодовиком, без брехні.'::text,'зробити'::text,'зробити'::text,'роблячи'::text,'Йо, йому треба когось попросити зробити фотку з тим величезним льодовиком, без брехні.'::text),
(400443,44494,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, tiene que conseguir que alguien le ... una foto con ese glaciar enorme, sin mentir.'::text,'haga'::text,'hacer'::text,'haciendo'::text,'Ey, tiene que conseguir que alguien le haga una foto con ese glaciar enorme, sin mentir.'::text),
(400442,44494,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, il doit trouver quelqu''un pour lui ... une photo avec cet immense glacier, sans mentir.'::text,'prendre'::text,'prendre'::text,'prenant'::text,'Yo, il doit trouver quelqu''un pour lui prendre une photo avec cet immense glacier, sans mentir.'::text),
(400445,44494,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, birine o devasa buzulla fotoğrafını ... lazım, yemin ederim.'::text,'çektirmesi'::text,'çektir'::text,'çektirerek'::text,'Yo, birine o devasa buzulla fotoğrafını çektirmesi lazım, yemin ederim.'::text),
(400446,44494,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, valakivel ... kell egy képet magáról azzal a hatalmas gleccserrel, komolyan.'::text,'csináltatnia'::text,'csináltat'::text,'csináltatva'::text,'Figyu, valakivel csináltatnia kell egy képet magáról azzal a hatalmas gleccserrel, komolyan.'::text),
(400449,44495,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mann, ich wünschte, ich ... jetzt gerade dort bei dem riesigen Gletscher, echt.'::text,'wäre'::text,'bin'::text,'werde sein'::text,'Mann, ich wünschte, ich wäre jetzt gerade dort bei dem riesigen Gletscher, echt.'::text),
(400453,44495,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, от би я ... там просто зараз біля того величезного льодовика, реально.'::text,'був'::text,'є'::text,'буду'::text,'Чувак, от би я був там просто зараз біля того величезного льодовика, реально.'::text),
(400452,44495,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ojalá ... allí ahora mismo con ese glaciar enorme, en serio.'::text,'estuviera'::text,'estoy'::text,'estaré'::text,'Tío, ojalá estuviera allí ahora mismo con ese glaciar enorme, en serio.'::text),
(400451,44495,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, j''aimerais bien ... là-bas en ce moment avec cet immense glacier, grave.'::text,'être'::text,'être'::text,'être'::text,'Mec, j''aimerais bien être là-bas en ce moment avec cet immense glacier, grave.'::text),
(400454,44495,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, keşke şu an orada o devasa buzulun yanında ..., cidden.'::text,'olsam'::text,NULL::text,'olacağım'::text,'Kanka, keşke şu an orada o devasa buzulun yanında olsam, cidden.'::text),
(400455,44495,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, bárcsak ... most ott annál a hatalmas gleccsernél, komolyan.'::text,'lennék'::text,'vagyok'::text,'leszek'::text,'Tesó, bárcsak lennék most ott annál a hatalmas gleccsernél, komolyan.'::text),
(400458,44496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gletscher, ... Größe ihn überraschte, ist zu riesig für ein einziges Foto.'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Gletscher, dessen Größe ihn überraschte, ist zu riesig für ein einziges Foto.'::text),
(400462,44496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Льодовик, ... розмір його здивував, завеликий, щоб поміститися на одне фото.'::text,'чий'::text,'який'::text,'що'::text,'Льодовик, чий розмір його здивував, завеликий, щоб поміститися на одне фото.'::text),
(400461,44496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El glaciar, ... tamaño lo sorprendió, es demasiado enorme para caber en una foto.'::text,'cuyo'::text,'que'::text,'el cual'::text,'El glaciar, cuyo tamaño lo sorprendió, es demasiado enorme para caber en una foto.'::text),
(400460,44496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le glacier, ... la taille l''a surpris, est trop immense pour tenir sur une seule photo.'::text,'dont'::text,'qui'::text,'que'::text,'Le glacier, dont la taille l''a surpris, est trop immense pour tenir sur une seule photo.'::text),
(400463,44496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyüklüğü onu ... buzul tek bir fotoğrafa sığmayacak kadar devasa.'::text,'şaşırtan'::text,NULL::text,NULL::text,'Büyüklüğü onu şaşırtan buzul tek bir fotoğrafa sığmayacak kadar devasa.'::text),
(400464,44496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gleccser, ... mérete meglepte, túl hatalmas ahhoz, hogy egy fotóra kiférjen.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A gleccser, amelynek a mérete meglepte, túl hatalmas ahhoz, hogy egy fotóra kiférjen.'::text),
(333759,37085,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächste Woche um diese Zeit ... er schon das nächste Barbecue schmeißen. Die Rippchen brauchen ihn eindeutig.'::text,'wird'::text,'wird'::text,'schmeißt'::text,'Nächste Woche um diese Zeit wird er schon das nächste Barbecue schmeißen. Die Rippchen brauchen ihn eindeutig.'::text),
(333763,37085,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного тижня в цей час він ... ще одне барбекю. Реберця явно без нього не можуть.'::text,'влаштовуватиме'::text,'влаштує'::text,'влаштовує'::text,'Наступного тижня в цей час він влаштовуватиме ще одне барбекю. Реберця явно без нього не можуть.'::text),
(333762,37085,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semana que viene a esta hora ... otra barbacoa. Está claro que las costillas lo necesitan.'::text,'estará organizando'::text,'organizará'::text,'organiza'::text,'La semana que viene a esta hora estará organizando otra barbacoa. Está claro que las costillas lo necesitan.'::text),
(333761,37085,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La semaine prochaine à la même heure, il ... un autre barbecue. Les côtes ont clairement besoin de lui.'::text,'sera en train d''organiser'::text,'organisera'::text,'organise'::text,'La semaine prochaine à la même heure, il sera en train d''organiser un autre barbecue. Les côtes ont clairement besoin de lui.'::text),
(333764,37085,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haftaya bu saatte başka bir barbekü ..., belli ki kaburgaların ona ihtiyacı var.'::text,'düzenliyor olacak'::text,'düzenleyecek'::text,'düzenliyor'::text,'Haftaya bu saatte başka bir barbekü düzenliyor olacak, belli ki kaburgaların ona ihtiyacı var.'::text),
(333765,37085,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő héten ilyenkor ... már egy újabb barbecue-t. A bordáknak egyértelműen szükségük van rá.'::text,'fog rendezni'::text,'rendez'::text,'rendez'::text,'Jövő héten ilyenkor fog rendezni már egy újabb barbecue-t. A bordáknak egyértelműen szükségük van rá.'::text),
(333768,37086,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schwört, er ... die Rippchen beim nächsten Barbecue nicht. Offensichtlich ein bescheidener Koch.'::text,'verbrennt'::text,'wird verbrennen'::text,'verbrennt gerade'::text,'Er schwört, er verbrennt die Rippchen beim nächsten Barbecue nicht. Offensichtlich ein bescheidener Koch.'::text),
(333772,37086,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він клянеться, що ... реберця на наступному барбекю. Очевидно, скромний кухар.'::text,'не спалить'::text,'не палитиме'::text,'не палить'::text,'Він клянеться, що не спалить реберця на наступному барбекю. Очевидно, скромний кухар.'::text),
(333771,37086,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jura que no ... las costillas en la próxima barbacoa. Obviamente, un chef humilde.'::text,'quemará'::text,'estará quemando'::text,'está quemando'::text,'Jura que no quemará las costillas en la próxima barbacoa. Obviamente, un chef humilde.'::text),
(333770,37086,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il jure qu''il ... les côtes au prochain barbecue. Visiblement un chef modeste.'::text,'ne brûlera pas'::text,'ne sera pas en train de brûler'::text,'ne brûle pas'::text,'Il jure qu''il ne brûlera pas les côtes au prochain barbecue. Visiblement un chef modeste.'::text),
(333773,37086,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir sonraki barbeküde kaburgaları ... yemin ediyor. Belli ki alçakgönüllü bir şef.'::text,'yakmayacağına'::text,'yakıyor olmayacağına'::text,'yakmadığına'::text,'Bir sonraki barbeküde kaburgaları yakmayacağına yemin ediyor. Belli ki alçakgönüllü bir şef.'::text),
(333774,37086,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megesküszik, hogy a következő barbecue-n ... oda a bordákat. Nyilván szerény séf.'::text,'nem égeti'::text,'nem fogja égetni'::text,'nem égeti'::text,'Megesküszik, hogy a következő barbecue-n nem égeti oda a bordákat. Nyilván szerény séf.'::text),
(333777,37087,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn die Kohlen heiß ..., werden die Barbecue-Rippchen viel schneller gar, echt.'::text,'sind'::text,'wären'::text,'sein werden'::text,'Bro, wenn die Kohlen heiß sind, werden die Barbecue-Rippchen viel schneller gar, echt.'::text),
(333781,37087,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо вугілля ... гаряче, реберця на барбекю готуються набагато швидше, реально.'::text,''::text,'було'::text,'буде'::text,'Бро, якщо вугілля гаряче, реберця на барбекю готуються набагато швидше, реально.'::text),
(333780,37087,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si las brasas ... calientes, las costillas de la barbacoa se hacen mucho más rápido, en serio.'::text,'están'::text,'estuvieran'::text,'estarán'::text,'Bro, si las brasas están calientes, las costillas de la barbacoa se hacen mucho más rápido, en serio.'::text),
(333779,37087,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si les braises ... chaudes, les côtes au barbecue cuisent bien plus vite, grave.'::text,'sont'::text,'étaient'::text,'seront'::text,'Frère, si les braises sont chaudes, les côtes au barbecue cuisent bien plus vite, grave.'::text),
(333782,37087,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kömürler sıcak ..., barbekü kaburgaları çok daha hızlı pişer, cidden.'::text,'olursa'::text,'olsaydı'::text,'olacaksa'::text,'Kanka, kömürler sıcak olursa, barbekü kaburgaları çok daha hızlı pişer, cidden.'::text),
(333783,37087,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha a szén forró ..., a barbecue-bordák sokkal gyorsabban sülnek, komolyan.'::text,''::text,'lenne'::text,'lesz'::text,'Tesó, ha a szén forró, a barbecue-bordák sokkal gyorsabban sülnek, komolyan.'::text),
(333786,37088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alle jubeln, also ... dieses Barbecue legendär sein, ohne Witz.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Alle jubeln, also muss dieses Barbecue legendär sein, ohne Witz.'::text),
(333790,37088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі радіють, тож це барбекю ... бути легендарним, без брехні.'::text,'мусить'::text,'не може'::text,'повинно'::text,'Усі радіють, тож це барбекю мусить бути легендарним, без брехні.'::text),
(333789,37088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todos están aplaudiendo, así que esta barbacoa ... ser legendaria, sin mentir.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Todos están aplaudiendo, así que esta barbacoa debe de ser legendaria, sin mentir.'::text),
(333788,37088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le monde applaudit, donc ce barbecue ... être légendaire, sans mentir.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Tout le monde applaudit, donc ce barbecue doit être légendaire, sans mentir.'::text),
(333791,37088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herkes tezahürat yapıyor, demek ki bu barbekü efsane ..., yemin ederim.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Herkes tezahürat yapıyor, demek ki bu barbekü efsane olmalı, yemin ederim.'::text),
(333792,37088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindenki ujjong, szóval ez a barbecue ... legendás, komolyan.'::text,'biztos'::text,'nem lehet'::text,'talán'::text,'Mindenki ujjong, szóval ez a barbecue biztos legendás, komolyan.'::text),
(333795,37089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Barbecue, ... Budget 200 Euro betrug, machte den ganzen Tisch satt.'::text,'dessen'::text,'das'::text,'welches'::text,'Das Barbecue, dessen Budget 200 Euro betrug, machte den ganzen Tisch satt.'::text),
(333799,37089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Барбекю, ... бюджет становив 200 євро, нагодувало весь стіл.'::text,'чий'::text,'яке'::text,'що'::text,'Барбекю, чий бюджет становив 200 євро, нагодувало весь стіл.'::text),
(333798,37089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La barbacoa, ... presupuesto fue de 200 euros, dio de comer a toda la mesa.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La barbacoa, cuyo presupuesto fue de 200 euros, dio de comer a toda la mesa.'::text),
(333797,37089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le barbecue, ... le budget était de 200 euros, a nourri toute la table.'::text,'dont'::text,'qui'::text,'que'::text,'Le barbecue, dont le budget était de 200 euros, a nourri toute la table.'::text),
(333800,37089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçesi 200 euro ... barbekü bütün masayı doyurdu.'::text,'olan'::text,NULL::text,NULL::text,'Bütçesi 200 euro olan barbekü bütün masayı doyurdu.'::text),
(333801,37089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barbecue, ... költségvetése 200 euró volt, az egész asztalt jóllakatta.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A barbecue, amelynek a költségvetése 200 euró volt, az egész asztalt jóllakatta.'::text),
(333813,37091,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Kochen über Kohlen ... früher eine Notwendigkeit; das Barbecue ist heute typischerweise ein gesellschaftliches Ereignis.'::text,'war'::text,'wäre'::text,'war gewohnt zu sein'::text,'Das Kochen über Kohlen war früher eine Notwendigkeit; das Barbecue ist heute typischerweise ein gesellschaftliches Ereignis.'::text),
(333817,37091,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Приготування їжі на вугіллі ... необхідністю; барбекю тепер зазвичай є соціальною подією.'::text,'колись було'::text,'було б'::text,'звикло бути'::text,'Приготування їжі на вугіллі колись було необхідністю; барбекю тепер зазвичай є соціальною подією.'::text),
(333816,37091,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cocinar sobre brasas ... ser una necesidad; la barbacoa es hoy normalmente un evento social.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Cocinar sobre brasas solía ser una necesidad; la barbacoa es hoy normalmente un evento social.'::text),
(333815,37091,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuisiner sur des braises ... une nécessité ; le barbecue est aujourd''hui généralement un événement social.'::text,'était autrefois'::text,'serait'::text,'avait l''habitude d''être'::text,'Cuisiner sur des braises était autrefois une nécessité ; le barbecue est aujourd''hui généralement un événement social.'::text),
(333818,37091,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kömür üzerinde pişirmek eskiden bir zorunluluk ...; barbekü artık genellikle sosyal bir etkinlik.'::text,'idi'::text,'olurdu'::text,'olmaya alışkındı'::text,'Kömür üzerinde pişirmek eskiden bir zorunluluk idi; barbekü artık genellikle sosyal bir etkinlik.'::text),
(333819,37091,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A parázson való főzés régen szükségszerűség ...; a barbecue ma jellemzően társasági esemény.'::text,'volt'::text,'lett volna'::text,'hozzá volt szokva lenni'::text,'A parázson való főzés régen szükségszerűség volt; a barbecue ma jellemzően társasági esemény.'::text),
(333822,37092,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er liebt es, die Rippchen bei jedem Familien-Barbecue zu ...'::text,'grillen'::text,'grillen'::text,'grillen'::text,'Er liebt es, die Rippchen bei jedem Familien-Barbecue zu grillen.'::text),
(333826,37092,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому подобається ... реберця на кожному сімейному барбекю.'::text,'смажити на грилі'::text,'смажити на грилі'::text,'смажити на грилі'::text,'Йому подобається смажити на грилі реберця на кожному сімейному барбекю.'::text),
(333825,37092,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le encanta ... las costillas en cada barbacoa familiar.'::text,'asar'::text,'asar'::text,'asar'::text,'Le encanta asar las costillas en cada barbacoa familiar.'::text),
(333824,37092,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il adore ... les côtes à chaque barbecue en famille.'::text,'griller'::text,'griller'::text,'griller'::text,'Il adore griller les côtes à chaque barbecue en famille.'::text),
(333827,37092,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her aile barbeküsünde kaburgaları ... seviyor.'::text,'ızgara yapmayı'::text,'ızgara yapmayı'::text,'ızgara yap'::text,'Her aile barbeküsünde kaburgaları ızgara yapmayı seviyor.'::text),
(333828,37092,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Imádja ... a bordákat minden családi barbecue-n.'::text,'grillezni'::text,'grillezni'::text,'grillezni'::text,'Imádja grillezni a bordákat minden családi barbecue-n.'::text),
(333831,37093,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Barbecue riecht super, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Das Barbecue riecht super, oder?'::text),
(333835,37093,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Барбекю чудово пахне, ...?'::text,'правда'::text,'правда'::text,'правда'::text,'Барбекю чудово пахне, правда?'::text),
(333834,37093,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La barbacoa huele genial, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'La barbacoa huele genial, ¿verdad?'::text),
(333833,37093,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le barbecue sent super bon, ... ?'::text,'non'::text,'non'::text,'non'::text,'Le barbecue sent super bon, non ?'::text),
(333836,37093,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Barbekü harika kokuyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Barbekü harika kokuyor, değil mi?'::text),
(333837,37093,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barbecue-nak isteni illata van, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A barbecue-nak isteni illata van, ugye?'::text),
(333840,37094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gäste ... am Tisch, seit das Barbecue angefangen hat.'::text,'sitzen'::text,'sitzen'::text,'sitzen'::text,'Die Gäste sitzen am Tisch, seit das Barbecue angefangen hat.'::text),
(333844,37094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості ... за столом відтоді, як почалося барбекю.'::text,'сидять'::text,'сидять'::text,'сидять'::text,'Гості сидять за столом відтоді, як почалося барбекю.'::text),
(333843,37094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los invitados ... a la mesa desde que empezó la barbacoa.'::text,'llevan sentados'::text,'están sentados'::text,'se sientan'::text,'Los invitados llevan sentados a la mesa desde que empezó la barbacoa.'::text),
(333842,37094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les invités ... à table depuis le début du barbecue.'::text,'sont assis'::text,'sont assis'::text,'sont assis'::text,'Les invités sont assis à table depuis le début du barbecue.'::text),
(333845,37094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Konuklar barbekü başladığından beri masada ...'::text,'oturuyor'::text,'oturuyor'::text,'oturur'::text,'Konuklar barbekü başladığından beri masada oturuyor.'::text),
(333846,37094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek azóta ... az asztalnál, hogy elkezdődött a barbecue.'::text,'ülnek'::text,'ülnek'::text,'ülnek'::text,'A vendégek azóta ülnek az asztalnál, hogy elkezdődött a barbecue.'::text),
(331581,36843,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, der Polizist hat beim Festnehmen nicht gelacht, und ...'::text,'der Einbrecher auch nicht.'::text,'der Einbrecher auch.'::text,'der Einbrecher auch nicht.'::text,'Okay, also ich hab gehört, der Polizist hat beim Festnehmen nicht gelacht, und der Einbrecher auch nicht.'::text),
(331585,36843,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що поліцейський не сміявся під час арешту, і ...'::text,'грабіжник теж ні.'::text,'грабіжник теж.'::text,'грабіжник теж ні.'::text,'Коротше, я чула, що поліцейський не сміявся під час арешту, і грабіжник теж ні.'::text),
(331584,36843,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me han dicho que el policía no se rió durante el arresto, y ...'::text,'el ladrón tampoco.'::text,'el ladrón también.'::text,'el ladrón tampoco.'::text,'Vale, me han dicho que el policía no se rió durante el arresto, y el ladrón tampoco.'::text),
(331583,36843,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, il paraît que le policier n''a pas ri pendant l''arrestation, et ...'::text,'le cambrioleur non plus.'::text,'le cambrioleur aussi.'::text,'le cambrioleur non plus.'::text,'Bon, il paraît que le policier n''a pas ri pendant l''arrestation, et le cambrioleur non plus.'::text),
(331586,36843,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duyduğuma göre polis tutuklama sırasında gülmemiş, ...'::text,'hırsız da gülmemiş.'::text,'hırsız da.'::text,'hırsız da gülmemiş.'::text,'Tamam, duyduğuma göre polis tutuklama sırasında gülmemiş, hırsız da gülmemiş.'::text),
(331587,36843,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval azt hallottam, hogy a rendőr nem nevetett a letartóztatás közben, és ...'::text,'a betörő sem.'::text,'a betörő is.'::text,'a betörő sem.'::text,'Oké, szóval azt hallottam, hogy a rendőr nem nevetett a letartóztatás közben, és a betörő sem.'::text),
(331590,36844,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis das Polizeiauto losfährt, wird der Polizist den falschen Einbrecher ...'::text,'festgenommen haben'::text,'festnehmen'::text,'festnehmen'::text,'Bis das Polizeiauto losfährt, wird der Polizist den falschen Einbrecher festgenommen haben.'::text),
(331594,36844,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки поліцейська машина поїде, поліцейський ... фальшивого грабіжника.'::text,'заарештує'::text,'заарештує'::text,'арештовуватиме'::text,'Поки поліцейська машина поїде, поліцейський заарештує фальшивого грабіжника.'::text),
(331593,36844,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se vaya el coche patrulla, el policía ... al falso ladrón.'::text,'habrá arrestado'::text,'arrestará'::text,'estará arrestando'::text,'Para cuando se vaya el coche patrulla, el policía habrá arrestado al falso ladrón.'::text),
(331592,36844,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que la voiture de police parte, le policier ... le faux cambrioleur.'::text,'aura arrêté'::text,'arrêtera'::text,'sera en train d''arrêter'::text,'D''ici à ce que la voiture de police parte, le policier aura arrêté le faux cambrioleur.'::text),
(331595,36844,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Polis arabası gidene kadar polis sahte hırsızı ...'::text,'tutuklamış olacak'::text,'tutuklayacak'::text,'tutukluyor olacak'::text,'Polis arabası gidene kadar polis sahte hırsızı tutuklamış olacak.'::text),
(331596,36844,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a rendőrautó elindul, a rendőr ... a kamu betörőt.'::text,'letartóztatja'::text,'le fogja tartóztatni'::text,'épp letartóztatja'::text,'Mire a rendőrautó elindul, a rendőr letartóztatja a kamu betörőt.'::text),
(331608,36846,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Einbrecher bestritt, die Edelsteine ..., bevor der Polizist ihn festnahm.'::text,'gestohlen zu haben'::text,'zu stehlen'::text,'gestohlen'::text,'Der Einbrecher bestritt, die Edelsteine gestohlen zu haben, bevor der Polizist ihn festnahm.'::text),
(331612,36846,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Грабіжник заперечив, що ... коштовності, перш ніж поліцейський його заарештував.'::text,'вкрав'::text,'вкрасти'::text,'вкрадені'::text,'Грабіжник заперечив, що вкрав коштовності, перш ніж поліцейський його заарештував.'::text),
(331611,36846,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ladrón negó ... las joyas antes de que el policía lo arrestara.'::text,'haber robado'::text,'robar'::text,'robado'::text,'El ladrón negó haber robado las joyas antes de que el policía lo arrestara.'::text),
(331610,36846,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le cambrioleur a nié ... les pierres précieuses avant que le policier ne l''arrête.'::text,'avoir volé'::text,'voler'::text,'volé'::text,'Le cambrioleur a nié avoir volé les pierres précieuses avant que le policier ne l''arrête.'::text),
(331613,36846,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hırsız, polis onu tutuklamadan önce mücevherleri ... inkâr etti.'::text,'çaldığını'::text,'çalmayı'::text,'çalınmış'::text,'Hırsız, polis onu tutuklamadan önce mücevherleri çaldığını inkâr etti.'::text),
(331614,36846,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A betörő tagadta, hogy ... a drágaköveket, mielőtt a rendőr letartóztatta.'::text,'ellopta'::text,'ellopni'::text,'ellopott'::text,'A betörő tagadta, hogy ellopta a drágaköveket, mielőtt a rendőr letartóztatta.'::text),
(331617,36847,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Polizist ... die Tasche vor der Festnahme schließen sollen; 12 Gummihühner gingen aus dem Bestand verloren.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Der Polizist hätte die Tasche vor der Festnahme schließen sollen; 12 Gummihühner gingen aus dem Bestand verloren.'::text),
(331621,36847,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поліцейський ... сумку до арешту; зі складу зникло 12 гумових курчат.'::text,'мав закрити'::text,'мабуть, закрив'::text,'не міг закрити'::text,'Поліцейський мав закрити сумку до арешту; зі складу зникло 12 гумових курчат.'::text),
(331620,36847,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El policía ... la bolsa antes del arresto; se perdieron 12 pollos de goma del inventario.'::text,'debería haber cerrado'::text,'debe de haber cerrado'::text,'no puede haber cerrado'::text,'El policía debería haber cerrado la bolsa antes del arresto; se perdieron 12 pollos de goma del inventario.'::text),
(331619,36847,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le policier ... le sac avant l''arrestation ; 12 poulets en caoutchouc ont disparu de l''inventaire.'::text,'aurait dû fermer'::text,'a dû fermer'::text,'n''a pas pu fermer'::text,'Le policier aurait dû fermer le sac avant l''arrestation ; 12 poulets en caoutchouc ont disparu de l''inventaire.'::text),
(331622,36847,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Polis tutuklamadan önce çantayı ...; envanterden 12 lastik tavuk kayboldu.'::text,'kapatmalıydı'::text,'kapatmış olmalı'::text,'kapatmış olamaz'::text,'Polis tutuklamadan önce çantayı kapatmalıydı; envanterden 12 lastik tavuk kayboldu.'::text),
(331623,36847,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A letartóztatás előtt ... a táskát; 12 gumicsirke eltűnt a készletből.'::text,'a rendőrnek be kellett volna zárnia'::text,'a rendőr biztosan bezárta'::text,'a rendőr nem zárhatta be'::text,'A letartóztatás előtt a rendőrnek be kellett volna zárnia a táskát; 12 gumicsirke eltűnt a készletből.'::text),
(331626,36848,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach der Festnahme ließ der Polizist den Einbrecher hinten ins Polizeiauto ...'::text,'einsteigen'::text,'einsteigen'::text,'einsteigend'::text,'Nach der Festnahme ließ der Polizist den Einbrecher hinten ins Polizeiauto einsteigen.'::text),
(331630,36848,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після арешту поліцейський змусив грабіжника ... на заднє сидіння поліцейської машини.'::text,'сісти'::text,'сісти'::text,'сідаючи'::text,'Після арешту поліцейський змусив грабіжника сісти на заднє сидіння поліцейської машини.'::text),
(331629,36848,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tras el arresto, el policía hizo que el ladrón ... en la parte trasera del coche patrulla.'::text,'se subiera'::text,'subirse'::text,'subiéndose'::text,'Tras el arresto, el policía hizo que el ladrón se subiera en la parte trasera del coche patrulla.'::text),
(331628,36848,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après l''arrestation, le policier a fait ... le cambrioleur à l''arrière de la voiture de police.'::text,'monter'::text,'monter'::text,'montant'::text,'Après l''arrestation, le policier a fait monter le cambrioleur à l''arrière de la voiture de police.'::text),
(331631,36848,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tutuklamadan sonra polis hırsızı polis arabasının arkasına ...'::text,'bindirdi'::text,'bindirdi'::text,'bindirerek'::text,'Tutuklamadan sonra polis hırsızı polis arabasının arkasına bindirdi.'::text),
(331632,36848,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A letartóztatás után a rendőr ... a betörőt a rendőrautó hátsó ülésére.'::text,'beültette'::text,'beültette'::text,'beültetve'::text,'A letartóztatás után a rendőr beültette a betörőt a rendőrautó hátsó ülésére.'::text),
(331635,36849,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Verdächtige wünscht sich vermutlich, er ... die Tasche vor der Festnahme geschlossen.'::text,'hätte'::text,'schloss'::text,'würde'::text,'Der Verdächtige wünscht sich vermutlich, er hätte die Tasche vor der Festnahme geschlossen.'::text),
(331639,36849,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підозрюваний, імовірно, хотів би, щоб він ... сумку до арешту.'::text,'закрив'::text,'закрив'::text,'закривав би'::text,'Підозрюваний, імовірно, хотів би, щоб він закрив сумку до арешту.'::text),
(331638,36849,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presumiblemente, el sospechoso desearía ... la bolsa antes de que se produjera el arresto.'::text,'haber cerrado'::text,'cerrar'::text,'cerrar'::text,'Presumiblemente, el sospechoso desearía haber cerrado la bolsa antes de que se produjera el arresto.'::text),
(331637,36849,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le suspect aimerait probablement ... le sac avant que l''arrestation ait lieu.'::text,'avoir fermé'::text,'fermer'::text,'fermer'::text,'Le suspect aimerait probablement avoir fermé le sac avant que l''arrestation ait lieu.'::text),
(331640,36849,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şüpheli muhtemelen keşke tutuklamadan önce çantayı ... diye düşünüyor.'::text,'kapatsaydım'::text,'kapatsam'::text,'kapatacağım'::text,'Şüpheli muhtemelen keşke tutuklamadan önce çantayı kapatsaydım diye düşünüyor.'::text),
(331641,36849,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyanúsított feltehetően azt kívánja, bárcsak ... a táskát a letartóztatás előtt.'::text,'bezárta volna'::text,'bezárná'::text,'bezárná'::text,'A gyanúsított feltehetően azt kívánja, bárcsak bezárta volna a táskát a letartóztatás előtt.'::text),
(331644,36850,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Polizist, ... Handschellen zuschnappten, verhaftete den Einbrecher für immer!'::text,'dessen'::text,'der'::text,'welcher'::text,'Der Polizist, dessen Handschellen zuschnappten, verhaftete den Einbrecher für immer!'::text),
(331648,36850,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поліцейський, ... кайданки клацнули, заарештував грабіжника назавжди!'::text,'чиї'::text,'який'::text,'котрий'::text,'Поліцейський, чиї кайданки клацнули, заарештував грабіжника назавжди!'::text),
(331647,36850,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El policía, ... esposas se cerraron con un clic, arrestó al ladrón para siempre!'::text,'cuyas'::text,'que'::text,'el cual'::text,'¡El policía, cuyas esposas se cerraron con un clic, arrestó al ladrón para siempre!'::text),
(331646,36850,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le policier, ... les menottes se sont refermées d''un clic, a arrêté le cambrioleur pour toujours !'::text,'dont'::text,'qui'::text,'lequel'::text,'Le policier, dont les menottes se sont refermées d''un clic, a arrêté le cambrioleur pour toujours !'::text),
(331649,36850,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kelepçeleri klik diye ... polis, hırsızı sonsuza dek tutukladı!'::text,'kapanan'::text,NULL::text,NULL::text,'Kelepçeleri klik diye kapanan polis, hırsızı sonsuza dek tutukladı!'::text),
(331650,36850,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendőr, ... bilincse kattanva bezárult, örökre letartóztatta a betörőt!'::text,'akinek a'::text,'aki'::text,'amely'::text,'A rendőr, akinek a bilincse kattanva bezárult, örökre letartóztatta a betörőt!'::text),
(331653,36851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Festnahme fielen ständig Gummihühner heraus, eine totale Katastrophe!'::text,'Während'::text,'Während'::text,'Außer wenn'::text,'Während der Festnahme fielen ständig Gummihühner heraus, eine totale Katastrophe!'::text),
(331657,36851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... арешту гумові курчата постійно випадали, повна катастрофа!'::text,'Під час'::text,'Поки'::text,'Якщо не'::text,'Під час арешту гумові курчата постійно випадали, повна катастрофа!'::text),
(331656,36851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... el arresto, los pollos de goma no paraban de caerse, un desastre total!'::text,'Durante'::text,'Mientras'::text,'A menos que'::text,'¡Durante el arresto, los pollos de goma no paraban de caerse, un desastre total!'::text),
(331655,36851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''arrestation, les poulets en caoutchouc n''arrêtaient pas de tomber, une catastrophe totale !'::text,'Pendant'::text,'Pendant que'::text,'À moins que'::text,'Pendant l''arrestation, les poulets en caoutchouc n''arrêtaient pas de tomber, une catastrophe totale !'::text),
(331658,36851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tutuklama ... lastik tavuklar durmadan düştü, tam bir felaket!'::text,'sırasında'::text,'iken'::text,'olmadıkça'::text,'Tutuklama sırasında lastik tavuklar durmadan düştü, tam bir felaket!'::text),
(331659,36851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A letartóztatás ... folyton potyogtak a gumicsirkék, totális katasztrófa!'::text,'alatt'::text,'miközben'::text,'hacsak nem'::text,'A letartóztatás alatt folyton potyogtak a gumicsirkék, totális katasztrófa!'::text),
(331662,36852,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis die Tür zugeht, ... der Polizist den Einbrecher festgenommen haben, und seine Karriere ist für immer vorbei!'::text,'wird'::text,'wird'::text,'nimmt'::text,'Bis die Tür zugeht, wird der Polizist den Einbrecher festgenommen haben, und seine Karriere ist für immer vorbei!'::text),
(331666,36852,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки двері зачиняться, поліцейський ... грабіжника, і його кар''єра назавжди скінчена!'::text,'заарештує'::text,'заарештує'::text,'арештовує'::text,'Поки двері зачиняться, поліцейський заарештує грабіжника, і його кар''єра назавжди скінчена!'::text),
(331665,36852,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando se cierre la puerta, el policía ... al ladrón, y su carrera se acabó para siempre!'::text,'habrá arrestado'::text,'arrestará'::text,'arresta'::text,'¡Para cuando se cierre la puerta, el policía habrá arrestado al ladrón, y su carrera se acabó para siempre!'::text),
(331664,36852,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que la porte se ferme, le policier ... le cambrioleur, et sa carrière est finie pour toujours !'::text,'aura arrêté'::text,'arrêtera'::text,'arrête'::text,'D''ici à ce que la porte se ferme, le policier aura arrêté le cambrioleur, et sa carrière est finie pour toujours !'::text),
(331667,36852,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kapı kapanana kadar polis hırsızı ... ve kariyeri sonsuza dek bitti!'::text,'tutuklamış olacak'::text,'tutuklayacak'::text,'tutukluyor'::text,'Kapı kapanana kadar polis hırsızı tutuklamış olacak ve kariyeri sonsuza dek bitti!'::text),
(331668,36852,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire becsukódik az ajtó, a rendőr ... a betörőt, és a karrierje örökre véget ér!'::text,'letartóztatja'::text,'le fogja tartóztatni'::text,'letartóztatja'::text,'Mire becsukódik az ajtó, a rendőr letartóztatja a betörőt, és a karrierje örökre véget ér!'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
